import { Book } from "@/lib/types";

export const proverbs: Book = {
  id: "proverbs",
  name: "Sprüche",
  shortName: "Spr",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Sprüche Salomos*, des Sohnes Davids, des Königs von Israel*,", heading: "Überschrift und Zweck des Buches: Unterweisung in der Weisheit", footnotes: ["℘ Kap. 10,1; 25,1; 1Kö 5,12", "℘ 1Chr 29,28; Pred 1,1; 12,9"] },
      { number: 2, text: "um zu erkennen Weisheit und Zucht, um zu verstehen verständige Worte*,", footnotes: ["℘ Kap. 4,1; 19,20"] },
      { number: 3, text: "um anzunehmen Zucht <mit> Einsicht*, <dazu> Gerechtigkeit, Recht und Aufrichtigkeit*,", footnotes: ["o. Zucht, <die> kluges Handeln <bewirkt>", "℘ Kap. 2,9; 22,21; Pred 12,10"] },
      { number: 4, text: "um Einfältigen* Klugheit zu geben, dem jungen Mann Erkenntnis und Besonnenheit*.", footnotes: ["o. Unerfahrenen; o. Unverständigen", "℘ Ps 119,9; Tit 2,6"] },
      { number: 5, text: "Der Weise höre und mehre die Kenntnis, und der Verständige erwerbe* weisen Rat*,", footnotes: ["o. Es hört darauf der Weise und nimmt zu an Einsicht, und der Verständige erwirbt", "w. Steuerungen; d. h. Verhaltensregeln; o. weise Lenkung\n℘ Kap. 8,33; 9,8.9; 18,15; 19,25; 21,11; 5Mo 4,6; Hi 34,2; Mt 13,12"] },
      { number: 6, text: "um zu verstehen Spruch und Bildrede, Worte von Weisen und ihre Rätsel! —" },
      { number: 7, text: "Die Furcht des HERRN ist der Anfang der Erkenntnis.* Weisheit und Zucht verachten <nur> die Narren.*", footnotes: ["℘ Kap. 9,10; 15,33; Hi 28,28", "℘ Kap. 15,5; 18,2"] },
      { number: 8, text: "Gehorche, mein Sohn, der Zucht deines Vaters und verwirf nicht die Weisung* deiner Mutter!*", heading: "Warnung vor Verführung zur Gewalttat", footnotes: ["o. das Gesetz", "℘ Kap. 6,20; 23,22; 31,1; Eph 6,1"] },
      { number: 9, text: "Denn ein anmutiger Kranz für dein Haupt sind sie und eine Kette für deinen Hals*. —", footnotes: ["℘ Kap. 3,22"] },
      { number: 10, text: "Mein Sohn, wenn Sünder dich locken, so folge <ihnen> nicht!*", footnotes: ["℘ Kap. 24,2; Eph 5,11"] },
      { number: 11, text: "Wenn sie sagen: Geh mit uns! Wir wollen auf Blut lauern*, wollen ohne Grund dem Rechtschaffenen* nachstellen*.", footnotes: ["℘ Kap. 12,6", "o. dem Unschuldigen", "℘ Ps 10,8; Jer 5,26"] },
      { number: 12, text: "Wir wollen sie wie der Scheol lebendig verschlingen* und vollständig wie solche, die <im Nu> in die Grube hinabfahren.", footnotes: ["℘ Ps 124,3"] },
      { number: 13, text: "Allerlei kostbaren Besitz werden wir finden, werden unsere Häuser mit Beute füllen.*", footnotes: ["℘ Am 3,10"] },
      { number: 14, text: "Dein Los wirf nur in unserer Mitte; ein Beutel soll uns allen sein! —" },
      { number: 15, text: "Mein Sohn, geh nicht mit ihnen auf dem Weg, halte deinen Fuß zurück von ihrem Pfad!*", footnotes: ["℘ Kap. 3,31; 4,14.15; Ps 1,1; 119,101; Jes 33,15"] },
      { number: 16, text: "Denn ihre Füße laufen zum Bösen und eilen, Blut zu vergießen.*", footnotes: ["℘ Kap. 6,18; 1Mo 37,20; Jes 59,7"] },
      { number: 17, text: "In den Augen aller Vögel* ist das Fangnetz ja <auch> ohne Absicht bestreut*;", footnotes: ["w. jedes Herrn der Schwinge", "d. h. mit Köder; andere üs. mit Textänderung: ausgespannt"] },
      { number: 18, text: "doch jene lauern auf ihr Blut, sie stellen ihrem Leben nach*.", footnotes: ["o. und <jene> lauern auf ihr eigenes Blut, stellen ihrem eigenen Leben nach\n℘ Kap. 5,22; 11,5.6"] },
      { number: 19, text: "So sind* die Pfade eines jeden, der unrechten Gewinn macht: Der nimmt seinem Besitzer das Leben.*", footnotes: ["d. h. wie das Schicksal der Vögel, die sich auf den Köder stürzen", "℘ Kap. 15,27; 29,24; Jos 7,21.25; Ps 7,16.17; 1Tim 6,9.10"] },
      { number: 20, text: "Die Weisheit schreit draußen; auf den Plätzen lässt sie ihre Stimme erschallen.*", heading: "Warnung vor Ungehorsam gegenüber der Weisheit", footnotes: ["℘ Kap. 8,1; 9,1.3"] },
      { number: 21, text: "Wo man am lautesten lärmt*, ruft sie. An den Eingängen der Tore, in der Stadt, spricht sie ihre Worte*:", footnotes: ["w. Auf dem Gipfel der lärmenden <Orte>", "℘ Kap. 8,3"] },
      { number: 22, text: "Bis wann, ihr Einfältigen*, wollt ihr Einfalt* lieben und haben Spötter ihre Lust an Spott* und hassen die Toren Erkenntnis*?", footnotes: ["o. Unerfahrenen; o. Unverständigen", "o. Unerfahrenheit; o. Unverstand", "℘ Kap. 15,12", "℘ Ps 94,8"] },
      { number: 23, text: "Wendet ihr euch meiner Mahnung zu, siehe*, so will ich meinen Geist euch sprudeln lassen*, will euch kundtun meine Worte. —", footnotes: ["o. Kehrt auf meine Rüge hin um! Siehe", "℘ Joe 3,1"] },
      { number: 24, text: "Weil ich rief und ihr euch weigertet, <weil> ich meine Hand ausstreckte und niemand aufmerkte*", footnotes: ["℘ Hi 33,14; Jes 50,2; Jer 7,13; Mt 22,4"] },
      { number: 25, text: "und ihr fahren ließet all meinen Rat und meine Mahnung* nicht wolltet*,", footnotes: ["o. Rüge", "℘ 2Chr 33,10; 36,16; Ps 107,11"] },
      { number: 26, text: "so will auch ich bei eurem Unglück lachen, will spotten, wenn der Schrecken über euch kommt*,", footnotes: ["℘ Kap. 3,34; 19,29; 5Mo 28,63; Ps 37,13"] },
      { number: 27, text: "wenn wie ein Unwetter der Schrecken euch naht, euer Unglück hereinbricht wie ein Sturm, wenn Bedrängnis und Angst über euch kommen*.", footnotes: ["℘ Kap. 10,25; Jer 23,19; 1Thes 5,3"] },
      { number: 28, text: "Dann rufen sie mich, doch ich antworte nicht*, <dann> suchen sie mich, doch sie finden mich nicht.*", footnotes: ["℘ 5Mo 1,45; 1Sam 8,18; Ps 18,42; Jes 1,15", "℘ Hos 5,6"] },
      { number: 29, text: "Weil sie Erkenntnis gehasst* und die Furcht des HERRN nicht erwählt haben*,", footnotes: ["℘ Hi 21,14", "℘ 2Thes 2,10"] },
      { number: 30, text: "meinen Rat nicht gewollt, verschmäht haben all meine Mahnung*,", footnotes: ["o. Rüge\n℘ Kap. 5,12; 2Chr 25,16"] },
      { number: 31, text: "sollen sie essen von der Frucht ihres Weges, von ihren Ratschlägen sich sättigen.*", footnotes: ["℘ Kap. 14,14; Jer 6,19; Hes 22,31"] },
      { number: 32, text: "Ja, die Abkehr der Einfältigen* tötet sie, und die Sorglosigkeit der Toren vernichtet sie.*", footnotes: ["o. Unerfahrenen; o. Unverständigen", "℘ Kap. 2,18; 8,36; 9,18; 10,21; 14,16; Am 6,1"] },
      { number: 33, text: "Doch wer auf mich hört, wird sicher wohnen, kann ruhig sein vor des Unglücks Schrecken.*", footnotes: ["℘ 3Mo 25,18; Hi 36,11; Jes 32,17"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Mein Sohn, wenn du meine Reden annimmst und meine Gebote bei dir verwahrst*,", heading: "Segen der Weisheit — Schutz vor dem Verderben", footnotes: ["℘ vgl. Kap. 3,1-26; 8,1-21; 9,1-12", "℘ Kap. 7,1"] },
      { number: 2, text: "indem du der Weisheit dein Ohr leihst, dein Herz dem Verständnis zuwendest*,", footnotes: ["℘ Ps 119,112"] },
      { number: 3, text: "ja, wenn du den Verstand anrufst, zum Verständnis erhebst deine Stimme*,", footnotes: ["℘ Kap. 4,1"] },
      { number: 4, text: "wenn du es suchst wie Silber und wie Schätzen ihm nachspürst*,", footnotes: ["℘ Kap. 4,7; 16,16; Mt 13,44; Kol 2,3"] },
      { number: 5, text: "dann wirst du verstehen die Furcht des HERRN* und die Erkenntnis Gottes gewinnen*.", footnotes: ["℘ Jes 33,6", "℘ Kap. 28,7; Joh 17,3"] },
      { number: 6, text: "Denn der HERR gibt Weisheit*. Aus seinem Mund <kommen> Erkenntnis und Verständnis*.", footnotes: ["℘ 2Mo 31,3; 1Kö 10,24; Dan 2,21; Jak 1,5", "℘ Esr 7,25; Hi 12,13.16; Ps 19,8; 94,10; Pred 2,26"] },
      { number: 7, text: "Er hält für die Aufrichtigen* Hilfe* bereit, ist denen ein Schild, die in Lauterkeit* wandeln*,", footnotes: ["o. die Geraden", "o. Gelingen; o. Klugheit", "o. Vollkommenheit", "℘ Ps 3,4"] },
      { number: 8, text: "indem er behütet die Pfade des Rechts und den Weg seiner Frommen bewahrt*.", footnotes: ["℘ 1Sam 2,9"] },
      { number: 9, text: "Dann verstehst du Gerechtigkeit, Recht und Geradheit* und jede gute Bahn*.", footnotes: ["o. Aufrichtigkeit\n℘ Kap. 1,2", "w. Wagenspur\n℘ Kap. 4,12; Ps 25,12"] },
      { number: 10, text: "Denn Weisheit zieht ein in dein Herz, und Erkenntnis wird deiner Seele lieb*.", footnotes: ["℘ Ps 119,103; Phil 3,8"] },
      { number: 11, text: "Besonnenheit wacht über dir, Verständnis wird dich behüten*:", footnotes: ["℘ Kap. 4,6; Ps 119,9"] },
      { number: 12, text: "um dich zu retten vom bösen Weg, vom Mann, der Verkehrtes <nur> redet*,", footnotes: ["℘ Kap. 6,12"] },
      { number: 13, text: "<von denen,> die da verlassen die geraden Pfade, um auf finsteren Wegen zu gehen," },
      { number: 14, text: "die sich <nur> freuen am bösen Tun, frohlocken bei schlimmer Verkehrtheit*,", footnotes: ["℘ Kap. 4,16.17; Röm 1,32"] },
      { number: 15, text: "deren Pfade krumm sind, die in die Irre gehen auf ihren Bahnen*,", footnotes: ["w. in ihren Wagenspuren\n℘ Ps 125,5; Jes 59,8"] },
      { number: 16, text: "um dich zu retten von <der> fremden Frau*, von der Ausländerin, die ihre Worte glatt macht*,", footnotes: ["Damit kann die Ehefrau eines anderen Israeliten gemeint sein oder die Frau mit einer fremden Religion.", "℘ Kap. 5,3; 6,24; 7,5.21; 26,28; 1Mo 39,8"] },
      { number: 17, text: "die den Vertrauten ihrer Jugend verlässt und den Bund ihres Gottes vergisst.*", footnotes: ["℘ Mal 2,14"] },
      { number: 18, text: "Denn zum Tod senkt sich ihr Haus und zu den Schatten ihre Bahnen.*", footnotes: ["℘ Kap. 1,32; 7,26.27"] },
      { number: 19, text: "Alle, die einkehren zu ihr, kommen nie wieder zurück, finden nie wieder die Pfade des Lebens.*", footnotes: ["℘ Kap. 5,11; 6,32; Pred 7,26"] },
      { number: 20, text: "Darum geh du auf dem Weg der Guten, die Pfade der Gerechten beachte!*", footnotes: ["℘ Kap. 4,11; 8,20"] },
      { number: 21, text: "Denn die Aufrichtigen bewohnen das Land, und die Lauteren bleiben darin.*", footnotes: ["℘ Ps 37,18.29; Mt 5,5"] },
      { number: 22, text: "Die Gottlosen aber werden getilgt aus dem Land, und die Treulosen reißt man aus ihm heraus.*", footnotes: ["℘ Kap. 10,30; 5Mo 29,20; 1Kö 14,14; 1Chr 10,13; Ps 37,20; 52,7; 104,35"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "*Mein Sohn, meine Weisung vergiss nicht, und dein Herz bewahre meine Gebote!*", heading: "Ermahnung zur Gottesfurcht", footnotes: ["℘ vgl. Kap. 2,1-11; 8,1-21; 9,1-12", "℘ Kap. 4,21; 5Mo 5,16; 6,6; 2Tim 3,14"] },
      { number: 2, text: "Denn Länge der Tage und Jahre des Lebens und Frieden mehren sie dir.*", footnotes: ["℘ V. 16.18; Kap. 4,4.10; 5Mo 5,32.33; 11,21"] },
      { number: 3, text: "Gnade und Treue* sollen dich nicht verlassen. Binde sie um deinen Hals*, schreibe sie auf deines Herzens Tafel*!", footnotes: ["℘ Kap. 16,6; 20,28; 2Mo 34,6", "℘ Kap. 6,21", "℘ Jer 17,1; 2Kor 3,3"] },
      { number: 4, text: "Und finde Gunst und feine Klugheit in den Augen Gottes und der Menschen!*", footnotes: ["℘ 1Mo 39,4"] },
      { number: 5, text: "Vertraue auf den HERRN mit deinem ganzen Herzen* und stütze dich nicht auf deinen Verstand!*", footnotes: ["℘ Ps 37,3.5", "℘ Kap. 22,19"] },
      { number: 6, text: "Auf all deinen Wegen erkenne nur ihn, dann ebnet er selbst deine Pfade!*", footnotes: ["℘ Jes 26,7"] },
      { number: 7, text: "Sei nicht weise in deinen Augen*, fürchte den HERRN und weiche vom Bösen!*", footnotes: ["℘ Kap. 26,12", "℘ Kap. 14,16; 28,26"] },
      { number: 8, text: "Das ist Heilung für deinen Leib*, Labsal für deine Gebeine*.", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: für deinen Nabel", "℘ Kap. 4,22"] },
      { number: 9, text: "Ehre den HERRN mit* deinem Besitz, mit* den Erstlingen all deines Ertrages!*", footnotes: ["w. von", "w. von", "℘ 2Mo 23,16.19; 4Mo 15,20"] },
      { number: 10, text: "Dann füllen deine Speicher sich mit Vorrat, und von Most fließen über deine Keltern.*", footnotes: ["℘ 5Mo 14,29; 28,8; 2Chr 31,10"] },
      { number: 11, text: "Die Zucht des HERRN, mein Sohn, verwirf nicht, und lass dich nicht verdrießen seine Mahnung!*", footnotes: ["℘ Hi 5,17"] },
      { number: 12, text: "Denn wen der HERR liebt, den züchtigt er wie ein Vater den Sohn*, den er gern hat.*", footnotes: ["andere in Anlehnung an LXX: den züchtigt er, er fügt dem Sohn Schmerz zu", "℘ Hebr 12,5.6"] },
      { number: 13, text: "Glücklich der Mensch, der Weisheit gefunden hat, der Mensch, der Verständnis erlangt!*", heading: "Wert und Nutzen der Weisheit", footnotes: ["℘ Kap. 8,34.35"] },
      { number: 14, text: "Denn ihr Erwerb ist besser als Silber* und <wertvoller> als Gold ihr Gewinn*.", footnotes: ["w. besser als der Erwerb von Silber", "o. Ertrag\n℘ Kap. 16,16"] },
      { number: 15, text: "Kostbarer ist sie als Korallen, und alle deine Kleinode kommen an Wert ihr nicht gleich.*", footnotes: ["℘ Pred 7,11"] },
      { number: 16, text: "Länge des Lebens* <ist> in ihrer Rechten, in ihrer Linken Reichtum und Ehre.*", footnotes: ["w. der Tage", "℘ Kap. 4,8; 1Kö 3,13"] },
      { number: 17, text: "Ihre Wege sind freundliche Wege, und alle ihre Pfade sind Frieden." },
      { number: 18, text: "Ein Baum des Lebens* ist sie für <alle>, die sie ergreifen, und wer an ihr festhält, ist glücklich zu preisen.*", footnotes: ["℘ Kap. 13,12", "℘ Kap. 8,32"] },
      { number: 19, text: "Der HERR hat durch Weisheit die Erde gegründet, den Himmel befestigt durch Einsicht.*", footnotes: ["℘ Kap. 8,29; Hi 38,4; Jer 10,12"] },
      { number: 20, text: "Durch seine Erkenntnis brachen die Fluten* hervor, die Wolken triefen von Tau.* —", footnotes: ["o. Tiefen; vgl. 1Mo 1,2", "℘ Hi 36,27"] },
      { number: 21, text: "Mein Sohn, lass sie nicht weichen aus deinen Augen*, bewahre Umsicht und Besonnenheit!", footnotes: ["℘ Kap. 4,6"] },
      { number: 22, text: "So werden sie Leben sein für deine Seele und Anmut für deinen Hals.*", footnotes: ["℘ Kap. 1,9; 19,8"] },
      { number: 23, text: "Dann gehst du sicher deinen Weg, dein Fuß stößt nirgends an.*", footnotes: ["℘ Kap. 4,12; 6,22; Ps 91,12; Mt 4,6"] },
      { number: 24, text: "Wenn du dich hinlegst, wirst du nicht aufschrecken,* und liegst du, erquickt <dich> dein Schlaf.*", footnotes: ["℘ Kap. 19,23; 3Mo 26,6; 1Petr 3,6", "℘ 2Chr 20,30; Ps 3,6; Hes 34,25"] },
      { number: 25, text: "Fürchte dich nicht vor plötzlichem Schrecken noch vor dem Verderben* der Gottlosen, wenn es <über sie> kommt!*", footnotes: ["w. Unwetter", "℘ Ps 91,5; 112,7; Jes 54,14; Mi 4,4; Sach 9,8"] },
      { number: 26, text: "Denn der HERR ist deine Zuversicht* und bewahrt deinen Fuß vor der Falle.*", footnotes: ["o. ist an deiner Seite", "℘ Ps 121,3; Jud 24"] },
      { number: 27, text: "Enthalte Gutes dem nicht vor, dem es gebührt*, wenn es in der Macht deiner Hand steht, es zu tun!* —", heading: "Ermahnung zur Nächstenliebe", footnotes: ["o. dem, der es braucht; w. seinem Herrn", "℘ Gal 6,10; 1Jo 3,17"] },
      { number: 28, text: "Sage nicht zu deinem Nächsten: Geh, komm <später> wieder, und morgen will ich geben!, — wo du doch hast.* —", footnotes: ["℘ Pred 9,10; Mt 5,42"] },
      { number: 29, text: "Schmiede* nicht Böses gegen deinen Nächsten, während er vertrauensvoll bei dir wohnt!* —", footnotes: ["w. Pflüge", "℘ Sach 7,10"] },
      { number: 30, text: "Geh mit keinem grundlos vor Gericht, wenn er dir nichts Böses angetan!* —", footnotes: ["℘ 2Kö 14,10"] },
      { number: 31, text: "Beneide nicht den Mann der Gewalttat* und wähle keinen seiner Wege!* —", footnotes: ["℘ Kap. 23,17; 24,1.19", "℘ Kap. 1,15"] },
      { number: 32, text: "Denn ein Gräuel für den HERRN ist, wer sich auf Abwege begibt*; doch mit den Aufrichtigen hält er seinen Rat*.", footnotes: ["℘ Kap. 6,12-15", "o. seinen vertrauten Umgang\n℘ Ps 25,14"] },
      { number: 33, text: "Der Fluch des HERRN fällt auf das Haus des Gottlosen*, doch die Wohnung der Gerechten segnet er*.", footnotes: ["℘ Sach 5,4", "℘ Kap. 10,6; 14,11; 15,6; Hi 8,6"] },
      { number: 34, text: "Den Spöttern gegenüber spottet er*, den Demütigen aber gibt er Gnade*.", footnotes: ["℘ Kap. 1,26", "℘ Jak 4,6; 1Petr 5,5"] },
      { number: 35, text: "Ehre erben die Weisen*, die Toren aber tragen Schande davon*.", footnotes: ["℘ Kap. 4,8; Dan 12,3", "w. die Toren aber hebt die Schande hoch"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Hört, ihr Söhne, auf die Zucht des Vaters* und merkt auf, um Einsicht zu kennen*!", heading: "Väterliche Unterweisung zum Streben nach Weisheit und zum Befolgen ihrer Lehre", footnotes: ["℘ Kap. 13,1; 1Mo 49,2", "℘ Kap. 1,2; 2,3; 5,1"] },
      { number: 2, text: "Denn gute Lehre gebe ich euch*. Meine Weisung sollt ihr nicht verlassen!", footnotes: ["℘ Kap. 8,6-8; Hi 33,3"] },
      { number: 3, text: "Als ich <noch> ein Sohn war <bei> meinem Vater, zart und einzig war vor* meiner Mutter,", footnotes: ["d. h. auch: unter der Obhut von"] },
      { number: 4, text: "da unterwies er mich und sprach zu mir: Dein Herz halte meine Worte fest! Beachte meine Gebote und lebe!*", footnotes: ["℘ Kap. 3,2; 7,2"] },
      { number: 5, text: "Erwirb dir Weisheit, erwirb Verstand*, vergiss <sie> nicht! Und weiche nicht von den Reden meines Mundes!*", footnotes: ["℘ Kap. 23,23; Jak 1,5", "℘ Hi 23,11"] },
      { number: 6, text: "Verlass sie nicht*, so wird sie dich behüten; liebe sie, so wird sie dich bewahren!*", footnotes: ["℘ Kap. 3,21", "℘ Kap. 2,10-12"] },
      { number: 7, text: "Der Weisheit Anfang ist: Erwirb dir Weisheit!* Und mit allem, was du erworben hast, erwirb <dir> Verstand!*", footnotes: ["o. Das Beste ist Weisheit. <Darum> erwirb Weisheit!", "℘ Kap. 2,4; 2Chr 1,10"] },
      { number: 8, text: "Halte sie hoch, so wird sie dich erhöhen! Sie bringt dich zu Ehren*, wenn du sie umarmst.", footnotes: ["℘ Kap. 3,16.35"] },
      { number: 9, text: "Sie verleiht deinem Haupt einen anmutigen Kranz, eine prächtige Krone reicht sie dir dar.*", footnotes: ["℘ Kap. 14,18; 1Kö 3,13"] },
      { number: 10, text: "Höre, mein Sohn, und nimm meine Worte an, dann werden dir zahlreich die Lebensjahre!" },
      { number: 11, text: "Im Weg der Weisheit unterweise ich dich, lasse dich gehen auf geraden Bahnen.*", footnotes: ["℘ Kap. 2,20; Ps 23,3"] },
      { number: 12, text: "Wenn du gehst, wird dein Schreiten nicht beengt sein, und wenn du läufst, wirst du nicht stürzen.*", footnotes: ["℘ Kap. 2,9; 3,23"] },
      { number: 13, text: "Halte fest an der Zucht, lass nicht ab! Wahre sie, denn sie ist dein Leben!* —", footnotes: ["℘ Kap. 6,23; 8,35; 10,17; 5Mo 32,47"] },
      { number: 14, text: "Den Pfad der Gottlosen betritt nicht, beschreite nicht den Weg der Bösen!*", footnotes: ["℘ Kap. 22,25; Ps 1,1; 1Kor 15,33"] },
      { number: 15, text: "Lass ihn liegen, geh nicht darauf, weiche von ihm und geh vorbei!*", footnotes: ["℘ Kap. 1,15; 5,8; 24,1"] },
      { number: 16, text: "Denn sie schlafen nicht, wenn sie nichts Böses getan, und ihr Schlaf wird ihnen geraubt, wenn sie nicht <irgendeinen> zu Fall gebracht haben.*", footnotes: ["℘ Kap. 2,14; Ps 36,3-5"] },
      { number: 17, text: "Denn sie essen Brot der Gottlosigkeit, und Wein von Gewalttaten trinken sie.*", footnotes: ["d. h. Brot, das sie sich in ihrer Gottlosigkeit, und Wein, den sie sich durch Gewalttaten angeeignet haben\n℘ Jes 5,18-20; Jer 9,4"] },
      { number: 18, text: "Aber der Pfad der Gerechten ist wie das glänzende Morgenlicht*, heller und heller erstrahlt es bis zur Tageshöhe*.", footnotes: ["℘ 2Sam 23,4; Ps 97,11", "℘ Kap. 13,9; Ri 5,31"] },
      { number: 19, text: "Der Weg der Gottlosen ist wie das Dunkel*; sie erkennen nicht, worüber sie stürzen.*", footnotes: ["℘ Hi 5,14; Ps 82,5", "℘ Kap. 22,5; Jes 59,9.10; Jer 23,12"] },
      { number: 20, text: "Mein Sohn, auf meine Worte achte, meinen Reden neige dein Ohr zu!*", footnotes: ["℘ Kap. 5,1; Ps 34,12"] },
      { number: 21, text: "Lass sie nicht aus deinen Augen weichen, bewahre sie im Innern deines Herzens!*", footnotes: ["℘ Kap. 3,1; 6,21; 7,3; 22,18; 5Mo 4,9"] },
      { number: 22, text: "Denn Leben sind sie denen, die sie finden, und Heilung für ihr ganzes Fleisch.* —", footnotes: ["℘ Kap. 3,8; 12,18"] },
      { number: 23, text: "Mehr als alles, was man <sonst> bewahrt, behüte dein Herz!* Denn in ihm <entspringt> die Quelle* des Lebens.* —", footnotes: ["℘ Kap. 16,17", "w. aus ihm sind die Ausflüsse", "℘ Mt 12,34"] },
      { number: 24, text: "Lass weichen von dir die Falschheit des Mundes und die Verdrehtheit der Lippen entferne von dir!* —", footnotes: ["℘ Ps 34,14; 1Petr 3,10"] },
      { number: 25, text: "Lass deine Augen geradeaus blicken und deine Blicke gerade vor dich gehen!* —", footnotes: ["℘ Hi 31,1"] },
      { number: 26, text: "Gib acht auf die Bahn deines Fußes, und alle deine Wege seien geordnet!*", footnotes: ["℘ Kap. 15,21; 21,29; 23,19; Hebr 12,13"] },
      { number: 27, text: "Bieg nicht ab zur Rechten noch zur Linken*, lass weichen deinen Fuß vom Bösen*!", footnotes: ["℘ 5Mo 5,32", "℘ 2Petr 2,15"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Mein Sohn, horche auf meine Weisheit, zu meiner Einsicht neige dein Ohr*,", heading: "Warnung vor Ehebruch", footnotes: ["℘ vgl. Kap. 6,20-35; 7", "℘ Kap. 4,1.20; 22,17"] },
      { number: 2, text: "dass du Besonnenheit behältst und deine Lippen Erkenntnis bewahren*!", footnotes: ["℘ Kap. 16,23"] },
      { number: 3, text: "Denn Honig träufeln die Lippen der Fremden*, und glatter als Öl ist ihr Gaumen*;", footnotes: ["s. Anm. zu Kap. 2,16", "℘ Kap. 2,16; 22,14"] },
      { number: 4, text: "aber zuletzt ist sie bitter wie Wermut, scharf wie ein zweischneidiges Schwert*.", footnotes: ["℘ 1Kor 6,18"] },
      { number: 5, text: "Ihre Füße steigen hinab zum Tod, auf den Scheol halten ihre Schritte zu.*", footnotes: ["℘ Pred 7,26"] },
      { number: 6, text: "Damit du auf den Pfad des Lebens nur nicht achtgibst, sind unstet ihre Bahnen*, <und> du erkennst es nicht.", footnotes: ["o. schweifen heimatlos umher ihre Bahnen"] },
      { number: 7, text: "Nun denn, ihr Söhne, hört auf mich und weicht nicht ab von den Worten meines Mundes!" },
      { number: 8, text: "Halte fern von ihr deinen Weg und komm ihrer Haustür nicht nah!*", footnotes: ["℘ Kap. 4,14.15"] },
      { number: 9, text: "Sonst gibst du andern deine <Lebens>blüte* und deine Jahre einem Grausamen.", footnotes: ["o. deinen Glanz; o. deine Ehre"] },
      { number: 10, text: "Sonst sättigen Fremde sich noch an deinem Vermögen, an deinem mühsam Erworbenen in eines Ausländers Haus*;", footnotes: ["℘ Kap. 29,3"] },
      { number: 11, text: "und du stöhnst zuletzt*, wenn dein Fleisch und dein Leib dahinschwinden*,", footnotes: ["w. an deinem Ende", "℘ Kap. 2,19"] },
      { number: 12, text: "und sagst: Ach, wie konnte ich nur hassen die Zucht, <wie> konnte mein Herz nur die Mahnung* verschmähen*,", footnotes: ["o. die Rüge", "℘ Kap. 1,29.30"] },
      { number: 13, text: "dass ich nicht gehorchte der Stimme <all> derer, die mich unterwiesen, dass ich mein Ohr meinen Lehrern nicht zuneigte!*", footnotes: ["℘ 1Kö 12,14"] },
      { number: 14, text: "Wie leicht hätte ich ganz ins Unglück geraten können*, mitten in der Versammlung und der Gemeinde!*", footnotes: ["o. Es fehlt nur noch wenig, dann bin ich in allem Übel", "℘ Kap. 10,17; Ps 73,2"] },
      { number: 15, text: "Trinke Wasser aus deiner <eigenen> Zisterne und was aus deinem Brunnen quillt." },
      { number: 16, text: "Sollen nach draußen verströmen deine Quellen, auf die Plätze die Wasserbäche?" },
      { number: 17, text: "Dir allein sollen sie gehören, doch keinem Fremden neben dir." },
      { number: 18, text: "Deine Quelle sei gesegnet, erfreue dich an der Frau deiner Jugend!*", footnotes: ["℘ Pred 9,9"] },
      { number: 19, text: "Die liebliche Hirschkuh und anmutige Gämse* — ihre Brüste sollen dich berauschen jederzeit, in ihrer Liebe sollst du taumeln immerdar!", footnotes: ["o. <das> . . . Steinbockweibchen\n℘ Hl 2,9"] },
      { number: 20, text: "Warum solltest du, mein Sohn, an einer Fremden* taumeln und den Busen einer anderen* umarmen?* —", footnotes: ["s. Anm. zu Kap. 2,16", "w. einer Ausländerin", "℘ Mal 2,14.16; 1Kor 6,16"] },
      { number: 21, text: "Denn vor den Augen des HERRN <liegen> eines jeden Wege*, und auf alle seine Bahnen gibt er acht.", footnotes: ["℘ Kap. 15,3.11; Ps 139,3; Jer 16,17; Hos 7,2"] },
      { number: 22, text: "Seine eigenen Sünden fangen ihn, den Gottlosen, und in den Stricken seiner Sünde wird er festgehalten.*", footnotes: ["℘ Kap. 1,18; 11,5.6; 12,14; 14,32; 18,7; 24,12; 26,27; Ri 9,57; 1Kö 18,18; Est 9,25; Ps 9,17; Jer 2,19; Kla 1,14; Ob 15"] },
      { number: 23, text: "Ein solcher wird sterben aus Mangel an Zucht, und in der Größe seiner Narrheit taumelt er dahin*.", footnotes: ["LXX: wird er weggerafft\n℘ Kap. 10,21; 21,16; Ps 94,23"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Mein Sohn, hast du gebürgt für deinen Nächsten, für einen Fremden deinen Handschlag gegeben*,", heading: "Warnung vor Bürgschaft, Trägheit und Falschheit", footnotes: ["℘ Kap. 11,15; 17,18; 20,16; 22,26; 27,13"] },
      { number: 2, text: "bist du verstrickt durch deines Mundes Worte, gefangen durch die Worte deines Mundes," },
      { number: 3, text: "so tu denn dies, mein Sohn: Reiß dich los, da du in deines Nächsten Hand gekommen bist! Geh unverzüglich hin und bestürme deinen Nächsten!" },
      { number: 4, text: "Gönne deinen Augen keinen Schlaf und keinen Schlummer deinen Wimpern*!", footnotes: ["℘ Ps 132,4"] },
      { number: 5, text: "Reiße dich los wie die Gazelle aus der Hand <des Jägers>* und wie ein Vogel aus der Hand des Vogelstellers*!", footnotes: ["LXX, Vulg. und die syr. Üs.: aus dem Netz", "℘ Ps 124,7"] },
      { number: 6, text: "Geh hin zur Ameise, du Fauler*, sieh ihre Wege an und werde weise!", footnotes: ["℘ Kap. 10,26; 15,19"] },
      { number: 7, text: "Sie, die keinen Anführer*, Aufseher und Gebieter hat,", footnotes: ["o. Fürst; o. Richter"] },
      { number: 8, text: "sie bereitet im Sommer ihr Brot, sammelt in der Ernte ihre Nahrung.*", footnotes: ["℘ Kap. 27,27; 30,25"] },
      { number: 9, text: "Bis wann, du Fauler, willst du noch liegen? Wann willst du aufstehen von deinem Schlaf?*", footnotes: ["℘ Kap. 26,14"] },
      { number: 10, text: "Noch ein wenig Schlaf, noch ein wenig Schlummer, noch ein wenig Händefalten, um auszuruhen —" },
      { number: 11, text: "und schon kommt wie ein Landstreicher* deine Armut* und dein Mangel wie ein unverschämter Mann*.", footnotes: ["o. Wegelagerer; w. Umhergehender", "℘ Kap. 10,4; 19,15; 20,13; 24,33.34; Pred 4,5", "o. wie ein schildbewehrter Mann"] },
      { number: 12, text: "Ein ruchloser Mensch, ein heilloser Mann ist, wer umhergeht mit Falschheit im Mund*,", footnotes: ["℘ Kap. 2,12; 16,27"] },
      { number: 13, text: "wer zuzwinkert mit seinen Augen*, ein Zeichen gibt* mit seinen Füßen, einen Hinweis mit seinen Fingern*,", footnotes: ["℘ Kap. 10,10; Ps 101,3", "w. wer spricht; nach anderen: wer scharrt", "℘ Jes 58,9"] },
      { number: 14, text: "wer Verkehrtheit <trägt> in seinem Herzen*, Böses schmiedet* zu aller Zeit*, freien Lauf lässt dem Zank*.", footnotes: ["℘ Kap. 3,32; Ps 140,3; Mt 15,19", "w. pflügt", "℘ Kap. 14,22; Mi 2,1", "o. Zank veranlasst"] },
      { number: 15, text: "Darum kommt plötzlich sein Unglück; im Nu wird er zerschmettert ohne Heilung.*", footnotes: ["℘ Kap. 24,22; 29,1; Hes 11,13"] },
      { number: 16, text: "Sechs <Dinge> sind es, die dem HERRN verhasst sind, und sieben* sind seiner Seele ein Gräuel:", footnotes: ["℘ Hi 5,19"] },
      { number: 17, text: "Stolze Augen*, falsche Zunge* und Hände, die unschuldiges Blut vergießen*,", footnotes: ["℘ Kap. 16,5; 21,4; Lk 16,15; 1Jo 2,16", "℘ Kap. 12,22; Ps 5,7; Offb 21,8", "℘ 2Kö 21,16; 24,4; Jes 1,15"] },
      { number: 18, text: "ein Herz, das heillose Anschläge schmiedet*, Füße, die eilig dem Bösen nachlaufen*,", footnotes: ["w. Gedanken des Unrechts pflügt\n℘ Kap. 15,26; 24,8; Sach 8,17", "℘ Kap. 1,16; Röm 3,14-18"] },
      { number: 19, text: "wer Lügen vorbringt* als falscher Zeuge* und wer freien Lauf lässt dem Zank* zwischen Brüdern*.", footnotes: ["w. schnaubt, o. aushaucht", "℘ Kap. 14,5; 19,5.9; 1Kö 21,10", "o. Zank veranlasst", "℘ Kap. 8,13; 16,28"] },
      { number: 20, text: "*Bewahre, mein Sohn, das Gebot deines Vaters, verwirf nicht die Weisung* deiner Mutter!*", heading: "Erneute Warnung vor Ehebruch", footnotes: ["℘ vgl. Kap. 5; 7", "o. das Gesetz", "℘ Kap. 1,8"] },
      { number: 21, text: "Binde sie stets auf dein Herz, winde sie um deinen Hals!*", footnotes: ["℘ Kap. 3,3; 4,21; 2Mo 13,9.16"] },
      { number: 22, text: "Bei deinem Gehen leite sie dich*, bei deinem Liegen behüte sie dich*, und wachst du auf, so rede sie dich an!", footnotes: ["℘ Kap. 3,23.24", "℘ Ps 3,6"] },
      { number: 23, text: "Denn eine Leuchte ist das Gebot und die Weisung ein Licht*, und ein Weg zum Leben sind Ermahnungen* der Zucht*,", footnotes: ["℘ Ps 119,105; 2Petr 1,19", "o. Rügen", "℘ Kap. 4,13.22; Hes 20,11"] },
      { number: 24, text: "dich zu bewahren vor der Frau des Nächsten*, vor der glatten Zunge der Fremden*.", footnotes: ["so mit LXX; Mas. T.: vor der Frau der Bosheit", "w. der Ausländerin\n℘ Kap. 2,16"] },
      { number: 25, text: "Begehre nicht in deinem Herzen ihre Schönheit*, lass sie dich nicht mit ihren Wimpern fangen*!", footnotes: ["℘ 5Mo 5,21; 2Sam 11,3; Hi 31,1", "℘ Hl 4,9; 2Petr 2,14"] },
      { number: 26, text: "Denn der Preis für eine Hure <geht> bis zu einem Brot*, doch die Frau eines Mannes macht Jagd auf <dein> kostbares Leben*. —", footnotes: ["℘ Kap. 29,3", "℘ 1Mo 39,7"] },
      { number: 27, text: "Kann man Feuer wohl tragen in seinem Gewandbausch, ohne dass einem die Kleider verbrennen?*", footnotes: ["℘ Hi 31,9-12"] },
      { number: 28, text: "Oder kann jemand wohl schreiten auf glühenden Kohlen, ohne dass er sich die Füße versengt?" },
      { number: 29, text: "So <geht es auch dem>, der hineingeht zur Frau seines Nächsten: keiner bleibt ungestraft, der sie berührt.* —", footnotes: ["℘ 1Mo 20,2-7; 3Mo 18,20; 2Sam 11,27; Jer 5,8.9"] },
      { number: 30, text: "Verachtet man nicht <schon> den Dieb, auch wenn er <nur> stiehlt, um den Bauch* sich zu füllen, weil Hunger ihn treibt?", footnotes: ["w. die Kehle"] },
      { number: 31, text: "Und wird er ertappt, so muss er es siebenfach erstatten; den ganzen Besitz seines Hauses kann er dahingeben.*", footnotes: ["℘ 2Mo 21,37"] },
      { number: 32, text: "Wer aber Ehebruch treibt mit der Frau <seines Nächsten>, ist ohne Verstand.* Nur wer sich selber vernichten will, der mag das tun.*", footnotes: ["℘ Hos 4,11", "℘ Kap. 2,18.19"] },
      { number: 33, text: "Plage und Schande <nur> findet er, und seine Schmach wird nicht mehr gelöscht." },
      { number: 34, text: "Denn Eifersucht <weckt> die Zornglut des Mannes, kein Mitleid verspürt er am Tage der Rache.*", footnotes: ["℘ Kap. 27,4; 1Mo 39,19"] },
      { number: 35, text: "Er nimmt keine Rücksicht auf irgendein Sühnegeld* und willigt nicht ein, selbst wenn du die Bestechung häufst.", footnotes: ["w. Nicht erhebt er <dein> Gesicht <wegen> irgendeines Lösegeldes"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Mein Sohn, bewahre meine Worte, und meine Gebote birg bei dir!*", heading: "Verführung zum Ehebruch — Folgen für den Verführten", footnotes: ["℘ vgl. Kap. 5; 6,20-35", "℘ Kap. 2,1"] },
      { number: 2, text: "Bewahre meine Gebote, damit du lebst*, und meine Weisung wie deinen Augapfel*!", footnotes: ["℘ Kap. 4,4; Ps 119,144; Jes 55,3; Jer 38,20", "℘ Ps 17,8"] },
      { number: 3, text: "Binde sie um deine Finger,* schreibe sie auf die Tafel deines Herzens*!", footnotes: ["℘ 5Mo 6,8", "℘ Kap. 3,3; 4,21; 5Mo 11,18; Jes 59,21; Jer 31,33; 2Kor 3,3"] },
      { number: 4, text: "Sprich zur Weisheit: Meine Schwester bist du! — und Verwandte nenne die Einsicht," },
      { number: 5, text: "dass sie dich bewahre vor der fremden Frau*, vor der Ausländerin, die ihre Worte glatt macht.* —", footnotes: ["Damit kann die Frau eines andern Israeliten gemeint sein oder die Frau mit einer fremden Religion.", "℘ V. 21; Kap. 2,16.19"] },
      { number: 6, text: "Denn durch das Fenster meines Hauses <blickte ich>, durch mein Gitter schaute ich hinaus*.", footnotes: ["℘ Ri 5,28"] },
      { number: 7, text: "Und ich sah unter den Unerfahrenen*, bemerkte unter den Söhnen einen Jüngling ohne Verstand,", footnotes: ["o. Unverständigen; o. Einfältigen"] },
      { number: 8, text: "der geht über die Straße hin zu ihrer Ecke, den Weg zu ihrem Haus betritt er" },
      { number: 9, text: "in der Dämmerung, am Abend des Tages, beim Anbruch* der Nacht und bei Dunkelheit.*", footnotes: ["T.; so in Anlehnung an Kap. 20,20; Mas. T.: in der Pupille der Nacht", "℘ Hi 24,15"] },
      { number: 10, text: "Da siehe, eine Frau kommt ihm entgegen im Hurenkleid* und mit verstecktem <Plan im> Herzen. —", footnotes: ["℘ 1Mo 38,15; 2Kö 9,30; Jer 4,30"] },
      { number: 11, text: "Leidenschaftlich ist sie* und unbändig, zu Hause haben ihre Füße keine Ruhe*.", footnotes: ["℘ Kap. 9,13", "w. lassen ihre Füße sich nicht nieder"] },
      { number: 12, text: "Bald ist sie draußen, bald auf den Plätzen, und neben jeder Ecke lauert sie.*", footnotes: ["℘ Kap. 23,28"] },
      { number: 13, text: "Da greift sie ihn, da küsst sie ihn, wird unverschämt* und sagt zu ihm:", footnotes: ["w. macht ihr Gesicht unverschämt"] },
      { number: 14, text: "Zu Heilsopfern* war ich verpflichtet, heute habe ich meine Gelübde erfüllt*.", footnotes: ["o. Friedensopfern; o. Abschlussopfern; o. Gemeinschaftsopfern", "℘ Kap. 21,27; Jes 1,13"] },
      { number: 15, text: "Darum bin ich ausgezogen, dir entgegen, um dein Gesicht zu suchen, und ich habe dich gefunden." },
      { number: 16, text: "Mit Decken habe ich mein Bett bedeckt, mit buntem ägyptischem Leinen*.", footnotes: ["℘ Jes 19,9; Hes 27,7"] },
      { number: 17, text: "Ich habe mein Lager benetzt mit Myrrhe, Aloe und Zimt*.", footnotes: ["℘ Ps 45,9; Hl 3,6; 4,14; Hes 27,19"] },
      { number: 18, text: "Komm, wir wollen an Liebe uns berauschen bis zum Morgen, wollen schwelgen in Liebkosungen." },
      { number: 19, text: "Denn der Mann ist nicht zu Hause, er ist weggegangen*, fort auf weite Reise.", footnotes: ["℘ Hes 16,32"] },
      { number: 20, text: "Den Beutel mit dem Geld nahm er in seine Hand, am Tag des Vollmondes <erst> kommt er nach Haus.*", footnotes: ["℘ Kap. 9,17; 4Mo 5,13"] },
      { number: 21, text: "Sie verleitet ihn durch ihr vieles Überreden, mit ihren glatten Lippen reißt sie ihn fort.*", footnotes: ["℘ V. 5"] },
      { number: 22, text: "Er folgt ihr augenblicklich*, so wie ein Stier zur Schlachtung geht, wie in die Fessel hüpft der Hirsch*,", footnotes: ["LXX: Er folgt ihr ahnungslos", "so mit anderer Vokalisierung in Anlehnung an LXX, die syr. und aram. Üs.; Mas. T.: wie die Fußfesseln zur Zucht des Narren <dienen>"] },
      { number: 23, text: "bis ein Pfeil die Leber ihm zerreißt; wie ein Vogel sich ins Fangnetz stürzt und nicht weiß, dass es um sein Leben geht. —" },
      { number: 24, text: "Nun denn, ihr Söhne, hört auf mich und horcht auf die Worte meines Mundes!*", footnotes: ["℘ Kap. 13,1; Ps 34,12"] },
      { number: 25, text: "Nicht schweife dein Herz ab zu ihren Wegen, verirre dich nicht auf ihre Pfade!" },
      { number: 26, text: "Denn viele sind die Erschlagenen, die sie gefällt hat, und zahlreich alle, die sie ermordete*.", footnotes: ["℘ Kap. 23,28"] },
      { number: 27, text: "Ein Weg zum Scheol ist ihr Haus, der hinabführt* zu den Kammern des Todes.*", footnotes: ["w. Wege zum Scheol sind ihr Haus, die hinabführen", "℘ Kap. 2,18; 9,18; Röm 6,23"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Ruft nicht die Weisheit? Die Einsicht, lässt sie nicht ihre Stimme erschallen?*", heading: "Mahnung der Weisheit und sie zu befolgen — Ihre Zusagen", footnotes: ["℘ vgl. Kap. 2,1-11; 3,1-26; 9,1-12", "℘ Kap. 1,20"] },
      { number: 2, text: "Oben auf den Höhen am Weg, da wo die Pfade sich kreuzen*, hat sie sich <wartend> aufgestellt.", footnotes: ["w. am Haus der Pfade\n℘ Mt 22,9"] },
      { number: 3, text: "Neben den Toren, am Zugang zur Stadt, am Eingang der Pforten schreit sie*:", footnotes: ["℘ Kap. 1,21"] },
      { number: 4, text: "An euch, ihr Männer, ergeht mein Ruf, und meine Stimme an die Menschenkinder*.", footnotes: ["℘ Mi 1,2"] },
      { number: 5, text: "Lernt* Klugheit, ihr Einfältigen*, und ihr Toren, bringt <euer> Herz zur Einsicht!", footnotes: ["w. Gewinnt Einsicht in", "o. ihr Unverständigen; o. ihr Unerfahrenen"] },
      { number: 6, text: "Hört zu! Denn Vortreffliches rede ich, und das Öffnen meiner Lippen ist Aufrichtigkeit." },
      { number: 7, text: "Denn Wahrheit verkündet mein Gaumen*, und ein Gräuel ist meinen Lippen die Gottlosigkeit.", footnotes: ["℘ Hi 36,4; Joh 18,37"] },
      { number: 8, text: "In Gerechtigkeit <ergehen> alle Worte meines Mundes; nichts in ihnen ist verschlagen oder falsch.*", footnotes: ["℘ Kap. 4,2; Joh 8,40"] },
      { number: 9, text: "Sie alle sind recht* dem Verständigen und redlich für die zur Erkenntnis Gelangten.*", footnotes: ["w. geradeaus gehend", "℘ Kap. 14,6"] },
      { number: 10, text: "Nehmt an meine Zucht und nicht Silber, und Erkenntnis lieber als auserlesenes Gold!*", footnotes: ["℘ V. 19; Kap. 20,15"] },
      { number: 11, text: "Denn Weisheit ist besser als Korallen, und alle Kleinode kommen ihr nicht gleich an Wert. —" },
      { number: 12, text: "Ich, die Weisheit, bin die Nachbarin der Klugheit, und besonnene Erkenntnis finde ich." },
      { number: 13, text: "Die Furcht des HERRN <bedeutet>, Böses zu hassen.* Hochmut und Stolz und bösen Wandel und einen ränkevollen Mund, <das> hasse ich.*", footnotes: ["℘ 2Mo 1,17; Hi 28,28; Ps 97,10; 101,3; Röm 12,9", "℘ Kap. 6,16-19; 16,5; Am 6,8"] },
      { number: 14, text: "Mein sind Rat und Hilfe*. Ich bin die Einsicht, mein ist die Stärke.*", footnotes: ["o. Gelingen; o. Klugheit", "℘ Hi 12,13; Pred 7,19"] },
      { number: 15, text: "Durch mich regieren Könige*, und Fürsten treffen gerechte Entscheidungen*.*", footnotes: ["℘ Röm 13,1", "w. ordnen Gerechtigkeit an", "℘ 1Kö 3,28; 2Chr 1,11"] },
      { number: 16, text: "Durch mich herrschen Oberste und Edle, alle gerechten Richter*.", footnotes: ["LXX: und Edle richten die Erde"] },
      { number: 17, text: "Ich liebe, die mich lieben*; und die mich suchen, finden mich*.", footnotes: ["℘ Joh 14,21", "℘ Jes 55,6; Mt 7,7"] },
      { number: 18, text: "Reichtum und Ehre sind bei mir, stattlicher* Besitz und Gerechtigkeit.*", footnotes: ["o. altehrwürdiger; o. altangestammter", "℘ Kap. 24,4; Offb 3,18"] },
      { number: 19, text: "Besser ist meine Frucht als Gold und gediegenes Gold, und mein Ertrag <besser> als auserlesenes Silber.*", footnotes: ["℘ V. 10.11"] },
      { number: 20, text: "Auf dem Pfad der Gerechtigkeit gehe ich, mitten auf den Steigen des Rechts*,", footnotes: ["℘ Kap. 2,20"] },
      { number: 21, text: "dass ich Besitz vererbe <allen>, die mich lieben, und ihre Vorratskammern fülle ich." },
      { number: 22, text: "Der HERR hat mich geschaffen als Anfang* seines Weges, als erstes seiner Werke von jeher.*", heading: "Die Weisheit als Gottes ewiger Besitz", footnotes: ["o. besaß mich im Anfang", "℘ Hi 28,27; Joh 1,1.2; Offb 3,14"] },
      { number: 23, text: "Von Ewigkeit her war ich eingesetzt, von Anfang an, vor* den Uranfängen der Erde*.", footnotes: ["o. In der Urzeit wurde ich eingesetzt, im Anbeginn, in", "℘ Mi 5,1"] },
      { number: 24, text: "Als es noch keine Fluten* gab, wurde ich geboren, als noch keine Quellen waren, reich an Wasser.", footnotes: ["o. Tiefen; vgl. V. 27"] },
      { number: 25, text: "Ehe die Berge eingesenkt wurden*, vor den Hügeln war ich geboren*,", footnotes: ["℘ Ps 104,8", "℘ Hi 15,7; Ps 90,2; Kol 1,17"] },
      { number: 26, text: "als er noch nicht gemacht die Erde und die Fluren, noch die Gesamtheit der Erdschollen des Festlandes." },
      { number: 27, text: "Als er die Himmel feststellte, war ich dabei*. Als er einen Kreis abmaß über der Fläche der Tiefe*,", footnotes: ["w. dort", "o. der Flut; vgl. V. 24"] },
      { number: 28, text: "als er die Wolken droben befestigte*, als er stark machte* die Quellen der Tiefe*,", footnotes: ["℘ Hi 26,8", "so mit den alten Üs.; Mas. T.: als stark waren", "o. der Flut; vgl. V. 24\n℘ 1Mo 7,11"] },
      { number: 29, text: "als er dem Meer seine Schranke setzte, damit das Wasser seinen Befehl* nicht übertrat*, als er die Grundfesten der Erde abmaß*:", footnotes: ["o. seinen Rand; d. h. den Rand des Meeres", "℘ 1Mo 1,9; Hi 38,10.11; Ps 136,5", "℘ Kap. 3,19.20"] },
      { number: 30, text: "da war ich Schoßkind bei ihm* und war <seine> Wonne* Tag für Tag, spielend vor ihm allezeit,", footnotes: ["w. Liebling an seiner Seite. — Andere üs.: Werkmeister bei ihm", "℘ Joh 17,24"] },
      { number: 31, text: "spielend auf dem <weiten> Rund seiner Erde, und ich hatte meine Wonne an den Menschenkindern*.", footnotes: ["o. und meine Wonne <war es,> bei den Menschenkindern <zu sein>"] },
      { number: 32, text: "Nun denn, ihr Söhne, hört auf mich, denn glücklich sind, die meine Wege wahren!*", heading: "Vorzüge der Weisheit und Nachteile der Torheit", footnotes: ["℘ Kap. 3,18; Lk 11,28"] },
      { number: 33, text: "Hört auf Zucht und werdet weise*, lasst sie niemals fahren!", footnotes: ["℘ Kap. 1,2-5"] },
      { number: 34, text: "Glücklich der Mensch, der auf mich hört*, indem er wacht an meinen Türen Tag für Tag, die Pfosten meiner Tore hütet!", footnotes: ["℘ Kap. 3,13; 1Kö 10,8"] },
      { number: 35, text: "Denn wer mich findet, hat Leben gefunden*, Gefallen erlangt von dem HERRN.*", footnotes: ["℘ Kap. 4,13.22; Pred 7,12", "o. Denn wenn jemand mich findet, Leben findet und Gefallen erlangt<, dann ist das> vom HERRN."] },
      { number: 36, text: "Wer mich aber verfehlt*, tut sich selbst* Gewalt an. Alle, die mich hassen, lieben den Tod.*", footnotes: ["o. Wer aber gegen mich sündigt", "w. seiner Seele", "℘ Kap. 1,32; 1Kor 16,22"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Die Weisheit hat ihr Haus gebaut, hat ihre sieben Säulen ausgehauen.", footnotes: ["℘ V. 1-12: vgl. Kap. 2,1-11; 3,1-26; 8,1-21"] },
      { number: 2, text: "Sie hat ihr Schlachtvieh geschlachtet, hat ihren Wein gemischt, auch ihren Tisch gedeckt.*", footnotes: ["℘ Mt 22,4"] },
      { number: 3, text: "Sie hat ihre Mägde gesandt, lädt ein auf den Höhen* der Stadt*:", footnotes: ["w. auf den Höhenrücken", "℘ Kap. 1,20"] },
      { number: 4, text: "Wer unerfahren* ist, der kehre hier ein!* Wer ohne Verstand ist, zu dem spricht sie:", footnotes: ["o. unverständig; o. einfältig", "℘ V. 16; Jes 35,8"] },
      { number: 5, text: "Kommt, esst von meinem Brot und trinkt von dem Wein, den ich gemischt*!", footnotes: ["℘ Jes 55,1"] },
      { number: 6, text: "Lasst fahren die Torheit* und lebt und schreitet einher auf dem Weg der Einsicht!", footnotes: ["w. die Unverständigkeiten, o. Einfältigkeiten, o. die Unverständigen, o. Unerfahrenen"] },
      { number: 7, text: "Wer den Spötter zurechtweist, holt sich nur Schande; und wer den Gottlosen rügt, <holt sich> selbst einen* Makel.*", footnotes: ["w. <holt sich> seinen o. dessen", "℘ 1Mo 19,8.9"] },
      { number: 8, text: "Rüge nicht den Spötter, damit er dich nicht hasst*; rüge den Weisen, so wird er dich lieben*!", footnotes: ["℘ Kap. 23,9", "℘ Ps 141,5"] },
      { number: 9, text: "Gib dem Weisen, so wird er noch weiser; belehre den Gerechten, so lernt er noch mehr*!", footnotes: ["w. so mehrt er die Kenntnis\n℘ Kap. 1,5"] },
      { number: 10, text: "Die Furcht des HERRN ist der Weisheit Anfang*; und Erkenntnis des <allein> Heiligen* ist Einsicht*.", footnotes: ["℘ Kap. 1,7; Ps 34,12; 111,10", "Im Hebr. steht die Mehrzahl in steigernder Bedeutung.", "℘ Kap. 30,3"] },
      { number: 11, text: "Denn durch mich werden zahlreich deine Tage, und es mehren sich dir die Jahre des Lebens.*", footnotes: ["℘ Kap. 10,27; 5Mo 6,2; 30,19"] },
      { number: 12, text: "Wenn du weise bist, so bist du weise für dich*; und spottest du, so musst du allein es tragen*.", footnotes: ["℘ Hi 22,3", "℘ Hi 19,4"] },
      { number: 13, text: "Frau Torheit ist leidenschaftlich* im Verführen, sonst kann sie nichts*.", footnotes: ["℘ Kap. 7,11", "o. doch sie hat nichts erkannt; w. sie weiß nicht, was. — LXX: sie kennt keine Scham"] },
      { number: 14, text: "Und sie sitzt an der Tür ihres Hauses, auf einem Sitz auf den Höhen der Stadt," },
      { number: 15, text: "um einzuladen, die des Wegs vorübergehen, die geradehalten ihre Pfade:" },
      { number: 16, text: "Wer unerfahren* ist, der kehre hier ein!* — Wer ohne Verstand ist, zu dem spricht sie:", footnotes: ["o. unverständig; o. einfältig", "℘ V. 3.4"] },
      { number: 17, text: "Gestohlenes Wasser ist süß, und heimliches Brot schmeckt lieblich*. —", footnotes: ["℘ Kap. 7,20; 20,17"] },
      { number: 18, text: "Und er weiß nicht, dass dort die Schatten sind, in den Tiefen des Scheol ihre Geladenen*.", footnotes: ["℘ Kap. 1,32; 7,27"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Sprüche Salomos*Ein weiser Sohn erfreut den Vater*, aber ein törichter Sohn ist der Kummer seiner Mutter*.", heading: "Kap. 10 bis 31: Sammlung einzelner Weisheitssprüche", footnotes: ["℘ Kap. 1,1", "℘ Kap. 23,24.25", "℘ Kap. 15,20; 17,21.25"] },
      { number: 2, text: "Nichts nützen gottlose Schätze*, aber Gerechtigkeit rettet vom Tod*.", footnotes: ["℘ Kap. 13,11", "℘ Kap. 11,4.6.19; 12,28"] },
      { number: 3, text: "Der HERR lässt nicht hungern die Seele* des Gerechten*, aber die Gier der Gottlosen stößt er zurück*.", footnotes: ["o. die Kehle", "℘ Ps 34,10; 37,19", "℘ Hi 15,23"] },
      { number: 4, text: "Arm wird, wer mit lässiger Hand schafft*, aber die Hand der Fleißigen macht reich*.", footnotes: ["lat. Üs.: Lässige Hand macht arm\n℘ Kap. 6,6-11; 12,24", "℘ Kap. 12,27; 13,4; 21,5"] },
      { number: 5, text: "Wer im Sommer sammelt, ist ein kluger Sohn*, wer in der Ernte schläft, ein schandbarer Sohn.", footnotes: ["℘ Kap. 30,25"] },
      { number: 6, text: "Segen ist auf dem Haupt des Gerechten*, aber der Mund der Gottlosen birgt Gewalttat*.", footnotes: ["℘ Kap. 3,33; 11,26; 28,20; Jes 3,10", "o. deckt Gewalttat zu"] },
      { number: 7, text: "Des Gerechten gedenkt man zum Segen*, aber der Name der Gottlosen fault*.", footnotes: ["o. Die Erwähnung des Gerechten ist zum Segen\n℘ Ps 112,6; Mk 14,9", "℘ Hi 18,17; Ps 34,17; 109,13"] },
      { number: 8, text: "Wer weisen Herzens ist, nimmt Gebote an*, wer aber närrische Lippen hat, kommt zu Fall*.", footnotes: ["℘ Kap. 12,1", "℘ Kap. 12,13; 13,3; 18,7; Pred 10,12"] },
      { number: 9, text: "Wer in Lauterkeit lebt, lebt sicher*, wer aber krumme Wege wählt, muss schwitzen*.", footnotes: ["o. Wer in Vollkommenheit geht, geht sicher\n℘ Kap. 28,1.18; Hi 8,20", "o. wer aber seine Wege krumm macht, wird erkannt; d. h. ertappt"] },
      { number: 10, text: "Wer mit den Augen zwinkert, verursacht Schmerz*, und wer närrische Lippen hat, kommt zu Fall*.", footnotes: ["℘ Kap. 6,13.14", "LXX: wer aber in Freimütigkeit rügt, schafft Frieden"] },
      { number: 11, text: "Eine Quelle des Lebens ist der Mund des Gerechten*, aber der Mund der Gottlosen birgt Gewalttat*.", footnotes: ["℘ Kap. 13,14; 15,4; Joh 6,68", "o. deckt Gewalttat zu"] },
      { number: 12, text: "Hass erregt Zänkereien, aber Liebe deckt alle Vergehen zu.*", footnotes: ["℘ Kap. 17,9"] },
      { number: 13, text: "Auf den Lippen des Verständigen findet sich Weisheit, aber der Stock <findet sich> für den Rücken des Unverständigen.*", footnotes: ["℘ Kap. 19,29; 26,3"] },
      { number: 14, text: "Weise bewahren Erkenntnis*, aber der Mund des Narren ist nahes* Verderben.*", footnotes: ["o. Die Weisen halten mit <ihrer> Erkenntnis zurück", "o. stets drohendes", "℘ Kap. 17,20"] },
      { number: 15, text: "Der Besitz des Reichen ist seine feste Stadt*, das Verderben der Geringen ist ihre Armut*.", footnotes: ["℘ Kap. 18,11", "℘ Kap. 19,7"] },
      { number: 16, text: "Der Erwerb des Gerechten <gereicht> zum Leben*, der Ertrag des Gottlosen zur Sünde.", footnotes: ["℘ Kap. 21,21"] },
      { number: 17, text: "Ein Pfad zum Leben ist, wer auf Zucht achtet*; wer aber die Mahnung* unbeachtet lässt, leitet in die Irre*.", footnotes: ["℘ Kap. 4,13", "o. Rüge", "℘ Kap. 5,12-14; 15,32"] },
      { number: 18, text: "Wer Hass verbirgt, hat Lügenlippen;* und wer Verleumdung ausstreut, ist ein Tor.*", footnotes: ["℘ Kap. 26,24-26", "℘ 3Mo 19,16; Jer 6,28"] },
      { number: 19, text: "Bei vielen Worten bleibt <Wort>bruch* nicht aus*, wer aber seine Lippen zügelt, handelt klug*.", footnotes: ["o. das Vergehen", "℘ Hi 11,2", "℘ Kap. 11,12.13; 12,23; 17,27.28"] },
      { number: 20, text: "Auserlesenes Silber ist die Zunge des Gerechten,* das Herz der Gottlosen <aber> ist wenig wert.", footnotes: ["℘ Kap. 20,15; Ps 37,30"] },
      { number: 21, text: "Die Lippen des Gerechten weiden viele*, aber die Narren sterben durch Unverstand*.", footnotes: ["℘ Kap. 15,7; Pred 12,11", "℘ Kap. 1,32; Jes 5,13"] },
      { number: 22, text: "Der Segen des HERRN, der macht reich, und <eigenes> Abmühen fügt neben ihm nichts hinzu.*", footnotes: ["℘ 1Mo 24,35; 26,12; Ps 127,2"] },
      { number: 23, text: "Als ein Vergnügen gilt dem Toren das Verüben von Schandtat*, dem verständigen Mann aber die Weisheit*.", footnotes: ["℘ Kap. 14,9; 15,21; 26,19", "℘ Kap. 16,21"] },
      { number: 24, text: "Wovor dem Gottlosen graut, das wird* über ihn kommen*, aber der Wunsch der Gerechten wird gewährt*.", footnotes: ["w. Das Grauen des Gottlosen wird", "℘ Hes 11,8", "so mit LXX; Mas. T.: aber den Wunsch . . . wird er gewähren\n℘ Ps 37,4"] },
      { number: 25, text: "Sobald ein Sturmwind daherfährt, ist der Gottlose nicht mehr*; der Gerechte aber ist fest gegründet für ewig*.", footnotes: ["℘ Kap. 1,27; Hi 20,8; Ps 58,10", "w. ist eine ewig <bestehende> Grundmauer\n℘ Kap. 12,3.7; Ps 125,1; Mt 7,24.25"] },
      { number: 26, text: "Wie Essig für die Zähne und wie Rauch für die Augen, so ist der Faule für die, die ihn senden.*", footnotes: ["℘ Kap. 6,6"] },
      { number: 27, text: "Die Furcht des HERRN vermehrt die <Lebens>tage*, aber die Jahre der Gottlosen werden verkürzt*.", footnotes: ["℘ Kap. 9,11; Ps 92,15.16", "℘ Hi 15,32; Pred 7,17"] },
      { number: 28, text: "Das Warten der Gerechten <führt zur> Freude*, aber die Hoffnung der Gottlosen wird zunichte*.", footnotes: ["℘ Kap. 29,6; Ps 68,4", "℘ Hi 8,13"] },
      { number: 29, text: "Eine Zuflucht für den, der rechtschaffenen Weges ist, ist der HERR*, aber Verderben für die, die Unrecht tun.*", footnotes: ["so in Anlehnung an die alten Üs.; Mas. T.: Eine Zuflucht für die Rechtschaffenheit ist der Weg des HERRN", "℘ Kap. 11,7; 21,15; Hos 14,10; Lk 2,34"] },
      { number: 30, text: "Der Gerechte wird in Ewigkeit nicht zum Wanken gebracht*, aber die Gottlosen werden im Land nicht wohnen bleiben*.", footnotes: ["℘ Hi 17,9; Ps 15,5; 112,6", "℘ Kap. 2,22"] },
      { number: 31, text: "Der Mund des Gerechten lässt Weisheit sprießen*, aber die Zunge der Verkehrtheit wird abgeschnitten*.", footnotes: ["℘ Ps 37,30", "℘ Ps 12,4"] },
      { number: 32, text: "Die Lippen des Gerechten sind bedacht auf Wohlgefälliges*, der Mund der Gottlosen aber auf Verkehrtes*.", footnotes: ["℘ Pred 10,12", "℘ Kap. 15,28; Mt 12,35"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Trügerische Waagschalen sind dem HERRN ein Gräuel*, aber volles Gewicht hat sein Wohlgefallen*.", footnotes: ["℘ Kap. 20,10; Hos 12,8", "℘ Kap. 16,11"] },
      { number: 2, text: "Kommt Übermut, kommt auch Schande*, doch bei den Bescheidenen ist Weisheit.", footnotes: ["℘ Dan 4,27-30"] },
      { number: 3, text: "Die Rechtschaffenheit* der Aufrichtigen leitet sie sicher, die Falschheit der Treulosen aber zerstört sie selbst.*", footnotes: ["o. Lauterkeit", "℘ Kap. 28,18; 4Mo 31,8"] },
      { number: 4, text: "Nichts nützt Reichtum am Tag des Zornes*, Gerechtigkeit aber rettet vom Tod.*", footnotes: ["℘ Hi 20,28; Jes 10,3; Hes 7,19; Zef 1,18", "℘ Kap. 10,2; Hes 14,14"] },
      { number: 5, text: "Die Gerechtigkeit des Lauteren* ebnet ihm den Weg*, doch der Gottlose kommt durch seine Gottlosigkeit zu Fall.*", footnotes: ["o. Untadligen; o. Vollkommenen", "℘ Kap. 15,19; Jes 26,7", "℘ Kap. 1,18; 13,6; 14,32; Hi 18,7; Hos 5,5"] },
      { number: 6, text: "Die Gerechtigkeit der Aufrichtigen rettet sie, aber durch ihre Gier* werden die Treulosen gefangen*.*", footnotes: ["o. Willkür", "so mit den alten Üs.; Mas. T.: aber durch die Gier der Gottlosen werden sie gefangen", "℘ Kap. 5,22.23"] },
      { number: 7, text: "Mit dem Tod eines gottlosen Menschen geht <seine> Hoffnung verloren, und die trügerische Erwartung ist verloren.*", footnotes: ["℘ Kap. 10,28.29"] },
      { number: 8, text: "Der Gerechte wird aus der Bedrängnis befreit*, und es kommt der Gottlose an seine Stelle*.", footnotes: ["℘ Ps 37,39", "℘ Kap. 21,18; Est 7,10; Dan 6,25; 2Thes 1,6"] },
      { number: 9, text: "Mit dem Mund richtet der Ruchlose seinen Nächsten zugrunde, aber durch Erkenntnis werden die Gerechten befreit." },
      { number: 10, text: "Beim Wohl der Gerechten jauchzt die Stadt*, und beim Untergang der Gottlosen ist Jubel*.", footnotes: ["℘ Kap. 28,12; 2Kö 11,20", "℘ 2Chr 23,13.21; Est 8,15; Jer 51,48"] },
      { number: 11, text: "Durch den Segen der Aufrichtigen steigt eine Stadt auf, durch den Mund der Gottlosen aber wird sie niedergerissen." },
      { number: 12, text: "Wer seinen Nächsten verachtet, ist ohne Verstand*, aber ein verständiger Mann schweigt*.", footnotes: ["℘ Kap. 14,21; Lk 18,11", "℘ Kap. 10,19"] },
      { number: 13, text: "Wer als Verleumder umhergeht, gibt Anvertrautes preis*; wer aber zuverlässigen Sinnes ist, hält die Sache verborgen*.", footnotes: ["w. deckt vertraute Beratung auf\n℘ Kap. 20,19", "℘ Kap. 10,19"] },
      { number: 14, text: "Wo es an Führung* fehlt, kommt ein Volk zu Fall, doch <kommt> Rettung durch viele Ratgeber.*", footnotes: ["o. an weisem Rat", "℘ Kap. 20,18; 24,6"] },
      { number: 15, text: "Schlecht, ja schlecht geht es einem, wenn er für einen Fremden bürgt; wer aber Handschlag hasst, ist sicher.*", footnotes: ["℘ Kap. 6,1-5"] },
      { number: 16, text: "Eine anmutige Frau erlangt Ehre*, *aber ein Thron der Schande ist eine Frau, die Redlichkeit hasst. Den Faulen fehlt es an Besitz*, die Fleißigen* aber erlangen Reichtum.", footnotes: ["℘ 1Sam 25,40", "so mit LXX; Mas. T. überliefert diesen Text nicht", "so mit LXX; Mas. T. überliefert diesen Text nicht", "so mit LXX; Mas. T.: Gewalthaber, o. Gewalttätigen"] },
      { number: 17, text: "Es erweist der Gütige sich selbst* Gutes*, doch schneidet sich ins eigene Fleisch* der Grausame*.", footnotes: ["w. seiner <eigenen> Seele", "℘ Ps 41,2-4; Jes 58,7-9; Mt 5,7", "o. bringt sich selbst ins Unglück; w. trübt sein Fleisch", "℘ Hi 20,16; Jak 2,13; 5,3"] },
      { number: 18, text: "Der Gottlose schafft <sich> trügerischen Gewinn, wer aber Gerechtigkeit sät, dauerhaften Lohn.*", footnotes: ["℘ Hos 10,2; Gal 6,8.9"] },
      { number: 19, text: "Steht einer fest in der Gerechtigkeit, <führt das> zum Leben*, jagt er dem Bösen nach, <gereicht es> zu seinem Tod*.", footnotes: ["℘ Kap. 21,21; 5Mo 16,20", "℘ 2Kö 1,4.16; Röm 6,21.23"] },
      { number: 20, text: "Ein Gräuel für den HERRN sind die mit verschlagenem* Herzen*; aber sein Wohlgefallen sind <Menschen> mit untadligem Wandel*.", footnotes: ["w. mit verdrehtem", "℘ Kap. 15,26", "℘ Kap. 12,22"] },
      { number: 21, text: "Die Hand darauf! Der Böse bleibt nicht ungestraft*; aber die Nachkommen der Gerechten entrinnen*.", footnotes: ["℘ 2Mo 23,7; Hi 36,17", "℘ Kap. 12,21; Ps 112,2"] },
      { number: 22, text: "Ein goldener Ring im Rüssel einer Sau, <so> ist eine Frau, die schön, aber ohne Feingefühl* ist.*", footnotes: ["o. ohne Verstand; o. ohne Unterscheidungsvermögen", "℘ Kap. 12,4; 31,30"] },
      { number: 23, text: "Das Begehren der Gerechten <bringt> lauter Gutes*, <aber> das Hoffen der Gottlosen Zorn*.", footnotes: ["℘ Kap. 12,5", "℘ Kap. 13,2"] },
      { number: 24, text: "Da ist einer, der ausstreut, und er bekommt immer mehr*, und einer, der mehr spart, als recht ist, <und es gereicht ihm> nur zum Mangel*.", footnotes: ["℘ 5Mo 15,10; 2Kor 9,6", "℘ Hag 1,9; Mal 3,8-11"] },
      { number: 25, text: "Wer gern wohltut, wird reichlich gesättigt*, und wer <andere> tränkt, wird auch selbst getränkt.*", footnotes: ["w. Die Seele des Segenswunsches wird fett gemacht", "℘ Jes 58,10"] },
      { number: 26, text: "Wer Getreide zurückhält, den verwünschen die Leute; aber Segen <kommt> auf das Haupt dessen, der Getreide verkauft.*", footnotes: ["℘ Kap. 10,6; 28,27; 1Mo 47,14; Hi 29,13"] },
      { number: 27, text: "Wer auf das Gute aus ist, sucht Wohlgefallen*; wer aber nach Bösem trachtet, über den wird es kommen.", footnotes: ["℘ Kap. 22,9"] },
      { number: 28, text: "Wer auf seinen Reichtum vertraut, der wird fallen*, aber wie Laub werden die Gerechten sprossen.", footnotes: ["℘ Hi 31,24; Mk 10,24"] },
      { number: 29, text: "Wer sein Haus zerrüttet*, wird Wind erben; und der Narr wird zum Sklaven dessen, der weisen Herzens ist.", footnotes: ["o. vernachlässigt"] },
      { number: 30, text: "Die Frucht des Gerechten* ist ein Baum des Lebens*, und der Weise gewinnt Menschen für sich*.", footnotes: ["LXX: Die Frucht der Gerechtigkeit", "℘ Kap. 12,12", "w. gewinnt Seelen für sich. — LXX: aber Gewalttat raubt das Leben"] },
      { number: 31, text: "Wenn dem Gerechten auf Erden vergolten wird*, wie viel mehr dem Gottlosen und Sünder!*", footnotes: ["℘ Ps 58,12", "℘ Jes 3,11; 13,11; Hes 44,10.12; Hos 4,9; 1Petr 4,18"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Wer Zucht liebt, liebt Erkenntnis*; und wer Ermahnung* hasst, ist dumm*.", footnotes: ["℘ Kap. 10,8", "o. Rüge", "℘ Kap. 15,10.12"] },
      { number: 2, text: "Der Gute erlangt Wohlgefallen von dem HERRN, aber den Ränkeschmied spricht er schuldig.*", footnotes: ["℘ Kap. 14,17"] },
      { number: 3, text: "Keinen Bestand hat ein Mensch durch Gottlosigkeit*, aber die Wurzel der Gerechten wird nicht ins Wanken gebracht*.", footnotes: ["℘ Pred 8,8", "℘ Kap. 10,25"] },
      { number: 4, text: "Eine tüchtige Frau ist die Krone ihres Mannes*, aber wie Wurmfraß* in seinen Knochen ist eine schandbare*.", footnotes: ["w. ihres <Ehe>herrn\n℘ Kap. 18,22; 31,10.29; 1Kor 11,7", "o. Fäulnis", "o. eine, die schändlich handelt\n℘ Kap. 11,22; 30,23"] },
      { number: 5, text: "Die Gedanken der Gerechten sind Recht*, die Überlegungen* der Gottlosen sind Betrug*.", footnotes: ["℘ Kap. 11,23", "o. Steuerungen", "℘ Kap. 14,8; Jer 9,3-5"] },
      { number: 6, text: "Die Worte der Gottlosen sind ein Lauern auf Blut*; aber der Mund der Aufrichtigen rettet sie*.", footnotes: ["℘ Kap. 1,11.18", "d. h. die Aufrichtigen oder die, deren Leben durch die Gottlosen bedroht ist\n℘ Kap. 14,3"] },
      { number: 7, text: "Es stürzen die Gottlosen, und sie sind nicht mehr*; aber das Haus der Gerechten bleibt stehen.", footnotes: ["℘ Kap. 14,11; Ps 37,36"] },
      { number: 8, text: "Gemäß seiner Einsicht wird ein Mann gelobt*; wer aber verkehrten Herzens ist, verfällt der Verachtung*.", footnotes: ["℘ 1Mo 41,39; Lk 16,8", "℘ 1Sam 2,30; Mal 2,9"] },
      { number: 9, text: "Besser, wer gering geachtet ist, aber einen Knecht hat*, als wer vornehm tut, aber Mangel an Brot hat.", footnotes: ["o. sein eigener Knecht ist. — LXX: und für sich selbst arbeitet"] },
      { number: 10, text: "Der Gerechte kümmert sich um das Wohlergehen* seines Viehes*, aber das Herz* der Gottlosen ist grausam*.", footnotes: ["o. kennt den Hunger; w. kennt die Seele", "℘ 1Mo 33,13", "w. die Eingeweide . . . sind", "℘ 4Mo 22,29"] },
      { number: 11, text: "Wer sein Ackerland bebaut, wird sich satt essen können an Brot*; wer aber nichtigen Dingen nachjagt, ist ohne Verstand.", footnotes: ["℘ Kap. 13,23; 20,13; 28,19"] },
      { number: 12, text: "Den Gottlosen gelüstet es nach dem Fang böser Dinge*, aber die Wurzel der Gerechten bleibt* beständig*.", footnotes: ["℘ Kap. 21,10", "so mit LXX; Mas. T.: gibt", "℘ Kap. 11,30"] },
      { number: 13, text: "Im Vergehen* der Lippen ist ein böser Fallstrick*, aber der Gerechte entkommt der Bedrängnis*.", footnotes: ["o. Im <Treue>bruch", "℘ Kap. 10,8; Ps 59,13", "℘ Ps 34,20"] },
      { number: 14, text: "Von der Frucht seines Mundes kann man sich satt essen an Gutem*, und das Tun der Hände eines Menschen kehrt zu ihm zurück*.", footnotes: ["℘ Kap. 13,2; 14,14", "so mit der Schreibform des Mas. T.; mit der Leseform: vergilt man ihm\n℘ Kap. 5,22; Jer 17,10"] },
      { number: 15, text: "Der Weg des Narren erscheint in seinen <eigenen> Augen recht*, der Weise aber hört auf Rat*.", footnotes: ["℘ Kap. 26,12", "℘ Kap. 13,1.10"] },
      { number: 16, text: "Der Narr — sein Unmut tut sich an demselben Tag <noch> kund, wer aber die Schmach verborgen hält, ist klug.*", footnotes: ["℘ Kap. 29,11"] },
      { number: 17, text: "Wer die Wahrheit spricht, bringt Rechtes vor*, ein falscher Zeuge hingegen <nur> Betrug.*", footnotes: ["o. Beständiges wirkt, wer recht aussagt", "℘ Kap. 14,5.25"] },
      { number: 18, text: "Da ist ein Schwätzer, <dessen Worte sind> Schwertstiche*; aber die Zunge der Weisen ist Heilung*.", footnotes: ["℘ Ps 57,5", "o. Heilmittel\n℘ Kap. 4,22; 16,24"] },
      { number: 19, text: "Die wahrhaftige Lippe besteht für immer, aber nur einen Augenblick lang* die lügnerische Zunge.*", footnotes: ["w. solange ich stillhalte", "℘ 2Kö 5,26; Ps 52,6.7; Apg 5,1-10"] },
      { number: 20, text: "Betrug ist im Herzen derer, die Böses schmieden*; bei denen aber, die zum Frieden raten*, ist Freude*.", footnotes: ["w. pflügen\n℘ Kap. 26,24; Ps 119,118; Dan 11,27", "o. Heilsames beschließen", "℘ Mt 5,9"] },
      { number: 21, text: "Keinerlei Unheil wird dem Gerechten widerfahren*, aber die Gottlosen sind voller Unglück.", footnotes: ["℘ Kap. 11,21; Ps 121,7; Pred 7,18; Röm 8,28"] },
      { number: 22, text: "Ein Gräuel für den HERRN sind Lippen, die lügen*; wer aber Treue* übt, hat sein Wohlgefallen*.", footnotes: ["w. Lippen der Lüge\n℘ Kap. 6,16.17", "o. Wahrheit; o. Beständigkeit", "℘ Kap. 11,20"] },
      { number: 23, text: "Ein kluger Mensch hält <seine> Erkenntnis verborgen*, aber das Herz der Toren schreit Narrheit hinaus*.", footnotes: ["℘ Kap. 10,19; 14,33; 1Sam 10,16; Neh 2,12.16", "℘ Kap. 13,16; 18,2"] },
      { number: 24, text: "Die Hand der Fleißigen wird herrschen, aber die lässige <Hand> muss Zwangsarbeit tun.*", footnotes: ["℘ Kap. 10,4"] },
      { number: 25, text: "Kummer im Herzen des Mannes drückt es nieder*, aber ein gutes Wort erfreut es*.", footnotes: ["℘ Kap. 15,13; 17,22", "℘ Kap. 15,23.30"] },
      { number: 26, text: "Der Gerechte erspäht seine Weide*, aber der Weg der Gottlosen führt sie in die Irre.*", footnotes: ["so mit anderer Vokalisierung; Mas. T.: Der Gerechte lässt seinen Freund ausspähen", "℘ Kap. 14,22"] },
      { number: 27, text: "Nicht erjagt* die Lässigkeit ihr Wild*; aber kostbarer Besitz eines Menschen ist es, wenn er fleißig ist*.", footnotes: ["o. brät. — LXX, die lat. und die syr. Üs.: erlangt", "℘ Kap. 13,4", "LXX und die syr. Üs. lesen mit Umstellung zweier Wörter: aber kostbaren Besitz erlangt der Mensch, der fleißig ist\n℘ Kap. 10,4"] },
      { number: 28, text: "Auf dem Pfad der Gerechtigkeit ist Leben*, aber der Weg der Rachsüchtigen <führt> zum Tod*.", footnotes: ["℘ Kap. 10,2.16; 5Mo 30,19; Hes 18,9", "so mit LXX; Mas. T. viell.: und in Richtung <dieses> Weges gibt es keinen Tod"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Ein weiser Sohn lässt sich vom Vater zurechtweisen*, aber ein Spötter hört nicht auf Zurechtweisung*.", footnotes: ["Der Text kann nur annähernd üs. werden; andere mit Textänderung: Ein weiser Sohn liebt die Zucht\n℘ Kap. 4,1; 7,24; 12,15; 1Kö 22,43", "℘ Kap. 15,5.12; 1Sam 2,25"] },
      { number: 2, text: "Man kann von der Frucht seines Mundes Gutes essen*, aber die Begierde* der Treulosen ist Gewalttat*.", footnotes: ["℘ Kap. 12,14; 18,20", "w. Seele", "℘ Kap. 11,23"] },
      { number: 3, text: "Wer seinen Mund behütet, bewahrt sein Leben*; wer seine Lippen aufreißt, dem <droht> Verderben*.", footnotes: ["o. sich selbst; o. seine Seele\n℘ Kap. 14,3; 21,23; Ri 16,17", "℘ Kap. 10,8"] },
      { number: 4, text: "Gierig ist die Seele des Faulen*, doch ist nichts da*; aber die Seele der Fleißigen wird reichlich gesättigt*.", footnotes: ["T.; Mas. T.: Gierig ist der Faule <in> seiner Seele", "℘ Kap. 12,27; 20,4; 24,30-34", "w. wird fett gemacht\n℘ Kap. 10,4"] },
      { number: 5, text: "Der Gerechte hasst Lügenrede*, aber der Gottlose handelt schändlich und schmählich*.", footnotes: ["o. betrügerisches Wesen\n℘ Kap. 30,8; Ps 119,163", "o. bringt in üblen Geruch und in Schmach\n℘ Kap. 18,3"] },
      { number: 6, text: "Die Gerechtigkeit behütet die Vollkommenheit des Wandels*, aber die Gottlosen bringt die Sünde zu Fall*.*", footnotes: ["Andere üs. mit Textänderung: den im Wandel Vollkommenen", "so mit hebr. Handschr. und griech. Üs.; Mas. T.: und die Gottlosigkeit bringt die Sünde zu Fall", "℘ Kap. 11,5.6; 1Kö 1,52; 13,34"] },
      { number: 7, text: "Da ist einer, der sich reich stellt, und hat gar nichts*; <und> einer, der sich arm stellt, und hat doch viel Besitz.", footnotes: ["℘ Offb 3,17"] },
      { number: 8, text: "Lösegeld für das Leben eines Mannes ist sein Reichtum*, aber der Arme hört keine Drohung.", footnotes: ["℘ Hi 2,4; Jer 41,8"] },
      { number: 9, text: "Das Licht der Gerechten brennt fröhlich*, aber die Leuchte der Gottlosen erlischt*.", footnotes: ["℘ Kap. 4,18", "℘ Kap. 20,20; 24,20; Hi 18,5.6"] },
      { number: 10, text: "Durch Übermut gibt es nur Zank*; bei denen aber, die sich raten lassen, Weisheit*.", footnotes: ["℘ Kap. 28,25", "℘ Kap. 12,15; 19,20"] },
      { number: 11, text: "Schnell erworbener Besitz* wird <schnell> weniger*; wer aber händeweise sammelt, vermehrt <ihn>*.", footnotes: ["so mit LXX und syr. Üs.; Mas. T.: Besitz aus dem Nichtigen", "℘ Kap. 10,2; 21,6; Jer 17,11", "℘ Kap. 28,20"] },
      { number: 12, text: "Hingezogene Hoffnung macht das Herz krank*, aber ein eingetroffener Wunsch ist ein Baum des Lebens*.", footnotes: ["℘ Neh 2,2; Ps 143,7", "℘ Kap. 3,18"] },
      { number: 13, text: "Wer das Wort verachtet, bei dem wird gepfändet*; wer aber das Gebot fürchtet, dem wird vergolten.*", footnotes: ["o. dem geht es schlecht", "℘ Kap. 16,20; Ps 19,12"] },
      { number: 14, text: "Die Weisung des Weisen ist eine Quelle des Lebens*, um zu entgehen den Fallen des Todes*.", footnotes: ["℘ Kap. 16,22", "℘ Kap. 10,11; 14,27; 1Sam 25,33"] },
      { number: 15, text: "Gute Einsicht verschafft Gunst, aber der Weg der Treulosen ist ihr Unglück*.", footnotes: ["so mit LXX; Mas. T.: ist beständig"] },
      { number: 16, text: "Jeder Kluge handelt* mit Bedacht; ein Tor aber breitet Narrheit aus.*", footnotes: ["die lat. und die syr. Üs.: Der Kluge tut alles", "℘ Kap. 12,23; 14,33; Pred 10,3.13"] },
      { number: 17, text: "Ein gottloser Bote stürzt ins Unglück*, aber ein treuer Gesandter ist Heilung*.", footnotes: ["℘ 4Mo 31,8", "℘ Kap. 25,13"] },
      { number: 18, text: "Armut und Schande dem, der Züchtigung* unbeachtet lässt*; wer aber Zurechtweisung* beachtet, wird geehrt*.", footnotes: ["o. Ermahnung", "℘ Jer 3,25", "o. Warnung", "℘ Kap. 15,31"] },
      { number: 19, text: "Ein erfüllter Wunsch erquickt die Seele, aber ein Gräuel ist es den Toren, vom Bösen zu weichen.*", footnotes: ["℘ Kap. 29,10.27"] },
      { number: 20, text: "Wer mit Weisen umgeht, wird weise*; aber wer sich mit Toren einlässt, dem wird es schlecht gehen.*", footnotes: ["so mit der Leseform des Mas. T.; mit der Schreibform: Geh mit Weisen um, werde weise", "℘ Kap. 14,7; 22,24.25; 1Kor 15,33"] },
      { number: 21, text: "Unheil verfolgt die Sünder*, aber Glück belohnt die Gerechten*.", footnotes: ["℘ Kap. 24,16", "℘ Ps 32,10"] },
      { number: 22, text: "Der Gute vererbt auf Kindeskinder*, aber das Vermögen des Sünders wird aufbewahrt für den Gerechten*.", footnotes: ["℘ Ps 112,2", "℘ Kap. 28,8; Hi 27,17"] },
      { number: 23, text: "Reichlich Nahrung <bringt> der Neubruch der Armen*, aber mancher wird weggerafft durch Unrecht*.", footnotes: ["℘ Kap. 12,11", "o. doch wird <Besitz> weggerafft, wo kein Recht ist"] },
      { number: 24, text: "Wer seine Rute schont, hasst seinen Sohn; aber wer ihn lieb hat, züchtigt ihn beizeiten*.*", footnotes: ["w. sucht ihn mit Züchtigung", "℘ Kap. 19,18; Hebr 12,6"] },
      { number: 25, text: "Der Gerechte hat zu essen bis zur Sättigung seiner Seele, aber der Leib der Gottlosen bleibt leer.*", footnotes: ["℘ Jes 65,13"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Die Weisheit der Frauen baut ihr Haus*, aber die Narrheit reißt es mit eigenen Händen nieder.", footnotes: ["℘ Kap. 24,3; 31,10-27"] },
      { number: 2, text: "Wer in seiner Geradheit lebt*, fürchtet den HERRN*; wer aber in seinen Wegen verkehrt ist, verachtet ihn*.", footnotes: ["w. geht", "℘ Kap. 16,6; Hi 1,1; Mal 2,5.6", "o. wer ihn aber verachtet, geht krumme Wege\n℘ 2Sam 12,9.10; 2Kö 17,34"] },
      { number: 3, text: "Im Mund des Narren ist eine Rute für den Hochmut*; aber die Lippen der Weisen bewahren sie*.", footnotes: ["Andere üs. mit Textänderung: eine Rute für seinen Rücken\n℘ Kap. 18,7", "d. h. die Weisen, o. die Weisheit\n℘ Kap. 12,6; 13,3"] },
      { number: 4, text: "Wo keine Rinder sind, ist die Krippe leer*, doch <kommt> reichlicher Ertrag durch die Kraft des Stieres.", footnotes: ["o. <bleibt> die Krippe <zwar> sauber"] },
      { number: 5, text: "Ein treuer Zeuge lügt nicht, aber ein falscher Zeuge bringt Lügen vor*.*", footnotes: ["w. schnaubt Lügen", "℘ V. 25; Kap. 6,19"] },
      { number: 6, text: "Der Spötter sucht Weisheit, doch sie ist nicht da*; aber für den Verständigen ist Erkenntnis ein Leichtes*.", footnotes: ["℘ Kap. 15,12; 17,16; 24,7", "℘ Kap. 8,8.9"] },
      { number: 7, text: "Tritt einem törichten Mann gegenüber, und* du wirst keine verständigen Lippen kennenlernen.*", footnotes: ["o. Geh einem törichten Mann aus dem Weg, denn", "℘ Kap. 13,20; Jer 28,11"] },
      { number: 8, text: "Die Weisheit des Klugen ist es, seinen Weg zu begreifen, aber die Narrheit der Toren ist Täuschung.*", footnotes: ["℘ Kap. 12,5; Pred 2,13"] },
      { number: 9, text: "Schuld macht Narren frech*, aber unter den* Aufrichtigen* ist Wohlgefallen*.", footnotes: ["o. Schuld macht Narren lächerlich; o. Die Narren treiben Spott mit der Schuld\n℘ Kap. 10,23", "Andere üs. in Anlehnung an LXX: In den Zelten der Narren <wohnt> Schuld, aber in den Häusern der", "o. Geraden", "℘ Apg 27,3"] },
      { number: 10, text: "Das Herz kennt sein eigenes Leid*, und kein Fremder kann sich in seine Freude mischen.", footnotes: ["w. die Bitterkeit seiner Seele\n℘ 1Sam 1,15; Hi 6,2-4"] },
      { number: 11, text: "Das Haus der Gottlosen wird ausgetilgt*, aber das Zelt der Aufrichtigen* blüht auf*.", footnotes: ["℘ Kap. 12,7; 15,25", "o. Geraden", "℘ Kap. 3,33; Hi 8,15.22; Ps 37,10.11"] },
      { number: 12, text: "Da ist ein Weg, der einem Menschen gerade erscheint, aber zuletzt sind es Wege des Todes.*", footnotes: ["℘ Kap. 16,25; 1Kö 12,26.28; Mt 7,13"] },
      { number: 13, text: "Sogar beim Lachen kann das Herz Kummer haben, und zuletzt <wird aus> Freude Traurigkeit.*", footnotes: ["℘ Pred 2,2"] },
      { number: 14, text: "Von seinen Wegen wird satt, wer abtrünnigen Herzens ist*, und von dem, was in ihm ist*, <wird satt> der gute Mann*.", footnotes: ["℘ Kap. 1,31", "o. über ihm ist; o. auf ihm ist. — Andere üs. mit Textänderung: und von seinen Taten", "℘ Kap. 12,14"] },
      { number: 15, text: "Der Einfältige* glaubt jedem Wort, aber der Kluge achtet auf seinen Schritt.", footnotes: ["o. Unerfahrene(n); o. Unverständige(n)"] },
      { number: 16, text: "Der Weise fürchtet sich und meidet das Böse*, aber der Tor braust auf und fühlt sich sicher*.", footnotes: ["℘ Kap. 3,7; 1Thes 5,22", "o. und kommt zu Fall\n℘ Kap. 1,32; 22,3"] },
      { number: 17, text: "Der Jähzornige begeht Narrheit*, und der Ränkeschmied wird gehasst*.", footnotes: ["℘ Kap. 20,3", "Andere üs. in Anlehnung an LXX: aber der verständige Mann wird erhöht\n℘ Kap. 12,2"] },
      { number: 18, text: "Die Einfältigen* erben Narrheit, die Klugen aber werden mit Erkenntnis gekrönt.*", footnotes: ["o. Unerfahrene(n); o. Unverständige(n)", "℘ Kap. 4,9"] },
      { number: 19, text: "Die Bösen müssen sich niederbeugen vor den Guten und die Gottlosen an den Türen des Gerechten.*", footnotes: ["℘ Jes 60,14; Offb 3,9"] },
      { number: 20, text: "Selbst seinem Nächsten ist der Arme verhasst, aber die Freunde des Reichen sind zahlreich.*", footnotes: ["℘ Kap. 19,4.6.7; Hi 42,11"] },
      { number: 21, text: "Wer seinem Nächsten Verachtung zeigt, sündigt*; aber wohl dem, der sich über die Elenden erbarmt*!", footnotes: ["℘ Kap. 11,12; 5Mo 15,9; Röm 14,10", "℘ Kap. 22,9; Ps 41,2"] },
      { number: 22, text: "Gehen nicht irre <alle>, die Böses schmieden*?* Aber Gnade und Treue <erfahren die>, die Gutes schmieden*.*", footnotes: ["w. pflügen", "℘ Kap. 6,14; 12,26", "w. pflügen", "℘ Jos 2,14"] },
      { number: 23, text: "Bei jeder Mühe ist Gewinn,* aber bloßes Gerede* <führt> nur zum Mangel.", footnotes: ["℘ Pred 3,9", "w. ein Wort der Lippen"] },
      { number: 24, text: "Die Krone der Weisen ist ihr Reichtum*; die Narrheit der Toren ist <nur> Narrheit*.*", footnotes: ["Andere üs. in Anlehnung an LXX: ihre Klugheit", "Andere üs. mit Textänderung: aber der Kranz der Toren ist ihre Narrheit", "℘ Kap. 27,22"] },
      { number: 25, text: "Ein wahrhaftiger Zeuge ist Lebensretter*; wer aber Lügen vorbringt*, ist <lauter> Betrug.*", footnotes: ["o. ist einer, der Seelen rettet", "w. schnaubt", "℘ V. 5; Kap. 12,17; 19,5.9"] },
      { number: 26, text: "In der Furcht des HERRN <liegt> ein starkes Vertrauen*, auch seine* Kinder haben eine Zuflucht*.", footnotes: ["℘ Kap. 18,10", "d. h. dessen, der den HERRN fürchtet", "℘ Kap. 20,7; Ps 102,29; Jes 33,6"] },
      { number: 27, text: "Die Furcht des HERRN ist eine Quelle des Lebens, um die Fallen des Todes zu meiden.*", footnotes: ["℘ Kap. 13,14; 19,23"] },
      { number: 28, text: "In der Menge des Volkes <besteht> die Herrlichkeit eines Königs*, aber durch Mangel an Leuten <kommt> der Untergang eines Fürsten*.", footnotes: ["℘ 2Sam 24,3; 1Kö 4,20", "℘ Jer 13,20"] },
      { number: 29, text: "Der Langmütige ist reich an Verständnis*, aber der Jähzornige trägt Narrheit davon*.", footnotes: ["℘ Kap. 15,18; 16,32; 19,11; Pred 7,8", "o. treibt die Narrheit auf die Spitze"] },
      { number: 30, text: "Ein gelassenes Herz ist des Leibes Leben, aber Wurmfraß in den Knochen ist die Leidenschaft*.", footnotes: ["o. die Eifersucht"] },
      { number: 31, text: "Wer den Geringen unterdrückt, verhöhnt* den, der ihn gemacht hat*; aber ihn ehrt, wer sich über den Armen erbarmt*.", footnotes: ["o. Wer den Hilflosen erpresst, reizt", "℘ Kap. 17,5; 22,2", "℘ 3Mo 25,35; Mt 25,40"] },
      { number: 32, text: "In seinem Unglück wird der Gottlose umgestoßen*, aber der Gerechte ist <noch> in seinem Tode geborgen*.", footnotes: ["℘ Kap. 5,22", "LXX und syr. Üs.: der Gerechte birgt sich in seiner Lauterkeit"] },
      { number: 33, text: "Im Herzen des Verständigen ruht die Weisheit*, aber unter den Toren schwitzt sie*.", footnotes: ["o. lässt sich die Weisheit nieder\n℘ Kap. 12,23", "LXX: wird sie nicht bekannt"] },
      { number: 34, text: "Gerechtigkeit erhöht eine Nation*, aber Sünde ist die Schande der Völker*.", footnotes: ["℘ Kap. 29,4; 5Mo 4,6", "℘ 2Chr 28,19"] },
      { number: 35, text: "Des Königs Wohlgefallen wird dem klugen Knecht <zuteil>*; aber den schandbaren trifft sein Zorn*.", footnotes: ["℘ Kap. 16,13; 1Mo 41,38", "℘ Est 7,7; Lk 19,17-27"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Eine sanfte Antwort wendet Grimm ab*, aber ein kränkendes Wort erregt Zorn*.", footnotes: ["℘ Kap. 25,15; 29,8; Ri 8,1-3", "℘ 2Sam 19,44; 1Kö 12,7.16"] },
      { number: 2, text: "Die Zunge der Weisen fördert Erkenntnis, aber der Mund der Toren lässt Narrheit sprudeln." },
      { number: 3, text: "Die Augen des HERRN sind an jedem Ort und schauen aus auf Böse und auf Gute.*", footnotes: ["℘ Kap. 5,21; 2Chr 16,9"] },
      { number: 4, text: "Gelassenheit der Zunge ist ein Baum des Lebens*, aber Falschheit in ihr ist Zerbruch des Geistes.", footnotes: ["℘ Kap. 10,11"] },
      { number: 5, text: "Ein Narr verschmäht die Zucht seines Vaters*; wer aber die Zurechtweisung* beachtet, ist klug*.", footnotes: ["℘ Kap. 1,7", "o. Warnung", "o. wird klug"] },
      { number: 6, text: "Im Haus des Gerechten ist reichlich Vorrat*; aber das Einkommen des Gottlosen ist Zerrüttung.", footnotes: ["℘ Kap. 3,33; 21,20"] },
      { number: 7, text: "Die Lippen der Weisen streuen Erkenntnis aus*, aber das Herz der Toren Unrecht*.", footnotes: ["℘ Kap. 10,21; 16,23", "o. das Herz der Toren ist nicht recht\n℘ Pred 10,2"] },
      { number: 8, text: "Das Opfer der Gottlosen ist ein Gräuel für den HERRN*, aber das Gebet der Aufrichtigen* sein Wohlgefallen*.", footnotes: ["℘ Kap. 21,27; 28,9; 2Sam 15,12; Jes 1,11.13; Am 5,22; Mi 6,6.7; Mal 1,10", "o. Geraden", "℘ Ps 141,2; Dan 9,23"] },
      { number: 9, text: "Ein Gräuel für den HERRN ist der Weg des Gottlosen*; wer aber der Gerechtigkeit nachjagt, den liebt er*.", footnotes: ["℘ Ps 5,5-7", "℘ Ps 11,7; Jes 51,1"] },
      { number: 10, text: "Schlimme Züchtigung für den, der den Pfad verlässt*; wer Zurechtweisung* hasst, muss sterben*.", footnotes: ["℘ Hi 34,27; Jer 2,17; 2Petr 2,15-17", "o. Warnung", "℘ Kap. 12,1; Hes 33,9"] },
      { number: 11, text: "Scheol und Abgrund* <liegen offen> vor dem HERRN*, wie viel mehr die Herzen der Menschenkinder*!", footnotes: ["d. i. der Ort des Untergangs; der Aufenthaltsort der Toten", "℘ Hi 26,6; Ps 139,8", "℘ 1Sam 16,7; 2Chr 6,30"] },
      { number: 12, text: "Der Spötter liebt es nicht, dass man ihn zurechtweist*; zu den Weisen geht er nicht*.", footnotes: ["℘ Kap. 13,1", "℘ Kap. 14,6"] },
      { number: 13, text: "Ein fröhliches Herz macht das Gesicht heiter*; aber beim Kummer des Herzens ist der Geist niedergeschlagen*.", footnotes: ["℘ Kap. 17,22", "℘ Kap. 12,25; Neh 2,2"] },
      { number: 14, text: "Das Herz des Verständigen sucht Erkenntnis*, aber der Mund* der Toren weidet sich an* Narrheit.", footnotes: ["℘ Kap. 18,15", "so mit der Leseform des Mas. T.; mit der Schreibform: das Gesicht", "o. beschäftigt sich mit"] },
      { number: 15, text: "Alle Tage des Elenden sind schlecht, aber ein fröhliches Herz <hat> ein ständiges Festmahl." },
      { number: 16, text: "Besser wenig in der Furcht des HERRN als ein großer Schatz und Unruhe* dabei.*", footnotes: ["o. plötzliche Bestürzung; o. Panik", "℘ Kap. 16,8; 17,1; Pred 4,6"] },
      { number: 17, text: "Besser ein Gericht Gemüse, und Liebe ist da, als ein gemästeter Ochse und Hass dabei.*", footnotes: ["℘ Kap. 16,8; 17,1; Pred 4,6"] },
      { number: 18, text: "Ein hitziger Mann erregt Zank*, aber ein Langmütiger beschwichtigt den Rechtsstreit*.", footnotes: ["o. zettelt <schnell> einen Prozess an\n℘ Kap. 22,24; 28,25; 29,22", "℘ Kap. 14,29"] },
      { number: 19, text: "Der Weg des Faulen ist wie eine Dornenhecke*, aber der Pfad der Aufrichtigen* ist gebahnt*.", footnotes: ["w. ist wie der Dornstrauch einer Dornenhecke\n℘ Kap. 6,6; 22,5", "o. Geraden", "℘ Kap. 11,5"] },
      { number: 20, text: "Ein weiser Sohn erfreut den Vater, aber ein törichter Mensch verachtet seine Mutter.*", footnotes: ["℘ Kap. 10,1; 23,22"] },
      { number: 21, text: "Narrheit ist dem Unverständigen Freude*, aber ein verständiger Mann geht den geraden Weg*.", footnotes: ["℘ Kap. 10,23", "w. macht das Gehen gerade\n℘ Kap. 4,25-27"] },
      { number: 22, text: "Pläne scheitern, wo keine Besprechung ist; wo aber viele Ratgeber sind, kommt etwas zustande.*", footnotes: ["℘ Kap. 20,18; 24,6; 1Chr 13,1"] },
      { number: 23, text: "Ein Mann hat Freude an der <treffenden> Antwort seines Mundes, und ein Wort zu seiner Zeit, wie gut!*", footnotes: ["℘ Kap. 12,25; 16,24; 25,11; Hi 6,25"] },
      { number: 24, text: "Der Weg des Lebens <geht> für den Einsichtigen nach oben, damit er dem Scheol unten entgeht." },
      { number: 25, text: "Das Haus der Hochmütigen reißt der HERR nieder*, aber er legt fest die Grenze der Witwe*.", footnotes: ["℘ Kap. 14,11", "℘ Hi 24,21; Ps 10,14; Jes 1,17; Jer 5,28"] },
      { number: 26, text: "Ein Gräuel für den HERRN sind die Anschläge des Bösen*, aber rein <vor ihm> sind freundliche Worte.", footnotes: ["℘ Kap. 6,18; 11,20"] },
      { number: 27, text: "Sein Haus zerrüttet, wer unrechten Gewinn macht*; wer aber <Bestechungs>geschenke hasst, wird leben*.", footnotes: ["℘ Kap. 1,19; Jos 7,25; Jes 5,8.9; Jer 17,11", "℘ Kap. 28,16; Ps 15,5"] },
      { number: 28, text: "Das Herz des Gerechten überlegt, was zu antworten ist*; aber der Mund der Gottlosen lässt Bosheiten sprudeln*.", footnotes: ["℘ Jak 1,19", "℘ Kap. 10,32"] },
      { number: 29, text: "Fern ist der HERR von den Gottlosen*, aber das Gebet der Gerechten hört er*.", footnotes: ["℘ Jes 59,2; Joh 9,31", "℘ Ps 34,16"] },
      { number: 30, text: "Leuchten der Augen* erfreut das Herz; eine gute Nachricht erquickt das Gebein.*", footnotes: ["o. Ein freundlicher Blick", "℘ Kap. 12,25; 25,25; 1Thes 3,6-8"] },
      { number: 31, text: "Ein Ohr, das auf heilsame Mahnung* hört, wird inmitten der Weisen bleiben.*", footnotes: ["w. Zurechtweisung zum Leben", "℘ Kap. 13,18; Pred 7,5"] },
      { number: 32, text: "Wer Zucht fahren lässt, verachtet sich selbst*; wer aber auf Zurechtweisung* hört, erwirbt Verstand.*", footnotes: ["w. Wer Züchtigung unbeachtet lässt, verachtet seine Seele", "o. Warnung", "℘ Kap. 10,17; 19,20"] },
      { number: 33, text: "Die Furcht des HERRN ist Zucht zur Weisheit*, und der Ehre geht Demut voran*.", footnotes: ["℘ Kap. 1,7", "℘ Kap. 18,12; Est 2,15; Lk 14,10"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Beim Menschen sind die Überlegungen des Herzens*, aber vom HERRN <kommt> die Antwort der Zunge*.", footnotes: ["℘ Hi 17,11", "℘ Kap. 19,21; 2Sam 7,5; Jer 10,23"] },
      { number: 2, text: "Alle Wege eines Mannes sind lauter in seinen Augen*, aber der die Geister prüft, ist der HERR*.", footnotes: ["℘ Ri 7,6", "℘ Kap. 17,3; 24,12; 4Mo 22,32"] },
      { number: 3, text: "Befiehl dem HERRN* deine Werke*, und deine Gedanken* werden zustande kommen.", footnotes: ["w. Wälze auf den HERRN", "℘ Ps 37,5", "o. Pläne; o. Vorhaben"] },
      { number: 4, text: "Alles hat der HERR zu seinem Zweck gemacht, so auch den Gottlosen für den Tag des Unglücks.*", footnotes: ["℘ Hi 15,23; Röm 9,22; 1Petr 2,8"] },
      { number: 5, text: "Ein Gräuel für den HERRN ist jeder Hochmütige. Die Hand darauf! Er bleibt nicht ungestraft.*", footnotes: ["℘ Kap. 6,17; 8,13; Jes 2,12; Röm 11,20.21"] },
      { number: 6, text: "Durch Güte* und Treue* wird Schuld gesühnt*, und durch die Furcht des HERRN weicht man vom Bösen*.", footnotes: ["o. Gnade", "℘ Kap. 3,3", "℘ Dan 4,24", "o. meidet man das Böse\n℘ Kap. 14,2; 2Mo 1,17; 3Mo 25,17.36.43; Hi 28,28"] },
      { number: 7, text: "Wenn der HERR an den Wegen eines Mannes Wohlgefallen hat, lässt er selbst seine Feinde mit ihm Frieden machen.*", footnotes: ["℘ Esr 8,36"] },
      { number: 8, text: "Besser wenig mit Gerechtigkeit als viel Einkommen mit Unrecht.*", footnotes: ["℘ Kap. 15,16.17; 17,1; 28,6; Ps 37,16"] },
      { number: 9, text: "Das Herz des Menschen plant seinen Weg, aber der HERR lenkt seinen Schritt.*", footnotes: ["℘ Kap. 20,24; 21,1; 1Sam 9,16; 2Chr 22,7"] },
      { number: 10, text: "Orakelspruch ist auf den Lippen des Königs*; beim Rechtsspruch redet sein Mund nicht treulos.", footnotes: ["o. Von den Lippen des Königs <kommt> Gottesentscheid\n℘ 2Sam 14,16"] },
      { number: 11, text: "Waagbalken und rechte Waagschalen* sind <Sache> des HERRN; sein Werk sind alle Gewichtsteine im Beutel.*", footnotes: ["o. Zeiger und Waagschalen des Rechts", "℘ Kap. 11,1; 3Mo 19,36"] },
      { number: 12, text: "Ein Gräuel ist für Könige gottloses Tun; denn durch Gerechtigkeit steht ein Thron fest.*", footnotes: ["℘ Kap. 25,5; 29,4; 2Chr 17,5"] },
      { number: 13, text: "Das Wohlgefallen des Königs* <finden> gerechte Lippen; und wer aufrichtig redet, den liebt er.*", footnotes: ["w. der Könige", "℘ Kap. 14,35; 22,11"] },
      { number: 14, text: "Der Zorn des Königs ist ein Todesbote*; aber ein weiser Mann wendet ihn ab*.", footnotes: ["w. Zorn des Königs — Todesboten\n℘ Kap. 20,2; 1Mo 40,2; 2Kö 6,31; Est 7,7; Dan 2,16.46", "w. deckt ihn zu; d. i. den Zorn\n℘ Kap. 19,12; 29,26"] },
      { number: 15, text: "Im Leuchten des Angesichts eines Königs ist Leben, und sein Wohlgefallen ist wie eine Wolke des Spätregens." },
      { number: 16, text: "Weisheit erwerben — wie viel besser ist es als Gold! Und Verständnis erwerben ist vorzüglicher als Silber!*", footnotes: ["℘ Kap. 2,4; 3,13; 8,10.19"] },
      { number: 17, text: "Die Straße der Aufrichtigen ist, vom Bösen zu weichen*; der bewahrt sein Leben*, der auf seinen Weg acht hat.*", footnotes: ["o. Das Ziel der Aufrichtigen ist es, Böses zu meiden", "o. seine Seele", "℘ Kap. 4,23; 19,16; 21,23; 22,5"] },
      { number: 18, text: "Vor dem Verderben* <kommt> Stolz, und Hochmut vor dem Fall.*", footnotes: ["o. Vor dem Zusammenbruch", "℘ Kap. 17,19; 18,12; 29,23; Est 6,6.13; Jer 50,32; Hes 28,17; Dan 4,30"] },
      { number: 19, text: "Besser bescheiden* sein mit Demütigen, als Beute teilen mit Hochmütigen.", footnotes: ["w. niedrigen Geistes"] },
      { number: 20, text: "Wer auf das Wort achtet, findet Gutes*, und glücklich der, der dem HERRN vertraut*!", footnotes: ["o. Glück\n℘ Kap. 13,13", "℘ Ps 2,12; 146,5"] },
      { number: 21, text: "Wer weisen Herzens ist, wird ein Verständiger genannt*; und Anmut der Sprache fördert das Lehren*.", footnotes: ["℘ Kap. 10,13.23", "o. Süßigkeit der Lippen fördert die Überredung"] },
      { number: 22, text: "Eine Quelle des Lebens ist Einsicht für ihre Besitzer*, aber die Züchtigung der Narren ist <ihre> Narrheit*.", footnotes: ["℘ Kap. 13,14", "℘ Kap. 18,7"] },
      { number: 23, text: "Das Herz des Weisen gibt seinem Mund Einsicht und fördert auf seinen Lippen das Lehren*.*", footnotes: ["o. steigert auf seinen Lippen die Überredungskunst", "℘ Kap. 5,2; 15,7; Hi 15,2"] },
      { number: 24, text: "Freundliche Worte sind Honig, Süßes für die Seele und Heilung* für das Gebein.*", footnotes: ["o. Heilmittel; o. Medizin", "℘ Kap. 12,18; 15,23; 27,9; Pred 12,10"] },
      { number: 25, text: "Da ist ein Weg, der einem Menschen gerade erscheint, aber zuletzt sind es Wege des Todes.*", footnotes: ["℘ Kap. 14,12"] },
      { number: 26, text: "Der Hunger* des Arbeiters arbeitet für ihn, denn sein Mund spornt ihn an.*", footnotes: ["w. Die Seele", "℘ Pred 6,7"] },
      { number: 27, text: "Ein ruchloser Mann* gräbt Unheil*, und auf seinen Lippen ist es wie sengendes Feuer.*", footnotes: ["w. Ein Mann der Bosheit o. der Nichtsnutzigkeit", "Andere üs. mit Textänderung: ist ein Ofen <voll> Bosheit", "℘ Kap. 6,12; 19,28; Jak 3,6"] },
      { number: 28, text: "Ein Mann der Falschheit lässt dem Zank freien Lauf*, und ein Verleumder entzweit Vertraute*.", footnotes: ["℘ Kap. 6,14.19; 18,6", "℘ Kap. 17,9; 26,20.21"] },
      { number: 29, text: "Ein Mann der Gewalttat verlockt seinen Nächsten und führt ihn auf einen Weg, der nicht gut ist." },
      { number: 30, text: "Wer seine Augen zukneift, <tut es,> um Falschheit zu ersinnen; wer seine Lippen zusammenkneift, hat das Böse <schon> fertig." },
      { number: 31, text: "Das graue Haar ist eine prächtige* Krone*, auf dem Weg der Gerechtigkeit findet man sie.", footnotes: ["o. zierende", "℘ Kap. 20,29; Pred 12,5"] },
      { number: 32, text: "Besser ein Langmütiger als ein Held, und besser, wer seinen Geist beherrscht, als wer eine Stadt erobert.*", footnotes: ["℘ Kap. 14,29; 25,15; Pred 7,9"] },
      { number: 33, text: "Im Gewandbausch schüttelt man das Los, aber all seine Entscheidung kommt vom HERRN.*", footnotes: ["℘ 3Mo 16,8; Jos 7,14; Ri 20,9; 1Sam 14,42; Jon 1,7; Apg 1,26"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Besser ein trockener Bissen und Ruhe* dabei als ein Haus voller Festspeisen, aber Streit dabei*.*", footnotes: ["w. Sorglosigkeit", "w. als ein Haus voller Schlachtopfer des Streites", "℘ Kap. 15,16.17; 16,8"] },
      { number: 2, text: "Ein verständiger Knecht wird Herr über einen schandbaren Sohn*, und mitten unter den Brüdern wird er die Erbschaft teilen.", footnotes: ["o. einen Sohn, der schändlich handelt"] },
      { number: 3, text: "Der Schmelztiegel für das Silber und der Ofen für das Gold*; aber ein Prüfer der Herzen ist der HERR*.", footnotes: ["℘ 1Petr 1,7", "℘ Kap. 16,2; 21,2; 27,21; 5Mo 8,2.16; Hi 23,10; Ps 66,10; Jer 17,10; 1Thes 2,4"] },
      { number: 4, text: "Ein Übeltäter hört auf die Lippe des Unheils, ein Lügner* schenkt Gehör der Zunge des Verderbens.*", footnotes: ["T.; Mas. T.: die Lüge", "℘ Jer 5,31"] },
      { number: 5, text: "Wer den Armen verspottet, verhöhnt den, der ihn gemacht hat*; wer sich über Unglück freut, bleibt nicht ungestraft*.", footnotes: ["℘ Kap. 14,31; Jak 2,6", "℘ Kap. 24,17.18; Hi 31,29; Hes 25,3; Ob 10-16"] },
      { number: 6, text: "Die Krone der Alten sind Kindeskinder*, und der Kinder Schmuck sind ihre Väter.", footnotes: ["℘ 1Mo 50,23; Hi 42,16"] },
      { number: 7, text: "Zu einem Törichten passt überragende Rede* nicht*; wie viel weniger zu einem Edlen lügnerische Rede!", footnotes: ["LXX: glaubhafte Rede", "℘ Kap. 26,7.9"] },
      { number: 8, text: "Ein Zauberstein* ist die Bestechung in den Augen ihres Gebers*; wohin er sich wendet, hat er Erfolg.*", footnotes: ["o. Ein Stein, der beliebt macht; w. Ein Gunststein", "o. ihres Empfängers; w. ihres Besitzers", "℘ Kap. 18,16; 21,14; 1Mo 32,14.21"] },
      { number: 9, text: "Wer Vergehen zudeckt, strebt nach Liebe*; wer aber eine Sache <immer wieder> aufrührt*, entzweit Vertraute*.", footnotes: ["℘ Kap. 10,12; 1Kor 13,5.7; 1Petr 4,8", "o. eine Sache weitererzählt", "℘ Kap. 16,28"] },
      { number: 10, text: "Zurechtweisung dringt bei einem Verständigen tiefer ein als hundert Schläge bei einem Toren.*", footnotes: ["℘ Kap. 19,25"] },
      { number: 11, text: "Nur Aufruhr sucht der Böse; aber ein grausamer Bote wird gegen ihn gesandt.*", footnotes: ["℘ Kap. 24,21.22; Jak 2,13"] },
      { number: 12, text: "Mag einem eine Bärin, die der Jungen beraubt ist*, begegnen, nicht aber ein Tor in seiner Narrheit*!", footnotes: ["℘ 2Sam 17,8", "℘ Kap. 27,3"] },
      { number: 13, text: "Wer Gutes mit Bösem vergilt, von dessen Haus wird das Böse nicht weichen.*", footnotes: ["℘ Ps 109,4-20; Jer 18,20"] },
      { number: 14, text: "<Wie> einer, der Wasser entfesselt, <so> ist der Anfang eines Streites; bevor also der Rechtsstreit losbricht, lass ab!*", footnotes: ["℘ Kap. 20,3; 2Sam 2,17"] },
      { number: 15, text: "Wer den Schuldigen* gerecht spricht und wer den Gerechten für schuldig* erklärt — ein Gräuel für den HERRN sind sie alle beide.*", footnotes: ["o. den Gottlosen", "o. für gottlos", "℘ Kap. 24,24; 2Mo 23,7; 5Mo 25,1; Hes 13,19; Jak 5,6"] },
      { number: 16, text: "Wozu denn Geld in der Hand des Toren? Um Weisheit zu kaufen, da ihm doch der Verstand fehlt?*", footnotes: ["℘ Kap. 14,6"] },
      { number: 17, text: "Ein Freund liebt zu jeder Zeit, und als Bruder für die Not wird er geboren*.*", footnotes: ["o. und ein Bruder wird für die Not geboren", "℘ Kap. 18,24; 1Sam 19,3; 20,17.42"] },
      { number: 18, text: "Ein Mensch ohne Verstand ist, wer Handschlag gibt, wer Bürgschaft leistet gegenüber seinem Nächsten.*", footnotes: ["℘ Kap. 6,1-5"] },
      { number: 19, text: "Wer Zank liebt, liebt Vergehen*; wer seine Tür* hoch macht, sucht Bruch.*", footnotes: ["℘ Jak 3,16", "d. i. wohl der Mund", "℘ Kap. 16,18"] },
      { number: 20, text: "Wer verschlagenen* Herzens ist, findet kein Glück; und wer sich mit seiner Zunge windet, fällt ins Unglück.*", footnotes: ["w. verdrehten", "℘ Kap. 10,14"] },
      { number: 21, text: "Wer einen Toren zeugt, dem <bringt es> Kummer, und keine Freude hat der Vater eines Narren*.*", footnotes: ["o. eines Gottlosen", "℘ Kap. 10,1; 19,13"] },
      { number: 22, text: "Ein fröhliches Herz bringt gute Besserung*, aber ein niedergeschlagener Geist dörrt das Gebein aus*.", footnotes: ["℘ Kap. 15,13.15; Pred 2,2", "℘ Kap. 12,25; 18,14; Ps 32,3.4"] },
      { number: 23, text: "Bestechung aus dem Gewandbausch nimmt der Gottlose an, um die Pfade des Rechts zu beugen.*", footnotes: ["℘ 2Mo 23,8; Jes 5,23; Hes 22,27; Mi 3,9-11"] },
      { number: 24, text: "Der Verständige <hat> die Weisheit vor dem Angesicht, aber die Augen des Toren sind am Ende der Erde." },
      { number: 25, text: "Ein törichter Sohn <bedeutet> für seinen Vater Verdruss und Bitternis für die, die ihn geboren hat." },
      { number: 26, text: "Schon Geldstrafe für den Gerechten ist nicht gut, <aber> Edle zu schlagen, ist gegen das Recht." },
      { number: 27, text: "Wer seine Worte zügelt, besitzt Erkenntnis; und wer kühlen Geist <bewahrt>, ist ein verständiger Mann." },
      { number: 28, text: "Auch ein Narr, wenn er schweigt, kann als weise gelten, wenn er seine Lippen verschließt, als verständig." },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Wer sich absondert, sucht <sein> Begehren*, gegen alle Umsicht* platzt er los.", footnotes: ["LXX: sucht nach einem Vorwand", "o. mit aller Kraft"] },
      { number: 2, text: "Kein Gefallen hat der Tor an Einsicht*, sondern nur an der Entblößung seines Herzens*.", footnotes: ["o. an Verständnis\n℘ Kap. 1,7.22", "℘ Kap. 12,23"] },
      { number: 3, text: "Kommt ein Gottloser*, kommt auch Verachtung und mit der Schandtat die Schmach.*", footnotes: ["Andere üs. mit Textänderung: Gottlosigkeit, o. Frevel", "℘ Kap. 13,5"] },
      { number: 4, text: "Tiefes Wasser sind die Worte aus dem Mund eines Mannes, ein sprudelnder Bach, eine Quelle der Weisheit.*", footnotes: ["℘ Kap. 20,5"] },
      { number: 5, text: "Es ist nicht gut, die Person des Gottlosen* anzusehen*, um den Gerechten* abzuweisen im Gericht.*", footnotes: ["o. des Schuldigen", "w. das Gesicht des Gottlosen zu erheben", "o. den Unschuldigen", "℘ Kap. 17,15; 24,23; 2Mo 23,2.3"] },
      { number: 6, text: "Die Lippen des Toren kommen an mit Streit*, und sein Mund schreit nach Prügel.", footnotes: ["Andere üs. mit LXX und der syr. Üs.: führen zu Streit\n℘ Kap. 16,28"] },
      { number: 7, text: "Der Mund des Toren wird ihm zum Verderben, und seine Lippen sind eine Falle für seine Seele*.*", footnotes: ["o. für ihn selbst", "℘ Kap. 10,8; 14,3; 16,22"] },
      { number: 8, text: "Die Worte des Verleumders sind wie Leckerbissen*, sie gleiten hinab in die Kammern des Leibes.*", footnotes: ["w. wie <Speisen>, die man gierig verschlingt", "℘ Kap. 26,22"] },
      { number: 9, text: "Wer sich auch nur lässig zeigt bei seiner Arbeit, der ist ein Bruder des Verderbers*.*", footnotes: ["w. des Herrn des Verderbens", "℘ Kap. 19,15; 23,21; 24,33.34"] },
      { number: 10, text: "Ein fester Turm ist der Name des HERRN*; zu ihm läuft der Gerechte und ist in Sicherheit*.", footnotes: ["℘ 1Sam 17,45", "℘ Kap. 14,26; Ps 20,2; 61,4; 144,2"] },
      { number: 11, text: "Das Vermögen des Reichen ist seine feste Stadt und wie eine hochragende Mauer* — in seiner Einbildung.", footnotes: ["℘ Kap. 10,15; 28,11; Ps 49,7; Jer 9,22; Lk 12,19"] },
      { number: 12, text: "Vor dem Sturz* will das Herz des Mannes hoch hinaus*, aber der Ehre geht Demut voraus*.", footnotes: ["o. Vor dem Zusammenbruch", "℘ Kap. 16,18", "℘ Kap. 15,33; 29,23; 1Kö 3,7; Lk 14,11; 1Petr 5,5.6"] },
      { number: 13, text: "Wer Antwort gibt, bevor er zuhört, dem ist es Narrheit und Schande." },
      { number: 14, text: "Eines Mannes Geist erträgt seine Krankheit; aber einen niedergeschlagenen Geist, wer richtet den auf*?*", footnotes: ["o. wer trägt den", "℘ Kap. 17,22; 2Mo 6,9"] },
      { number: 15, text: "Das Herz des Verständigen erwirbt Erkenntnis*, und das Ohr der Weisen sucht Erkenntnis.", footnotes: ["℘ Kap. 1,5; 15,14; Lk 2,46"] },
      { number: 16, text: "Das Geschenk eines Menschen schafft ihm weiten Raum, und vor die Großen führt es ihn.*", footnotes: ["℘ Kap. 17,8; 19,6; 1Mo 43,11; 2Kö 5,5"] },
      { number: 17, text: "Im Recht* <scheint>, wer in seiner Streitsache als Erster <auftritt>, <bis> sein Nächster kommt und ihn ausforscht*.", footnotes: ["o. Gerecht", "o. <doch dann> kommt der andere <zu Wort> und durchschaut ihn"] },
      { number: 18, text: "Streitigkeiten beendet das Los*, und zwischen Starken entscheidet es*.", footnotes: ["℘ 1Sam 14,41.42", "o. und Mächtige entzweit es"] },
      { number: 19, text: "Ein getäuschter Bruder <ist unzugänglicher> als eine befestigte Stadt*; und Streitigkeiten sind wie der Riegel einer Burg.", footnotes: ["℘ 1Mo 27,41"] },
      { number: 20, text: "Von der Frucht des Mundes eines Mannes wird sein Inneres satt, am Ertrag seiner Lippen isst er sich satt.*", footnotes: ["℘ Kap. 13,2.25"] },
      { number: 21, text: "Tod und Leben sind in der Gewalt der Zunge, und wer sie liebt, wird ihre Frucht essen.*", footnotes: ["℘ Ps 12,5"] },
      { number: 22, text: "Wer eine Frau gefunden, hat Gutes gefunden und hat Wohlgefallen erlangt von dem HERRN.*", footnotes: ["℘ Kap. 12,4; 19,14; 31,10; Rt 4,10"] },
      { number: 23, text: "Mit Flehen redet der Arme, der Reiche aber antwortet mit Härte.*", footnotes: ["℘ Kap. 22,7"] },
      { number: 24, text: "Manche Gefährten schlagen sich*, aber mancher Freund ist anhänglicher als ein Bruder.*", footnotes: ["T.; Mas. T.: Ein Mann von <vielen> Gefährten wird <an ihnen> zugrunde gehen", "℘ Kap. 17,17; 27,10; 1Sam 18,1.3; 2Sam 1,26; 15,21"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Besser ein Armer, der in seiner Lauterkeit lebt*, als einer, der verschlagene* Lippen hat und der dabei ein Tor ist*.*", footnotes: ["o. in seiner Vollkommenheit geht", "w. verdrehte", "Die syr. Üs. liest mit Kap. 28,6: und ist dabei reich", "℘ Kap. 28,6"] },
      { number: 2, text: "Ohne Erkenntnis ist selbst Eifer nicht gut*; und wer mit den Füßen hastig ist, tritt fehl*.", footnotes: ["o. Ohne Verstand taugt schon das Begehren nichts\n℘ 2Kö 4,39.40", "℘ Kap. 21,5"] },
      { number: 3, text: "Die Narrheit des Menschen führt ihn in die Irre*, aber auf den HERRN ist sein Herz wütend*.", footnotes: ["w. stürzt seinen Weg um", "℘ Hi 15,13"] },
      { number: 4, text: "Reichtum verschafft immer mehr Freunde; aber der Geringe — sein Freund trennt sich <von ihm>.*", footnotes: ["℘ Kap. 14,20"] },
      { number: 5, text: "Ein falscher Zeuge bleibt nicht ungestraft; und wer Lügen vorbringt*, wird nicht entkommen.*", footnotes: ["w. schnaubt; o. aushaucht", "℘ Kap. 6,19; 14,25; 21,28; 2Mo 20,16; 5Mo 19,19"] },
      { number: 6, text: "Viele umschmeicheln den Edlen*, und jeder ist der <beste> Freund des freigebigen Mannes.*", footnotes: ["w. machen das Gesicht des Edlen weich", "℘ Kap. 18,16; Lk 16,9"] },
      { number: 7, text: "Alle Brüder des Armen hassen ihn; wie viel mehr halten sich seine Freunde von ihm fern!* Er jagt Worten nach, die nichts sind.*", footnotes: ["℘ Kap. 10,15; 27,10; Ps 38,12", "so mit der Schreibform des Mas. T.; mit der Leseform: Er jagt Worten nach; die gehören ihm."] },
      { number: 8, text: "Wer Klugheit erwirbt, liebt seine Seele*; wer Einsicht bewahrt, wird Glück erlangen.", footnotes: ["o. sein Leben\n℘ Kap. 3,21.22"] },
      { number: 9, text: "Ein falscher Zeuge bleibt nicht ungestraft, und wer Lügen vorbringt*, geht zugrunde.", footnotes: ["w. schnaubt; o. aushaucht"] },
      { number: 10, text: "Wohlleben steht einem Toren nicht an*, wie viel weniger einem Sklaven, über Oberste zu herrschen*!", footnotes: ["℘ Kap. 26,1", "℘ Kap. 30,21.22; Pred 10,5-7"] },
      { number: 11, text: "Die Einsicht eines Menschen macht ihn langmütig*, und sein Ruhm ist es, an der Übertretung vorüberzugehen*.", footnotes: ["℘ Kap. 14,29", "℘ Kap. 20,22"] },
      { number: 12, text: "Wie das Knurren eines Junglöwen ist die Wut des Königs*, aber wie Tau auf dem Gras ist sein Wohlgefallen*.", footnotes: ["℘ Est 1,12", "℘ Kap. 16,14.15"] },
      { number: 13, text: "Verderben für seinen Vater ist ein törichter Sohn*, und ein tropfendes Dach, das <einen> vertreibt*, sind die Zänkereien einer Frau*.", footnotes: ["℘ Kap. 17,21", "o. eine ständig tropfende Dachtraufe", "℘ Kap. 21,9.19"] },
      { number: 14, text: "Haus und Habe sind ein Erbteil der Väter*, von dem HERRN aber ist eine einsichtsvolle Frau*.", footnotes: ["℘ 2Kor 12,14", "℘ Kap. 18,22; 31,26; 1Mo 24,44; 1Sam 25,3"] },
      { number: 15, text: "Faulheit versenkt in tiefen Schlaf, und eine lässige Seele muss hungern.*", footnotes: ["℘ Kap. 6,9-11; 18,9; 22,13"] },
      { number: 16, text: "Wer das Gebot bewahrt, bewahrt sein Leben*; wer seine Wege* verachtet, muss sterben*.", footnotes: ["o. seine Seele\n℘ Kap. 16,17; Lk 10,28", "Andere üs. mit Textänderung: das Wort", "℘ Kap. 21,16; Hi 5,2"] },
      { number: 17, text: "Wer über den Geringen sich erbarmt, leiht dem HERRN*, und seine Wohltat wird er ihm vergelten.*", footnotes: ["o. Der HERR leiht dem, der über den Geringen sich erbarmt", "℘ Kap. 28,27; 5Mo 15,11; Mt 10,42; 25,40; Lk 6,38; Hebr 6,10"] },
      { number: 18, text: "Züchtige deinen Sohn, solange <noch> Hoffnung da ist*; aber lass dich nicht dazu hinreißen*, ihn zu töten*!", footnotes: ["o. denn dann ist <noch> Hoffnung da\n℘ Kap. 13,24; 22,15; 23,13; 29,17", "w. erhebe nicht deinen Eifer o. deine Seele", "℘ 5Mo 21,18-21; Eph 6,4"] },
      { number: 19, text: "Wer maßlos zornig ist*, muss <seine> Geldbuße zahlen; denn greifst du auch ein, so machst du es nur noch schlimmer*.*", footnotes: ["so mit der Leseform des Mas. T.; mit der Schreibform: Der, dessen Los der Zorn ist", "o. wenn du retten willst, musst du es <doch> immer wiederholen", "℘ Kap. 25,28; Hi 5,2"] },
      { number: 20, text: "Höre auf <guten> Rat und nimm Zucht an, damit du für die Zukunft* weise wirst!*", footnotes: ["w. an deinem Ende", "℘ Kap. 1,2; 13,10; 15,32; Jer 6,8"] },
      { number: 21, text: "Viele Gedanken* sind im Herzen eines Mannes; aber der Ratschluss des HERRN, er kommt zustande*.*", footnotes: ["o. Pläne", "o. hat Bestand", "℘ Kap. 16,1; 21,30; 2Sam 17,14; Jes 14,24; Hes 20,32"] },
      { number: 22, text: "Gewinn für den Menschen* ist seine Mildtätigkeit*, und besser ein armer als ein verlogener Mann.", footnotes: ["so mit LXX; Mas. T.: Das Begehrenswerte <am> Menschen, o. Etwas Begehrenswertes für den Menschen", "℘ Eph 4,32"] },
      { number: 23, text: "Die Furcht des HERRN <gereicht> zum Leben*; und gesättigt verbringt man die Nacht, wird nicht heimgesucht vom Bösen*.", footnotes: ["℘ Kap. 14,27; 22,4; Ps 34,10-15", "℘ Kap. 3,24"] },
      { number: 24, text: "Hat der Faule seine Hand in die Schüssel gesteckt, nicht einmal zu seinem Mund bringt er sie zurück.*", footnotes: ["℘ Kap. 21,25; 26,15"] },
      { number: 25, text: "Schlägst du den Spötter, so wird der Einfältige* klug; und weist man den Verständigen zurecht, so wird er auf Erkenntnis achtgeben.*", footnotes: ["o. Unerfahrene; o. Unverständige", "℘ Kap. 1,5; 17,10"] },
      { number: 26, text: "Wer den Vater misshandelt*, die Mutter verjagt*, ist ein Sohn, der Schande und Schmach bringt.*", footnotes: ["o. zugrunde richtet", "o. verletzt", "℘ Kap. 28,24"] },
      { number: 27, text: "Hör auf, mein Sohn, Zucht anzuhören, um <dann> abzuirren von den Worten der Erkenntnis!*", footnotes: ["℘ 2Chr 10,10; 2Tim 2,16.17"] },
      { number: 28, text: "Ein nichtswürdiger Zeuge verspottet das Recht*, und der Mund der Gottlosen verbreitet Unheil*.", footnotes: ["℘ 1Kö 21,13", "℘ Kap. 16,27"] },
      { number: 29, text: "Für die Spötter stehen Gerichte* bereit*, und Prügel für den Rücken der Toren*.", footnotes: ["LXX: Peitschen", "℘ Kap. 1,22.26; 2Kö 2,24; Jes 28,22", "℘ Kap. 10,13"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Ein Spötter ist der Wein, ein Lärmer der Rauschtrank; und jeder, der davon taumelt, ist unweise.*", footnotes: ["℘ Kap. 23,20.33.34; 1Mo 9,21; Jes 28,7; Hos 4,11"] },
      { number: 2, text: "Wie das Knurren eines Junglöwen ist der Schrecken* des Königs*, wer sich seinen Zorn zuzieht, verwirkt sein Leben*.", footnotes: ["Andere üs. mit Textänderung: der Grimm", "℘ Kap. 16,14", "o. sündigt gegen sich selbst o. gegen seine Seele\n℘ 1Kö 2,23.24"] },
      { number: 3, text: "Ehre ist es dem Mann, vom Streit abzulassen*, jeder Narr aber fängt <Streit> an*.", footnotes: ["o. dem Streit fernzubleiben\n℘ Kap. 17,14", "w. bricht los"] },
      { number: 4, text: "Im Winter pflügt der Faule nicht; sucht er zur Erntezeit, dann ist nichts da.*", footnotes: ["℘ Kap. 13,4; 21,25; Pred 11,4"] },
      { number: 5, text: "Tiefes Wasser ist der Ratschluss im Herzen des Mannes*, aber ein verständiger Mann schöpft ihn herauf*.", footnotes: ["℘ Kap. 18,4", "℘ 1Kor 2,15"] },
      { number: 6, text: "Die meisten Menschen rufen ihre eigene Frömmigkeit aus*; aber einen zuverlässigen Mann, wer findet <ihn>*?", footnotes: ["o. preisen alle ihre Gnade an\n℘ Kap. 27,2; Mt 6,2", "℘ Ps 12,2; Jer 5,1; Mi 7,1.2"] },
      { number: 7, text: "Wer in seiner Lauterkeit als Gerechter lebt* — glücklich seine Kinder nach ihm*!", footnotes: ["w. wandelt\n℘ Hi 1,1.8; Ps 15,2-5", "℘ Kap. 14,26"] },
      { number: 8, text: "Ein König, der auf dem Richterstuhl sitzt, sondert mit seinen Augen alles Böse aus." },
      { number: 9, text: "Wer darf sagen: Ich habe mein Herz rein gehalten, ich bin rein von meiner Sünde?*", footnotes: ["℘ 1Kö 8,46"] },
      { number: 10, text: "Zweierlei Gewichtsteine, zweierlei Efa, sie sind alle beide ein Gräuel für den HERRN.*", footnotes: ["℘ Kap. 11,1; 5Mo 25,13-16; Mi 6,10-12"] },
      { number: 11, text: "Schon in seinen Taten gibt sich ein Junge zu erkennen, ob sein Handeln lauter und ob es redlich ist.*", footnotes: ["℘ 2Chr 34,3; Mt 7,16"] },
      { number: 12, text: "Das hörende Ohr und das sehende Auge, der HERR hat sie alle beide gemacht.*", footnotes: ["℘ 2Mo 4,11"] },
      { number: 13, text: "Liebe nicht den Schlaf, damit du nicht verarmst; halte deine Augen offen, dann kannst du dich an Brot satt essen!*", footnotes: ["℘ Kap. 6,11; 12,11"] },
      { number: 14, text: "Schlecht, schlecht!, sagt der Käufer; und wenn er weggeht, dann rühmt er sich." },
      { number: 15, text: "Es gibt Gold und viele Korallen; aber ein kostbarer Schmuck sind Lippen der Erkenntnis.*", footnotes: ["℘ Kap. 8,10.11.19; 10,20; Hi 28,18"] },
      { number: 16, text: "Nimm ihm das Gewand, denn er hat für einen Fremden gebürgt; und wegen der Ausländer* pfände ihn!*", footnotes: ["so mit der Schreibform des Mas. T. und Vulg.; mit der Leseform: wegen der Ausländerin", "℘ Kap. 6,1-5"] },
      { number: 17, text: "Süß <schmeckt> dem Mann das Brot der Lüge*, aber hinterher ist sein Mund voller Kies*.", footnotes: ["o. des Betrugs\n℘ Kap. 9,17", "℘ Hi 20,12-14; Kla 3,16"] },
      { number: 18, text: "Pläne kommen durch Beratung zustande*, und mit weiser Überlegung* führe Krieg*!", footnotes: ["℘ Kap. 11,14; 15,22; Ri 19,30", "o. mit kluger Lenkung", "℘ Kap. 24,6; 2Kö 18,20; Lk 14,31"] },
      { number: 19, text: "Wer Anvertrautes preisgibt*, geht als Verleumder umher*; und mit dem, der seine Lippen aufsperrt, lass dich nicht ein!", footnotes: ["w. Wer geheime Beratung aufdeckt", "℘ Kap. 11,13"] },
      { number: 20, text: "Wer seinem Vater oder seiner Mutter flucht, dessen Leuchte wird erlöschen in tiefster Finsternis*!*", footnotes: ["w. im Augapfel der Finsternis", "℘ Kap. 13,9; 30,11.17; 2Mo 21,17; Mt 15,4"] },
      { number: 21, text: "Ein Erbe, schnell erworben* im Anfang, wird an seinem Ende nicht gesegnet sein.*", footnotes: ["so mit der Leseform des Mas. T.; mit der Schreibform: Ein Erbe, verachtet", "℘ Mt 21,38.41"] },
      { number: 22, text: "Sage nicht: Ich will Böses vergelten*! Harre auf den HERRN, so wird er dich retten*!", footnotes: ["℘ Kap. 19,11; 24,29; 3Mo 19,18; 1Sam 25,13; 1Thes 5,15", "o. dir helfen\n℘ Ps 37,40"] },
      { number: 23, text: "Ein Gräuel sind für den HERRN zweierlei Gewichtsteine, und trügerische Waagschalen sind nicht gut.*", footnotes: ["℘ Am 8,5"] },
      { number: 24, text: "Vom HERRN sind die Schritte des Mannes <bestimmt>*; und der Mensch, wie sollte er seinen Weg verstehen?", footnotes: ["℘ Kap. 16,1.9"] },
      { number: 25, text: "Eine Falle für den Menschen ist es, vorschnell zu sagen: Geheiligt! — und <erst> nach den Gelübden zu überlegen.*", footnotes: ["℘ 5Mo 23,22-24; Pred 5,2-4"] },
      { number: 26, text: "Ein weiser König sondert die Gottlosen aus und lässt das Rad über sie gehen*.*", footnotes: ["Andere üs. mit Textänderung: und lässt ihre Schuld über sie kommen", "℘ Ps 101,8"] },
      { number: 27, text: "Der Geist des Menschen ist eine Leuchte des HERRN*, durchforscht alle Kammern des Leibes.*", footnotes: ["Andere üs. mit Textänderung: Der HERR bewacht den Atem des Menschen", "℘ Hi 32,8; 1Kor 2,11"] },
      { number: 28, text: "Güte* und Treue behüten den König, und durch Güte* stützt er seinen Thron.*", footnotes: ["o. Gnade; d. h. der Erweis der königlichen Gnade", "o. Gnade; d. h. der Erweis der königlichen Gnade", "℘ Kap. 3,3; 29,14; Dan 4,24"] },
      { number: 29, text: "Der Schmuck der jungen Männer ist ihre Kraft*, graues Haar aber die Zierde der Alten*.", footnotes: ["℘ 1Jo 2,14", "℘ Kap. 16,31"] },
      { number: 30, text: "Blutige Striemen* reinigen den Bösen*, und Schläge die Kammern des Leibes.*", footnotes: ["w. Striemen der Wunde", "Andere üs. mit Änderung der Vokale: reinigen den Willen", "℘ Hebr 12,10-11"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "<Wie> Wasserbäche ist das Herz eines Königs in der Hand des HERRN; wohin immer er will, neigt er es.*", footnotes: ["℘ Kap. 16,9; 2Mo 7,3; 2Kö 19,33; Esr 1,1; 7,27; Neh 2,8; Est 2,17"] },
      { number: 2, text: "Jeder Weg eines Mannes ist gerade in seinen Augen, aber der die Herzen prüft, ist der HERR.*", footnotes: ["℘ Kap. 16,2; 17,3; Hi 31,6; Dan 5,27; Lk 16,15"] },
      { number: 3, text: "Gerechtigkeit und Recht üben ist dem HERRN lieber als Schlachtopfer.*", footnotes: ["℘ 1Sam 15,22; Ps 40,7.9; Jes 1,17; Hos 6,6; Mi 6,6-8; Sach 7,9"] },
      { number: 4, text: "Stolz der Augen und Hochmut* des Herzens — die Leuchte* der Gottlosen ist Sünde.*", footnotes: ["w. Aufgeblasenheit", "o. der Neubruch", "℘ Kap. 6,16.17; 30,13; Hi 18,5-7; Ps 101,5; 131,1; Jes 3,16; 10,12.13; 1Jo 2,16"] },
      { number: 5, text: "Die Pläne des Fleißigen <führen> nur zum Gewinn*; aber jeder, der hastig ist, erreicht nur Mangel*.", footnotes: ["℘ Kap. 10,4", "o. Verlust\n℘ Kap. 19,2; 29,20"] },
      { number: 6, text: "Erwerb von Schätzen durch eine lügnerische Zunge ist <wie> verwehter Dunst, eine Falle des Todes*.*", footnotes: ["so mit einigen hebr. Handschr. und Vulg.; Mas. T.: solche, die den Tod suchen", "℘ Kap. 13,11"] },
      { number: 7, text: "Die Gewalttat der Gottlosen reißt sie mit weg, denn sie weigern sich, das Rechte zu tun.*", footnotes: ["℘ Kap. 22,22.23"] },
      { number: 8, text: "Gewunden ist der Weg des schuldbeladenen Mannes*; der Lautere aber, sein Tun ist gerade*.", footnotes: ["℘ Jes 59,8", "o. aufrichtig; o. redlich\n℘ Jes 26,7"] },
      { number: 9, text: "Besser auf dem Dach in einer Ecke wohnen als eine zänkische Frau und ein gemeinsames Haus.*", footnotes: ["℘ V. 19; Kap. 19,13; 25,24"] },
      { number: 10, text: "Die Seele des Gottlosen giert nach Bösem*, keine Gnade findet bei ihm* sein Nächster.", footnotes: ["℘ Kap. 12,12; Ps 52,3-5", "w. findet in seinen Augen"] },
      { number: 11, text: "Wenn man dem Spötter Geldbuße auferlegt, dann wird der Einfältige* weise; und wenn man den Weisen belehrt, nimmt er Erkenntnis an.*", footnotes: ["o. Unerfahrene; o. Unverständige", "℘ Kap. 1,5"] },
      { number: 12, text: "Ein Gerechter hat acht auf das Haus des Gottlosen, er stürzt die Gottlosen ins Unglück." },
      { number: 13, text: "Wer sein Ohr verstopft vor dem Hilfeschrei des Geringen*, auch er wird <einst> rufen und keine Antwort erhalten.*", footnotes: ["o. des Hilflosen; o. des Machtlosen", "℘ Jak 2,13"] },
      { number: 14, text: "Eine Gabe im Verborgenen wendet Zorn ab, und ein Geschenk im Gewandbausch heftigen Grimm.*", footnotes: ["℘ Kap. 17,8"] },
      { number: 15, text: "Freude ist es für den Gerechten, wenn Recht geschieht*; Schrecken aber für die Übeltäter*.", footnotes: ["℘ Ps 119,16", "℘ Kap. 10,29"] },
      { number: 16, text: "Ein Mensch, der von dem Weg der Einsicht abirrt, wird ruhen in der Versammlung der Schatten.*", footnotes: ["℘ Kap. 5,23; 19,16; Ps 125,5"] },
      { number: 17, text: "Dem Mangel verfällt*, wer Festfreude liebt; wer Wein und Öl liebt, wird nicht reich.*", footnotes: ["w. Ein Mann des Mangels wird", "℘ Kap. 23,20.21"] },
      { number: 18, text: "Lösegeld für den Gerechten ist der Gottlose, und an die Stelle der Aufrichtigen* <tritt> der Treulose.*", footnotes: ["o. der Geraden", "℘ Kap. 11,8"] },
      { number: 19, text: "Besser ist es, im Land der Wüste zu wohnen, als eine zänkische Frau und Verdruss.*", footnotes: ["℘ V. 9; Kap. 27,15; 30,23"] },
      { number: 20, text: "Ein begehrenswerter Schatz und Öl ist an der Wohnstätte* des Weisen*, ein törichter Mensch aber verschlingt es*.", footnotes: ["LXX: Ein begehrenswerter Schatz ist im Mund", "℘ Kap. 15,6; Ps 112,3", "o. vergeudet es\n℘ Lk 15,13.14"] },
      { number: 21, text: "Wer der Gerechtigkeit und Gnade nachjagt, findet Leben*, Gerechtigkeit und Ehre*.", footnotes: ["℘ Kap. 11,19; Mt 5,6", "℘ Kap. 10,16.27; 22,4; Röm 2,7.10"] },
      { number: 22, text: "Eine Stadt von Helden ersteigt der Weise und stürzt nieder das Bollwerk, auf das sie sich verlässt.*", footnotes: ["℘ Kap. 24,5.6; Pred 7,19"] },
      { number: 23, text: "Wer seinen Mund und seine Zunge bewahrt, bewahrt vor Nöten seine Seele*.*", footnotes: ["o. sein Leben", "℘ Kap. 13,3; 16,17; Jak 3,2"] },
      { number: 24, text: "Der anmaßend Übermütige — Spötter ist sein Name — handelt mit maßlosem Übermut." },
      { number: 25, text: "Die Begierde des Faulen bringt ihm den Tod*, denn seine Hände weigern sich zu arbeiten*.", footnotes: ["℘ Kap. 19,24", "℘ Kap. 20,4"] },
      { number: 26, text: "Den ganzen Tag giert er voller Begierde*, aber der Gerechte gibt und hält nicht zurück.*", footnotes: ["LXX: giert der Gottlose", "℘ Ps 37,26; 112,9; Mt 5,42"] },
      { number: 27, text: "Das Schlachtopfer der Gottlosen ist ein Gräuel <für den HERRN>*; wie viel mehr, wenn man es in schändlicher Absicht* bringt!", footnotes: ["℘ Kap. 7,14; 15,8; 4Mo 16,15; Jes 1,11.13; Jer 6,20; Am 5,22", "w. als Schandtat"] },
      { number: 28, text: "Ein Lügenzeuge wird zugrunde gehen*; ein Mann aber, der zuhört, redet für lange Dauer.", footnotes: ["℘ Kap. 19,5; Mt 26,59-61; Offb 21,8"] },
      { number: 29, text: "Mit frechem Gesicht tritt der gottlose Mann auf*; der Aufrichtige aber, er achtet auf seinen Weg*.", footnotes: ["℘ Jer 3,3", "so mit der Leseform des Mas. T.; mit der Schreibform: er macht seine Wege fest, d. h. gibt seinen Wegen eine feste Richtung\n℘ Kap. 4,25-27"] },
      { number: 30, text: "Es gibt keine Weisheit und keine Einsicht und keinen Rat gegenüber dem HERRN.*", footnotes: ["℘ Kap. 19,21; 1Kö 14,6; 2Kö 6,12; Hi 41,2"] },
      { number: 31, text: "Das Pferd wird gerüstet für den Tag der Schlacht, aber die Rettung* ist <Sache> des HERRN.*", footnotes: ["o. der Sieg", "℘ Ps 20,8"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Ein <guter> Name ist vorzüglicher* als großer Reichtum*, besser als Silber und Gold ist Anmut*.", footnotes: ["o. begehrenswerter", "℘ Pred 7,1", "o. Gunst; o. Beliebtheit"] },
      { number: 2, text: "Reiche und Arme begegnen sich*; der sie alle gemacht hat, ist der HERR*.", footnotes: ["℘ Jak 2,2", "℘ Kap. 14,31; 29,13; 1Sam 2,7; Hi 31,15"] },
      { number: 3, text: "Der Kluge sieht das Unglück und verbirgt sich; die Einfältigen* aber gehen weiter und müssen es büßen.*", footnotes: ["o. Unerfahrenen; o. Unverständigen", "℘ Kap. 14,16; 27,12; 2Mo 9,20.21"] },
      { number: 4, text: "Die Folge der Demut <und> der Furcht des HERRN ist* Reichtum und Ehre und Leben.*", footnotes: ["o. Die Folge der Demut ist die Furcht des HERRN, ist", "℘ Kap. 19,23; 21,21; Ps 34,10"] },
      { number: 5, text: "Dornen <und> Schlingen sind auf dem Weg des Verschlagenen*; wer sein Leben* bewahren will, hält sich fern von ihnen*.", footnotes: ["℘ Kap. 4,19; 15,19", "o. seine Seele", "℘ Kap. 16,17"] },
      { number: 6, text: "Erziehe den Knaben seinem Weg gemäß; er wird nicht davon weichen, auch wenn er älter wird.*", footnotes: ["℘ Eph 6,4"] },
      { number: 7, text: "Der Reiche herrscht über die Armen*, und Sklave ist der Schuldner <seinem> Gläubiger*.", footnotes: ["℘ Kap. 18,23; Am 4,1; Jak 2,6", "℘ 2Kö 4,1; Neh 5,4.5; Mt 18,25"] },
      { number: 8, text: "Wer Unrecht sät, wird Unheil ernten*, und der Stock seines Wütens wird ein Ende nehmen*.", footnotes: ["℘ Hi 4,8; Hos 8,7", "LXX: und der Stock macht seinem Wüten ein Ende\n℘ Jes 10,25"] },
      { number: 9, text: "Wer gütigen Auges ist, der wird gesegnet werden*; denn er gibt von seinem Brot dem Geringen*.", footnotes: ["℘ Kap. 14,21; 28,24.27", "℘ Kap. 11,17.27; 2Kor 9,6"] },
      { number: 10, text: "Treibe den Spötter fort, so zieht der Zank mit hinaus, und Streiten und Schimpfen hören auf.*", footnotes: ["℘ Kap. 26,20"] },
      { number: 11, text: "Wer Reinheit des Herzens liebt*, wessen Lippen wohlgefällig <reden>, dessen Freund ist der König.*", footnotes: ["LXX: Der HERR liebt den, der reinen Herzens ist", "℘ Kap. 16,13; 1Kö 4,5"] },
      { number: 12, text: "Die Augen des HERRN behüten die Erkenntnis, und er bringt die Worte des Treulosen zu Fall.*", footnotes: ["℘ 2Kö 6,9; Neh 4,9; Hi 5,12"] },
      { number: 13, text: "Der Faule sagt: Ein Löwe ist draußen; mitten auf den Plätzen könnte ich getötet werden!*", footnotes: ["℘ Kap. 19,15; 26,13"] },
      { number: 14, text: "Eine tiefe Grube ist der Mund von fremden Frauen*; wem der HERR zürnt, der fällt hinein*.", footnotes: ["d. h. von Nichtisraelitinnen oder von Frauen mit fremder Religion\n℘ Kap. 5,3.4; 23,27", "℘ Pred 7,26"] },
      { number: 15, text: "Haftet Narrheit am Herzen des Knaben, die Rute der Zucht entfernt sie davon.*", footnotes: ["℘ Kap. 19,18; 23,13.14; 29,15"] },
      { number: 16, text: "Wer den Geringen unterdrückt, verschafft ihm <nur> mehr*; wer dem Reichen gibt, <das gereicht> nur zum Mangel.", footnotes: ["w. <dient> ihm zur Mehrung"] },
      { number: 17, text: "Neige dein Ohr und höre die Worte von Weisen und richte dein Herz auf meine Erkenntnis!*", footnotes: ["℘ Kap. 5,1.2; 23,12"] },
      { number: 18, text: "Denn lieblich ist es, wenn du sie in deinem Innern bewahrst. Sie mögen sich alle miteinander auf deinen Lippen bereithalten*!*", footnotes: ["Andere üs. mit Textänderung: Sie mögen fest wie ein Zeltpflock auf deinen Lippen bleiben", "℘ Kap. 4,20.21"] },
      { number: 19, text: "Damit dein Vertrauen auf dem HERRN steht, belehre ich dich heute, gerade dich*.*", footnotes: ["Andere üs. mit LXX: belehre ich dich heute über deinen Weg; andere: über seinen Weg; d. i. Gottes Weg", "℘ Kap. 3,5"] },
      { number: 20, text: "Habe ich dir nicht dreißig <Sprüche> aufgeschrieben* mit Ratschlägen und Erkenntnis,", footnotes: ["T.; mit der Schreibform des Mas. T.: Habe ich dir nicht vorgestern geschrieben; mit der Leseform: Habe ich dir nicht Kernsprüche aufgeschrieben. — Doch die Üs. ist unsicher."] },
      { number: 21, text: "um dich zu lehren die Wahrheit zuverlässiger Worte*, so dass du denen, die dich gesandt haben, zuverlässige Antwort geben kannst?", footnotes: ["℘ Kap. 1,1-6"] },
      { number: 22, text: "Beraube nicht den Geringen, weil er gering ist, und zertritt nicht den Elenden im Tor!*", footnotes: ["℘ 2Mo 23,6; 3Mo 19,13; Hi 31,16; Sach 7,10"] },
      { number: 23, text: "Denn der HERR führt ihren Rechtsstreit* und raubt ihren Räubern das Leben*.", footnotes: ["℘ Kap. 23,11; 1Sam 25,39; Ps 12,6; 103,6; 140,13; Jer 50,34", "o. die Seele\n℘ Kap. 21,7; 2Mo 22,22.23; Jes 33,1; Jer 30,16; Hab 2,8"] },
      { number: 24, text: "Lass dich nicht ein *mit einem Zornigen, und mit einem Mann, der sich schnell erregt*, verkehre nicht*,", footnotes: ["w. mit dem Herrn des Zorns, und mit dem Mann der Erregungen", "w. mit dem Herrn des Zorns, und mit dem Mann der Erregungen", "℘ Kap. 15,18"] },
      { number: 25, text: "damit du dich nicht an seine Pfade gewöhnst und deinem Leben* eine Falle stellst*!", footnotes: ["o. deiner Seele", "℘ Kap. 4,14; 13,20"] },
      { number: 26, text: "Sei nicht unter denen, die Handschlag geben, unter denen, die für ein Darlehen bürgen.*", footnotes: ["℘ Kap. 6,1-5"] },
      { number: 27, text: "Wenn du <dann> nichts hast, um zu bezahlen, warum soll man dein Bett unter dir wegnehmen?" },
      { number: 28, text: "Verrücke nicht die uralte Grenze*, die deine Väter gemacht haben*!", footnotes: ["℘ Kap. 23,10", "℘ 5Mo 19,14"] },
      { number: 29, text: "Siehst du einen Mann, der gewandt ist in seinem Geschäft — vor Könige wird er hintreten*, er wird nicht vor Niedrige hintreten.*", footnotes: ["d. h. um ihnen zu dienen", "℘ 1Mo 41,38-44; 1Sam 16,21; 1Chr 4,23; Dan 1,19"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Wenn du dich hinsetzt, um mit einem Herrscher zu speisen, so achte ja auf das, was* du vor dir hast!", footnotes: ["o. beachte wohl, wen"] },
      { number: 2, text: "Und setze ein Messer an deine Kehle, wenn du heißhungrig bist!" },
      { number: 3, text: "Sei nicht begierig auf seine Leckerbissen, denn das ist eine trügerische Speise!" },
      { number: 4, text: "Mühe dich nicht ab, es zu Reichtum zu bringen*, da verzichte auf deine Klugheit*!", footnotes: ["℘ 1Tim 6,9", "o. Einsicht. — Andere üs.: Mühe dich nicht ab, reich zu werden, <sondern> sei erfolgreich mit deiner Klugheit\n℘ Jer 9,22.23"] },
      { number: 5, text: "Wenn du deine Augen darauf* richtest*, ist er nicht <mehr> da. Denn plötzlich macht er sich Flügel wie ein Adler und fliegt zum Himmel.*", footnotes: ["d. h. auf den Reichtum", "w. fliegen lässt", "℘ Kap. 27,24; Hi 27,19; Mt 6,19; 1Tim 6,17"] },
      { number: 6, text: "Iss nicht das Brot des Missgünstigen* und sei nicht begierig auf seine Leckerbissen!", footnotes: ["o. des Neidischen; o. des Geizigen; w. das Brot der Bosheit des Auges"] },
      { number: 7, text: "Denn wie ein Haar in seiner Kehle, so ist es*. Iss und trink! sagt er zu dir, aber sein Herz ist nicht mit dir.*", footnotes: ["LXX: ein Haar; andere üs. mit Textänderung: wie Sturm in der Kehle, so ist es; Mas. T. viell.: Denn wie einer, der in seiner Seele berechnet, so ist er, d. h. der Missgünstige", "℘ Kap. 26,23-25"] },
      { number: 8, text: "Deinen Bissen, den du gegessen hast, den musst du ausspeien, und vergeudet hast du deine freundlichen Worte.*", footnotes: ["℘ Jer 12,6"] },
      { number: 9, text: "Zu den Ohren eines Toren rede nicht, denn er wird deine klugen Worte verachten!*", footnotes: ["℘ Kap. 9,8"] },
      { number: 10, text: "Verrücke nicht die uralte Grenze*, und in die Felder der Waisen dringe nicht ein*!", footnotes: ["℘ Kap. 22,28", "℘ Jer 7,6"] },
      { number: 11, text: "Denn ihr Erlöser ist stark; er selbst wird ihren Rechtsstreit gegen dich führen.*", footnotes: ["℘ Kap. 22,23; Ps 68,6; Jer 50,34"] },
      { number: 12, text: "Bring her zur Zucht dein Herz, und deine Ohren zu den Worten der Erkenntnis!*", footnotes: ["℘ Kap. 22,17.18"] },
      { number: 13, text: "Entziehe dem Knaben die Züchtigung nicht!* Wenn du ihn mit der Rute schlägst, wird er nicht sterben.", footnotes: ["℘ Kap. 19,18"] },
      { number: 14, text: "Du schlägst ihn mit der Rute, aber rettest sein Leben* vom Scheol.*", footnotes: ["o. seine Seele", "℘ Kap. 22,15; 1Kor 11,32"] },
      { number: 15, text: "Mein Sohn, wenn dein Herz weise ist, freut sich auch mein Herz*;", footnotes: ["℘ V. 24; Kap. 29,3"] },
      { number: 16, text: "und meine Nieren jubeln, wenn deine Lippen Aufrichtiges reden*.", footnotes: ["℘ 3Jo 4"] },
      { number: 17, text: "Dein Herz eifere nicht gegen die Sünder*, sondern um die Furcht des HERRN jeden Tag*!", footnotes: ["℘ Kap. 3,31; 24,19; Ps 37,1", "℘ Kap. 24,21; Pred 5,6"] },
      { number: 18, text: "Denn wahrlich, es gibt <noch> ein Ende*, und dann wird deine Hoffnung nicht zerstört.*", footnotes: ["o. eine Zukunft. — Andere üs. in Anlehnung an LXX: Denn wenn du sie bewahrst, gibt es Zukunft", "℘ Kap. 24,14; Röm 5,5"] },
      { number: 19, text: "Höre du, mein Sohn, und werde weise und leite dein Herz den <geraden> Weg!*", footnotes: ["℘ Kap. 4,26"] },
      { number: 20, text: "Sei nicht unter Weinsäufern*, <noch> unter denen, die Fleisch verprassen*!", footnotes: ["℘ Kap. 20,1; Röm 13,13", "℘ Kap. 28,7; 5Mo 21,20"] },
      { number: 21, text: "Denn ein Säufer und Schlemmer verarmt*, und Schläfrigkeit kleidet in Lumpen*.", footnotes: ["℘ Kap. 21,17; Lk 15,14", "℘ Kap. 18,9; Pred 10,18"] },
      { number: 22, text: "Höre auf deinen Vater, der dich gezeugt hat, und verachte deine Mutter nicht, wenn sie alt geworden ist!*", footnotes: ["℘ Kap. 1,8; 15,20; 30,11; Mt 15,4"] },
      { number: 23, text: "Kaufe Wahrheit und verkaufe sie nicht, <dazu> Weisheit und Zucht und Verstand*!*", footnotes: ["o. Einsicht; V. 23 fehlt in LXX", "℘ Kap. 4,5-7"] },
      { number: 24, text: "Triumphierend jubelt der Vater eines Gerechten, <und> wer einen Weisen gezeugt hat, der kann sich über ihn freuen.*", footnotes: ["℘ V. 15.16; Kap. 10,1; 27,11"] },
      { number: 25, text: "Es freue sich dein Vater und deine Mutter, und es juble, die dich geboren hat!*", footnotes: ["℘ V. 15.16; Kap. 10,1; 27,11"] },
      { number: 26, text: "Gib mir, mein Sohn, dein Herz, und deine Augen lass an meinen Wegen Gefallen haben*!", footnotes: ["so mit der Schreibform des Mas. T.; mit der Leseform: und lass deine Augen meine Wege bewahren"] },
      { number: 27, text: "Denn eine tiefe Grube ist die Hure*, und ein enger Brunnen die fremde <Frau>*;", footnotes: ["℘ Kap. 22,14", "o. die Ausländerin"] },
      { number: 28, text: "ja, sie lauert wie ein Räuber*, und sie vermehrt die Treulosen* unter den Menschen*.", footnotes: ["℘ Kap. 7,10.12.26; Pred 7,26", "Andere üs. mit Textänderung: die Betrogenen", "℘ Kap. 7,26; 1Mo 39,10"] },
      { number: 29, text: "Wer hat Ach, wer hat Weh, wer Zänkereien, wer Klage, wer Wunden ohne Ursache, wer trübe* Augen?", footnotes: ["o. funkelnde; die Bedeutung des Wortes ist unsicher"] },
      { number: 30, text: "Die spät beim Wein noch sitzen, die einkehren, um den Mischkrug zu erforschen*.", footnotes: ["Andere üs.: um den Mischtrank zu kosten"] },
      { number: 31, text: "Sieh den Wein nicht an, wenn er so rötlich schimmert, wenn er im Becher funkelt* <und> leicht hinuntergleitet.*", footnotes: ["w. im Becher sein Auge gibt", "℘ Eph 5,18"] },
      { number: 32, text: "Zuletzt beißt er wie eine Schlange und speit <Gift> wie eine Otter." },
      { number: 33, text: "Deine Augen sehen Seltsames, und dein Herz redet Verworrenes*,", footnotes: ["℘ Kap. 20,1; Eph 5,18"] },
      { number: 34, text: "und du bist wie einer, der im Herzen des Meeres liegt, und wie einer, der da liegt im Ausguck am Mast*.", footnotes: ["o. oben auf der Takelage. — LXX: wie ein Matrose im gewaltigen Sturm\n℘ Kap. 31,4; 1Sam 25,36; 1Kö 16,9"] },
      { number: 35, text: "»Man hat mich geschlagen, es schmerzte mich nicht; man hat mich geprügelt, ich merkte es nicht. Wann werde ich aufwachen? Ich will ihn* noch einmal aufsuchen.«*", footnotes: ["d. h. den Wein", "℘ Jes 56,12"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Sei nicht neidisch auf böse Menschen* und nicht begierig, bei ihnen zu sein*!", footnotes: ["℘ V. 19; Kap. 3,31; Ps 73,3", "℘ Kap. 4,14.15"] },
      { number: 2, text: "Denn ihr Herz plant Gewalttat, und Unheil reden ihre Lippen.*", footnotes: ["℘ Kap. 1,10.11; Ps 36,4.5"] },
      { number: 3, text: "Durch Weisheit wird ein Haus gebaut*, und durch Verstand wird es befestigt;", footnotes: ["℘ Kap. 14,1; 1Kor 3,10"] },
      { number: 4, text: "und durch Erkenntnis füllen sich die Kammern mit allerlei kostbaren und angenehmen Gütern*.", footnotes: ["℘ Kap. 8,18"] },
      { number: 5, text: "Ein weiser Mann ist mehr als ein starker*, und ein Mann von Erkenntnis ist besser als ein kraftvoller.*", footnotes: ["so mit LXX, der syr. und aram. Üs.; Mas. T.: <steht> in Kraft", "℘ Kap. 21,22"] },
      { number: 6, text: "Denn mit weiser Überlegung* führst du deinen Krieg*, und Rettung <kommt> durch viele Ratgeber*.", footnotes: ["o. mit kluger Lenkung", "℘ Kap. 20,18", "℘ Kap. 11,14; 15,22"] },
      { number: 7, text: "Zu hoch* ist dem Narren die Weisheit*, im Tor macht er seinen Mund nicht auf*.", footnotes: ["w. <Wie> Korallen; d. h. unerreichbar", "℘ Kap. 14,6; 28,5", "℘ Kap. 31,23"] },
      { number: 8, text: "Wer darauf sinnt, Böses zu tun, den nennt man einen Ränkeschmied.*", footnotes: ["℘ Kap. 6,14.18"] },
      { number: 9, text: "Die Ränke des Narren sind Sünde, und ein Gräuel für die Menschen ist der Spötter." },
      { number: 10, text: "Zeigst du dich lässig* am Tag der Not, gerät <auch> deine Kraft in Not*.*", footnotes: ["o. mutlos", "o. am Tag der Knappheit, ist <auch> deine Kraft knapp", "℘ Hi 4,5"] },
      { number: 11, text: "Rette die, die zum Tode geschleppt werden; und die zur Schlachtung hinwanken, halte <sie> doch zurück!" },
      { number: 12, text: "Wenn du sagst: Siehe, wir wussten nichts davon*! — ist es nicht so: der die Herzen prüft*, er merkt es, und der auf deine Seele achthat, er weiß es?* Er vergilt dem Menschen nach seinem Tun.*", footnotes: ["o. Siehe, jener (d. i. Gott) weiß nichts von uns", "℘ Kap. 16,2", "℘ Kla 3,36", "℘ Kap. 5,22; Hi 34,11; Mt 16,27; Offb 20,12"] },
      { number: 13, text: "Iss Honig, mein Sohn, denn er ist gut, und <Waben>honig ist deinem Gaumen süß.*", footnotes: ["℘ Kap. 25,16.27; Ri 14,9; 1Sam 14,27"] },
      { number: 14, text: "Ebenso suche die Weisheit für deine Seele!* Wenn du sie gefunden hast, so gibt es Zukunft, und deine Hoffnung wird nicht vernichtet*.*", footnotes: ["℘ Ps 19,11", "w. nicht abgeschnitten", "℘ Kap. 23,18"] },
      { number: 15, text: "Laure nicht der Wohnstätte* des Gerechten auf, du Gottloser; zerstöre nicht seinen Lagerplatz!", footnotes: ["o. der Weide"] },
      { number: 16, text: "Denn siebenmal fällt der Gerechte und steht <doch wieder> auf*, aber die Gottlosen stürzen nieder im Unglück*.", footnotes: ["℘ Ps 37,24", "℘ Kap. 13,21; 4Mo 32,23; Hes 7,5; Am 8,14"] },
      { number: 17, text: "Wenn dein Feind fällt, freue dich nicht, und wenn er stürzt, jauchze dein Herz nicht*,", footnotes: ["℘ Kap. 17,5; Mi 7,8"] },
      { number: 18, text: "damit nicht der HERR es sieht und es böse ist in seinen Augen und er seinen Zorn von jenem abwendet!" },
      { number: 19, text: "Entrüste dich nicht über die Übeltäter! Ereifere dich nicht gegen die Gottlosen!*", footnotes: ["℘ V. 1; Kap. 23,17"] },
      { number: 20, text: "Denn für den Bösen gibt es keine Zukunft, die Leuchte der Gottlosen erlischt.*", footnotes: ["℘ Kap. 13,9; Ps 37,2.20"] },
      { number: 21, text: "Fürchte den HERRN, mein Sohn, und den König!* Mit Aufrührern* lass dich nicht ein*!*", footnotes: ["℘ Kap. 23,17; Pred 8,2; 1Petr 2,13.17", "o. Mit Andersgesinnten", "LXX: Gegen beide empöre dich nicht", "℘ Kap. 17,11"] },
      { number: 22, text: "Denn plötzlich erhebt sich ihr Verderben* und ihrer beider Untergang* unvermutet.*", footnotes: ["℘ Kap. 6,15; 2Sam 18,8; 1Kö 1,49; Pred 9,12; Röm 13,2.7", "o. geht Verderben von ihnen aus und Untergang von ihnen beiden", "o. und ihrer beider Untergang — wer kennt ihn?"] },
      { number: 23, text: "Auch diese sind von den Weisen: Die Person ansehen im Gericht ist nicht gut.*", footnotes: ["℘ Kap. 18,5; 28,21; Jak 2,1"] },
      { number: 24, text: "Wer zu dem Schuldigen* sagt: Du bist gerecht! — den verfluchen Völker, den verwünschen Völkerschaften.*", footnotes: ["o. Gottlosen", "℘ Kap. 17,15.26"] },
      { number: 25, text: "Denen aber, die <ihn> zurechtweisen*, geht es gut, und über sie kommt der Segen des Guten.", footnotes: ["o. die für das Recht eintreten"] },
      { number: 26, text: "Die Lippen küsst, wer eine richtige Antwort gibt.*", footnotes: ["℘ Kap. 25,11"] },
      { number: 27, text: "Besorge draußen deine Arbeit und bestelle sie dir auf dem Feld! Danach magst du dann dein Haus bauen*.*", footnotes: ["d. h. eine Familie gründen", "℘ Pred 3,1.2"] },
      { number: 28, text: "Werde nicht ohne Grund* Zeuge gegen deinen Nächsten! Willst du etwa täuschen mit deinen Lippen?", footnotes: ["o. nicht ein lügenhafter"] },
      { number: 29, text: "Sage nicht: Wie er mir getan hat, so will ich ihm tun, will jedem vergelten nach seinem Tun!*", footnotes: ["℘ Kap. 20,22; 25,21; Röm 12,19"] },
      { number: 30, text: "Am Acker eines Faulen kam ich vorüber und am Weinberg eines Menschen ohne Verstand." },
      { number: 31, text: "Und siehe, er war ganz in Nesseln aufgegangen, seine Fläche war mit Unkraut bedeckt, und seine steinerne Mauer eingerissen.*", footnotes: ["℘ Kap. 13,4; Jes 5,5.6; Hebr 6,8"] },
      { number: 32, text: "Und ich schaute es, ich nahm es mir zu Herzen*. Ich sah es, nahm mir <daraus> die Lehre:", footnotes: ["w. richtete mein Herz darauf"] },
      { number: 33, text: "Noch ein wenig Schlaf, noch ein wenig Schlummer, noch ein wenig Händefalten, um auszuruhen, —" },
      { number: 34, text: "und wie ein Landstreicher* kommt deine Armut, und dein Mangel wie ein unverschämter Mann*.*", footnotes: ["so mit vielen hebr. Handschr.; Mas. T.: und umherziehend", "o. wie ein schildbewehrter Mann", "℘ Kap. 6,10.11; 18,9; 28,19"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Auch dies sind Sprüche Salomos*, die die Männer Hiskias, des Königs von Juda, zusammengetragen haben:", footnotes: ["℘ Kap. 1,1"] },
      { number: 2, text: "Gottes Ehre ist es, eine Sache zu verbergen*, die Ehre der Könige aber, eine Sache zu erforschen*.", footnotes: ["℘ 5Mo 29,28; Röm 11,33", "℘ V. 27; 2Sam 14,19; 1Kö 3,16-28; Pred 1,13"] },
      { number: 3, text: "Der Himmel an Höhe und die Erde an Tiefe und das Herz der Könige sind unerforschlich." },
      { number: 4, text: "Man entferne die Schlacken aus dem Silber, so gelingt dem Goldschmied ein Gerät*.*", footnotes: ["w. so kommt für den Goldschmied ein Gerät heraus", "℘ Ps 66,10; Mal 3,3"] },
      { number: 5, text: "Man entferne den Gottlosen vom König, so steht sein Thron fest durch Gerechtigkeit.*", footnotes: ["℘ Kap. 16,12; 1Kö 2,33.45.46"] },
      { number: 6, text: "Brüste dich nicht vor dem König und an den Platz der Großen stelle dich nicht!*", footnotes: ["℘ Röm 12,16"] },
      { number: 7, text: "Denn besser man sagt zu dir: Komm hier herauf! — als dass man dich heruntersetzt vor einem Edlen.* Was deine Augen gesehen haben", footnotes: ["℘ Lk 14,10"] },
      { number: 8, text: "— geh <damit> nicht vorschnell zum Gericht!* Denn* was willst du hinterher machen, wenn dich dein Nächster beschämt? —", footnotes: ["℘ Pred 7,9", "T.; Mas. T. viell.: damit nicht <für dich die Frage entsteht>:"] },
      { number: 9, text: "Deinen Rechtsstreit führe mit deinem Nächsten, aber gib nicht preis, was ein anderer dir anvertraut hat*,", footnotes: ["w. aber die vertraute Beratung eines anderen decke nicht auf"] },
      { number: 10, text: "damit dich nicht schmäht, wer es hört, und dein übler Ruf nicht mehr weicht*!*", footnotes: ["o. und deine Verleumdung kannst du nicht mehr zurücknehmen", "℘ Pred 7,1"] },
      { number: 11, text: "Goldene Äpfel in silbernen Prunkschalen, <so ist> ein Wort, geredet zu seiner Zeit*.*", footnotes: ["o. auf seine rechte Art", "℘ Kap. 15,23; 24,26; 1Sam 25,35; Hi 4,4; Jes 50,4"] },
      { number: 12, text: "Ein goldener Ohrring und ein Halsgeschmeide aus feinem Gold, <so ist> ein weiser Mahner für ein hörendes Ohr.*", footnotes: ["℘ Ps 141,5"] },
      { number: 13, text: "Wie Kühlung des Schnees an einem Erntetag ist ein zuverlässiger* Bote denen, die ihn senden: die Seele seines Herrn erquickt er.*", footnotes: ["o. treuer; o. wahrhaftiger", "℘ Kap. 13,17"] },
      { number: 14, text: "Aufziehende <Wolken> mit Wind, doch kein Regen*, <so ist> ein Mann, der mit trügerischem Geschenk* prahlt.", footnotes: ["℘ Jud 12", "d. i. eine versprochene, aber nicht gewährte Gabe"] },
      { number: 15, text: "Durch langen Atem wird ein Richter* überredet*, und eine sanfte Zunge zerbricht Knochen*.", footnotes: ["o. Fürst", "℘ Pred 10,4", "℘ Kap. 15,1.4; 16,32"] },
      { number: 16, text: "Hast du Honig gefunden, iss <nur> deinen Bedarf, damit du ihn nicht satt wirst und ihn ausspeist!*", footnotes: ["℘ V. 27; Kap. 24,13"] },
      { number: 17, text: "Mache deinen Fuß selten im Haus deines Nächsten, damit er dich nicht satt wird und dich hasst!" },
      { number: 18, text: "Hammer und Schwert und geschärfter Pfeil, <so ist> ein Mann, der als falscher Zeuge gegen seinen Nächsten aussagt." },
      { number: 19, text: "Ein zerbrochener Zahn und ein wankender Fuß, <so ist> das Vertrauen auf den Treulosen am Tag der Not.*", footnotes: ["℘ 2Chr 28,21; Hi 6,14-20; Jes 30,3.7; 2Tim 4,16"] },
      { number: 20, text: "Einer, der das Oberkleid ablegt am Tag der Kälte, <oder> Essig auf Natron, so <ist es>, wenn einer einem traurigen Herzen Lieder singt.*", footnotes: ["℘ Ps 137,3"] },
      { number: 21, text: "Wenn dein Hasser Hunger hat, gib ihm Brot zu essen, und wenn er Durst hat, gib ihm Wasser zu trinken!*", footnotes: ["℘ Kap. 24,29; 2Kö 6,22; 2Chr 28,15; Lk 6,27"] },
      { number: 22, text: "Denn glühende Kohlen häufst du auf sein Haupt*, und der HERR wird es dir vergelten*.", footnotes: ["℘ Röm 12,20", "℘ 1Sam 24,18-20; Lk 6,35"] },
      { number: 23, text: "Nordwind gebiert Regen*, und eine heimliche Zunge verdrießliche Gesichter.", footnotes: ["℘ Hi 37,9"] },
      { number: 24, text: "Besser, auf dem Dach in einer Ecke wohnen, als eine zänkische Frau und ein gemeinsames Haus.*", footnotes: ["℘ Kap. 21,9; 27,15"] },
      { number: 25, text: "Kühles Wasser auf eine lechzende Kehle*, so ist eine gute Nachricht aus einem fernen Land.*", footnotes: ["o. Seele", "℘ Kap. 15,30; 1Mo 45,27; Jos 22,33"] },
      { number: 26, text: "Getrübter Quell und verdorbener Brunnen, <so ist> ein Gerechter, der vor einem Gottlosen wankt." },
      { number: 27, text: "Zu viel Honig essen ist nicht gut*, und das Suchen von Ehre <bleibt> ohne Ehre*!", footnotes: ["℘ V. 16", "T.; LXX liest: und ehrenvolle Worte muss man schätzen"] },
      { number: 28, text: "Eine aufgebrochene Stadt ohne Mauer, <so ist> ein Mann ohne Selbstbeherrschung*.*", footnotes: ["w. ein Mann, der keine Schranke seinem Geist <setzt>", "℘ Kap. 19,18"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Wie Schnee im Sommer und wie Regen in der Ernte*, so unpassend ist Ehre für einen Toren*.", footnotes: ["℘ 1Sam 12,17.18", "℘ Kap. 19,10"] },
      { number: 2, text: "Wie der Sperling hin und her flattert, wie die Schwalbe wegfliegt, so ein unverdienter Fluch: er trifft nicht ein.*", footnotes: ["℘ 4Mo 23,8; 2Sam 16,8; Ps 109,28"] },
      { number: 3, text: "Die Peitsche für das Pferd, der Zaum für den Esel* und der Stock für den Rücken der Toren*.", footnotes: ["℘ Ps 32,9", "℘ Kap. 10,13"] },
      { number: 4, text: "Antworte dem Toren nicht nach seiner Narrheit, damit nicht auch du ihm gleich wirst!" },
      { number: 5, text: "Antworte dem Toren nach seiner Narrheit, damit er nicht weise bleibt in seinen Augen!" },
      { number: 6, text: "Es verstümmelt sich die Füße, es trinkt Gewalttat*, wer Nachricht sendet durch einen Toren.", footnotes: ["Andere üs. mit Textänderung: Es entblößt sein Gesäß; d. h. es bringt sich in Schande"] },
      { number: 7, text: "Schlaff hängen die Schenkel am Lahmen herab, so ist ein Weisheitsspruch im Mund der Toren.*", footnotes: ["℘ Kap. 17,7"] },
      { number: 8, text: "Wie das Festbinden eines Steines in einer Schleuder*, so <ist>, wer einem Toren Ehre erweist.", footnotes: ["Wortbedeutung unsicher; viell. auch: Wie ein Bündel Edelsteine auf einem Steinhaufen"] },
      { number: 9, text: "Ein Dornzweig geriet in die Hand eines Betrunkenen und ein Weisheitsspruch in den Mund von Toren." },
      { number: 10, text: "Ein Schütze, der alles verwundet, so ist, wer einen Toren in Dienst nimmt und Vorübergehende in Dienst nimmt*.", footnotes: ["Andere üs. mit Textänderung: Ein Schütze, der alle Vorübergehenden verwundet, so ist einer, der einen Toren oder einen Betrunkenen in Dienst nimmt"] },
      { number: 11, text: "Wie ein Hund, der zurückkehrt zu seinem Gespei*, <so ist> ein Tor, der seine Narrheit wiederholt.", footnotes: ["℘ 2Petr 2,22"] },
      { number: 12, text: "Siehst du einen Mann, der in seinen Augen weise ist — für einen Toren gibt es mehr Hoffnung als für ihn.*", footnotes: ["℘ Kap. 3,7; 12,15; 28,26; 29,20; Jes 5,21"] },
      { number: 13, text: "Der Faule spricht: Ein Junglöwe ist auf dem Weg, ein Löwe mitten auf den Plätzen!*", footnotes: ["℘ Kap. 22,13"] },
      { number: 14, text: "Die Tür dreht sich in ihrer Angel und der Faule auf seinem Bett.*", footnotes: ["℘ Kap. 6,9.10"] },
      { number: 15, text: "Hat der Faule seine Hand in die Schüssel gesteckt, ist es ihm zu beschwerlich, sie an seinen Mund zurückzubringen.*", footnotes: ["℘ Kap. 19,24"] },
      { number: 16, text: "Der Faule ist in seinen Augen weiser als sieben, die verständig antworten." },
      { number: 17, text: "Der packt einen Hund bei den Ohren, wer im Vorbeigehen sich über einen Streit ereifert*, der ihn nichts angeht.*", footnotes: ["o. Der packt einen vorüberlaufenden Hund bei den Ohren, wer sich über einen Streit ereifert", "℘ Kap. 20,3; 1Petr 4,15"] },
      { number: 18, text: "Wie ein Wahnsinniger, der Brandgeschosse, Pfeile und Tod schleudert," },
      { number: 19, text: "so ist ein Mann, der seinen Nächsten betrügt und <dann> sagt: Habe ich <denn> nicht <nur> Spaß gemacht?*", footnotes: ["℘ Kap. 10,23"] },
      { number: 20, text: "Wo das Holz zu Ende geht, erlischt das Feuer; und wo kein Verleumder ist, kommt der Zank zur Ruhe.*", footnotes: ["℘ Kap. 16,28; 22,10"] },
      { number: 21, text: "Kohle zur Kohlenglut* und Holz zum Feuer und einen zänkischen Mann, um Streit zu entfachen.*", footnotes: ["Andere üs. in Anlehnung an LXX: Den Blasebalg zur Kohlenglut", "℘ Kap. 29,22; 30,33"] },
      { number: 22, text: "Die Worte des Verleumders sind wie Leckerbissen*, und sie gleiten hinab in die Kammern des Leibes.*", footnotes: ["w. wie <Speisen>, die man gierig verschlingt", "℘ Kap. 18,8"] },
      { number: 23, text: "Silberglasur, auf Tongeschirr gebracht, <so sind> feurige Lippen* und ein böses Herz.*", footnotes: ["LXX: glatte Lippen", "℘ Kap. 23,7; 27,6"] },
      { number: 24, text: "Mit seinen Lippen verstellt sich der Hasser, aber in seinem Innern hegt er Betrug.*", footnotes: ["℘ Kap. 10,18; 12,20; 1Mo 34,13; 2Sam 13,26; 20,9; Ps 12,3; 28,3"] },
      { number: 25, text: "Wenn er seine Stimme lieblich macht, traue ihm nicht! Denn sieben Gräuel sind in seinem Herzen.*", footnotes: ["℘ 1Sam 18,17; Neh 6,2; Jer 12,6"] },
      { number: 26, text: "Mag sich der Hass verbergen* in Täuschung, seine Bosheit wird <doch> in der Versammlung enthüllt werden.", footnotes: ["die alten Üs.: Mag einer <seinen> Hass auch verbergen"] },
      { number: 27, text: "Wer eine Grube gräbt, fällt selbst hinein*; und wer einen Stein wälzt, auf den rollt er zurück*.", footnotes: ["℘ Ps 7,16", "℘ Kap. 5,22; 28,10; Est 7,10; 9,25; Pred 10,8; Jes 3,8-11"] },
      { number: 28, text: "Eine Lügenzunge hasst die von ihr Zermalmten*; und ein glatter Mund bereitet Sturz.*", footnotes: ["der Text ist unsicher; LXX: hasst Wahrheit; andere üs. mit Textänderung: bringt Zusammenbruch", "℘ Kap. 2,16; 29,5"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Rühme dich nicht des morgigen Tages! Denn du weißt nicht, was ein Tag gebiert.*", footnotes: ["℘ 1Kö 20,11; Est 5,12; Lk 12,19.20; Jak 4,13-16"] },
      { number: 2, text: "Es rühme dich ein anderer und nicht dein <eigener> Mund, ein Fremder und nicht deine Lippen!*", footnotes: ["℘ Kap. 20,6; 2Kö 10,16; 2Kor 10,12.18"] },
      { number: 3, text: "Schwer ist der Stein, und eine Last ist der Sand, aber der Ärger über* einen Narren ist schwerer als beide.*", footnotes: ["o. die Kränkung durch", "℘ Kap. 17,12; Est 3,5.6"] },
      { number: 4, text: "Grausam ist der Grimm und überflutend der Zorn. Wer aber kann bestehen vor der Eifersucht?*", footnotes: ["℘ Kap. 6,34.35; 1Sam 18,9.29; 1Jo 3,12"] },
      { number: 5, text: "Besser offene Rüge als verborgen gehaltene Liebe." },
      { number: 6, text: "Treu gemeint sind die Schläge* dessen, der liebt, aber überreichlich* die Küsse des Hassers.*", footnotes: ["w. <die durch Schläge zugefügten> Wunden", "Wortbedeutung unsicher; andere üs.: trügerisch; andere mit Textänderung: wie Messer", "℘ Kap. 26,23; 2Sam 20,9.10"] },
      { number: 7, text: "Der Satte* tritt Honig <mit Füßen>; aber dem Hungrigen* ist alles Bittere süß.*", footnotes: ["w. Die satte Seele", "w. der hungrigen Seele", "℘ Lk 15,16.17"] },
      { number: 8, text: "Wie ein Vogel, der fern von seinem Nest schweift*, so ist ein Mann, der fern von seinem Wohnort schweift.", footnotes: ["℘ 1Kö 11,22; Hebr 11,13-16"] },
      { number: 9, text: "Öl und Räucherwerk erfreuen das Herz, und die Süße eines* Freundes <kommt> aus dem Rat der Seele*.*", footnotes: ["w. seines", "Andere üs. mit Textänderung: aber von Betrübnis zerreißt sich die Seele", "℘ Kap. 16,24; 1Kö 1,12"] },
      { number: 10, text: "Deinen Freund und deines Vaters Freund lass nicht fahren* und geh nicht in deines Bruders Haus am Tag deiner Not! Besser ein naher Nachbar als ein ferner Bruder.*", footnotes: ["℘ Kap. 18,24; 2Chr 10,8", "℘ Kap. 19,7"] },
      { number: 11, text: "Sei weise, mein Sohn, und erfreue mein Herz*, damit ich meinem Schmäher Antwort geben kann*!", footnotes: ["℘ Kap. 23,24.25; 29,3", "℘ Ps 119,42"] },
      { number: 12, text: "Der Kluge sieht das Unglück <und> verbirgt sich; die Einfältigen* gehen weiter <und> müssen büßen.*", footnotes: ["o. Unerfahrenen; o. Unverständigen", "℘ Kap. 22,3"] },
      { number: 13, text: "Nimm ihm das Gewand, denn er hat für einen anderen gebürgt, und anstelle der Ausländerin* pfände ihn!*", footnotes: ["o. wegen der fremden Sache", "℘ Kap. 6,1-5"] },
      { number: 14, text: "<Da ist einer,> der wünscht — am Morgen früh aufgestanden — seinem Nächsten mit lauter Stimme Glück*, aber als Verwünschung wird es ihm angerechnet.", footnotes: ["o. der entbietet . . . seinem Nächsten . . . den Friedensgruß"] },
      { number: 15, text: "Ein tropfendes Dach, das <einen> vertreibt* am Tag des Regengusses, und eine zänkische Frau gleichen sich.*", footnotes: ["o. Eine ständig tropfende Dachtraufe", "℘ Kap. 21,9.19; 25,24"] },
      { number: 16, text: "Wer sie zurückhalten will, hält Wind zurück, und seine Rechte greift nach Öl*.", footnotes: ["w. und Öl begegnet seiner Rechten"] },
      { number: 17, text: "Eisen wird durch Eisen geschärft, und ein Mann schärft das Angesicht seines Nächsten*.*", footnotes: ["so mit Vulg. und der aram. Üs.; Mas. T.: Eisen zusammen mit Eisen und ein Mann zusammen mit seinem Nächsten", "℘ Kap. 29,22"] },
      { number: 18, text: "Wer den Feigenbaum hütet, wird seine Frucht essen*; und wer über seinen Herrn wacht, wird geehrt werden*.", footnotes: ["℘ 1Kor 9,7", "℘ Est 6,11"] },
      { number: 19, text: "Wie im Wasser das Gesicht dem Gesicht <entspricht>, so das Herz des Menschen dem Menschen.*", footnotes: ["o. Wie sich im Wasser das Gesicht spiegelt, so das Herz eines Menschen in dem <des> anderen."] },
      { number: 20, text: "Scheol und Abgrund* werden nicht satt*, und die Augen des Menschen werden nicht satt*.", footnotes: ["d. i. der Ort des Untergangs, der Aufenthaltsort der Toten", "℘ Kap. 30,16; Hab 2,5", "℘ Pred 1,8; 4,8"] },
      { number: 21, text: "Der Schmelztiegel für das Silber und der Ofen für das Gold*, und ein Mann <wird beurteilt> nach seinem Ruf*.", footnotes: ["℘ Kap. 17,3", "o. von dem, der ihn lobt"] },
      { number: 22, text: "Zerstießest du den Narren mit dem Stößel im Mörser mitten unter den Sandkörnern*, so würde seine Narrheit <doch> nicht von ihm weichen.*", footnotes: ["T.; Mas. T.: unter der Grütze; Wortbedeutung unsicher", "℘ Kap. 14,24; 1Kö 13,33"] },
      { number: 23, text: "Kümmere dich sorgfältig um das Aussehen deiner Schafe*, richte deine Aufmerksamkeit* auf die Herden*!", footnotes: ["℘ Joh 10,14", "w. dein Herz", "℘ 1Petr 5,2"] },
      { number: 24, text: "Denn nicht ewig <reicht> der Vorrat.* Und <währt> etwa eine Krone von Generation zu Generation?*", footnotes: ["℘ Kap. 23,4.5; Pred 5,13; Jak 1,9-11", "Andere üs. mit Textänderung: Und auch Reichtum <währt> nicht von Generation zu Generation.\n℘ 1Sam 13,14"] },
      { number: 25, text: "Ist das Heu geerntet* und erscheint frisches Gras und sind eingesammelt die Kräuter der Berge*,", footnotes: ["w. verschwunden", "℘ Ps 147,8"] },
      { number: 26, text: "<dann gibt es> Lämmer zu deiner Bekleidung und Böcke als Kaufpreis für ein Feld*;", footnotes: ["℘ Hes 27,21"] },
      { number: 27, text: "und genug Ziegenmilch ist da zu deiner Nahrung, zur Nahrung deines Hauses, und Lebensunterhalt für deine Mägde*.", footnotes: ["℘ Kap. 6,8"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Es flieht der Gottlose, ohne dass ihm einer nachjagt*; der Gerechte* aber fühlt sich sicher* wie ein Junglöwe.", footnotes: ["℘ 3Mo 26,17.36; 2Kö 7,7; Hi 15,21", "so mit einer hebr. Handschr. und LXX; Mas. T.: die Gerechten", "℘ Neh 6,11"] },
      { number: 2, text: "Durch die Verbrechen* eines Landes werden zahlreich seine Obersten*; aber durch einen verständigen, einsichtigen Mann hat das Rechte lange Bestand.*", footnotes: ["w. das Verbrechen", "℘ 1Kö 16,8-22", "die Üs. ist ein Versuch; LXX: Durch das Verbrechen eines Gewalttätigen werden Streitigkeiten geweckt, aber durch einen verständigen Mann verlöschen sie."] },
      { number: 3, text: "Ein Mann, der ein Haupt ist und die* Geringen unterdrückt, ist ein Regen, der wegschwemmt und kein Brot <bringt>.", footnotes: ["T.; LXX: Ein gottloser Mann, der die; Mas. T.: Ein Mann, der arm ist und die"] },
      { number: 4, text: "Die das Gesetz verlassen, rühmen die Gottlosen; die aber das Gesetz bewahren, entrüsten sich über sie*.*", footnotes: ["o. kämpfen gegen sie", "℘ Neh 5,7-13; 13,11; Eph 5,11"] },
      { number: 5, text: "Böse Menschen verstehen nicht, was recht ist*; die aber den HERRN suchen, verstehen alles*.", footnotes: ["o. verstehen nichts vom Recht\n℘ Kap. 24,7; Jes 1,3; Jer 4,22; Am 3,10", "℘ Ps 119,98-100; 1Kor 2,15"] },
      { number: 6, text: "Besser ein Armer, der in seiner Lauterkeit lebt*, als ein Verschlagener*<, der> auf zwei Wegen <geht> und der dabei reich ist.*", footnotes: ["o. in seiner Vollkommenheit wandelt", "w. als ein Verdrehter", "℘ Kap. 16,8; 19,1"] },
      { number: 7, text: "Wer das Gesetz befolgt, ist ein verständiger Sohn*; wer sich aber mit Schlemmern einlässt, macht seinem Vater Schande*.", footnotes: ["℘ Kap. 2,1-5", "℘ Kap. 23,20.21"] },
      { number: 8, text: "Wer seinen Besitz durch Zins und durch Aufschlag vermehrt, sammelt ihn für den, der sich über die Geringen erbarmt.*", footnotes: ["℘ Kap. 13,22"] },
      { number: 9, text: "Wer sein Ohr abwendet vom Hören des Gesetzes, dessen Gebet sogar ist ein Gräuel.*", footnotes: ["℘ Kap. 15,8; Ps 109,7; Jer 14,12"] },
      { number: 10, text: "Wer Redliche* irreführt auf einen bösen Weg, wird selbst in seine Grube fallen;* aber die Lauteren nehmen Gutes in Besitz.", footnotes: ["o. Aufrichtige", "℘ Kap. 26,27"] },
      { number: 11, text: "Weise in seinen Augen ist der Reiche*, aber ein Geringer, der verständig ist, durchschaut ihn.", footnotes: ["℘ Kap. 18,11; Jes 10,13"] },
      { number: 12, text: "Wenn die Gerechten triumphieren*, ist die Herrlichkeit groß*; wenn aber die Gottlosen aufkommen, versteckt sich der Mensch*.", footnotes: ["o. frohlocken", "℘ Kap. 11,10; 29,2; Est 8,15-17", "℘ 1Kö 18,13; Jer 36,19"] },
      { number: 13, text: "Wer seine Verbrechen zudeckt, wird keinen Erfolg haben*; wer sie aber bekennt und lässt, wird Erbarmen finden*.", footnotes: ["℘ 1Sam 15,13; Hi 31,33; 34,31; Jer 2,35", "℘ Ri 10,15.16; 2Sam 12,13; 2Chr 6,26.27; Esr 10,2; Ps 32,3.5; Jes 55,7; Jon 3,10"] },
      { number: 14, text: "Glücklich der Mensch, der beständig in der <Gottes>furcht bleibt!* Wer aber sein Herz verhärtet, wird ins Unglück fallen.*", footnotes: ["℘ Pred 8,12; Phil 2,12", "℘ Kap. 29,1; 2Mo 7,23; Hi 9,4; Röm 2,5"] },
      { number: 15, text: "Ein knurrender Löwe und ein gieriger* Bär, <so ist> ein gottloser Herrscher über ein geringes Volk.*", footnotes: ["o. hervorbrechender", "℘ 2Mo 1,13; Jes 14,5.6; Zef 3,3"] },
      { number: 16, text: "<Mancher> Fürst ist ohne Verstand und reich an Erpressungen; wer <aber> unrechtmäßigen Gewinn hasst, wird <seine> Tage verlängern.*", footnotes: ["℘ Kap. 15,27"] },
      { number: 17, text: "Ein Mensch, belastet mit dem Blut einer Seele, ist flüchtig bis zum Grab; man unterstütze ihn nicht!*", footnotes: ["℘ 1Mo 4,12; 2Mo 21,14; 5Mo 19,11.12; 2Sam 13,34; 18,15; 1Kö 2,29; 1Jo 5,16"] },
      { number: 18, text: "Wer redlich lebt*, findet Hilfe*; wer aber krumme Wege* geht, wird auf einem <davon> fallen*.", footnotes: ["o. ungeteilt <mit Gott> geht; vgl. 5Mo 18,13", "℘ V. 10.26; Kap. 10,9; 11,5", "w. Doppelwege", "syr. Üs.: fällt in die Grube\n℘ 4Mo 22,21.35"] },
      { number: 19, text: "Wer sein Ackerland bebaut, wird sich satt essen können an Brot; wer aber nichtigen Dingen nachjagt, wird sich an der Armut satt essen.*", footnotes: ["℘ Kap. 12,11; 24,34"] },
      { number: 20, text: "Ein zuverlässiger* Mann ist reich an Segnungen*; wer aber hastet, um es zu Reichtum zu bringen, bleibt nicht ungestraft*.", footnotes: ["o. wahrhaftiger", "o. Segenswünschen\n℘ Kap. 10,6", "℘ Kap. 13,11"] },
      { number: 21, text: "Die Person ansehen* ist nicht gut*, und für einen Bissen Brot kann ein Mann zum Verbrecher werden*.", footnotes: ["d. h. parteiisch sein", "℘ Kap. 24,23; 5Mo 1,17", "w. verbrecherisch handeln\n℘ Hes 13,19; Mi 3,5"] },
      { number: 22, text: "Ein missgünstiger Mann* hastet nach Besitz, und er erkennt nicht, dass Mangel über ihn kommt.*", footnotes: ["o. Ein habgieriger Mann; w. Ein Mann der Bosheit des Auges", "℘ 1Tim 6,9"] },
      { number: 23, text: "Wer einen Menschen zurechtweist, findet letztlich mehr Gunst als einer, der mit der Zunge schmeichelt.*", footnotes: ["℘ Hi 32,21"] },
      { number: 24, text: "Wer seinen Vater oder seine Mutter beraubt und sagt: <Das ist> kein Verbrechen! — der ist ein Geselle des Verderbers.*", footnotes: ["℘ Kap. 19,26"] },
      { number: 25, text: "Der Habgierige* erregt Streit*; wer aber auf den HERRN vertraut, wird reichlich gesättigt*.", footnotes: ["w. Die unbegrenzte Seele", "o. zettelt <schnell> einen Prozess an\n℘ Kap. 13,10", "w. wird fett gemacht\n℘ 1Tim 6,6"] },
      { number: 26, text: "Wer auf seinen Verstand* vertraut, der ist ein Tor*; wer aber in Weisheit lebt*, der wird entkommen.", footnotes: ["w. auf sein Herz", "℘ Kap. 3,5-7; 26,12", "w. geht"] },
      { number: 27, text: "Wer dem Armen gibt, wird keinen Mangel haben*; wer aber seine Augen verhüllt, wird reich an Flüchen*.", footnotes: ["℘ Kap. 19,17; 22,9", "℘ Kap. 11,25.26"] },
      { number: 28, text: "Wenn die Gottlosen aufkommen, verbirgt sich der Mensch*; aber wenn sie umkommen, werden die Gerechten zahlreich.", footnotes: ["℘ 2Chr 22,12; Hi 24,4"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Ein Mann, der <trotz> Ermahnungen* halsstarrig bleibt, wird plötzlich zerschmettert werden ohne Heilung.*", footnotes: ["o. Warnungen; o. Rügen", "℘ Kap. 6,15; 28,14; 2Chr 36,16; Jes 28,22; Jer 14,19"] },
      { number: 2, text: "Wenn die Gerechten zahlreich sind*, freut sich das Volk*; wenn aber ein Gottloser herrscht, seufzt das Volk*.", footnotes: ["Andere üs. mit Textänderung: herrschen", "℘ Kap. 28,12", "℘ Est 3,15; Pred 4,1"] },
      { number: 3, text: "Ein Mann, der Weisheit liebt, erfreut seinen Vater*; wer sich aber mit Huren einlässt, richtet den Besitz zugrunde*.", footnotes: ["℘ Kap. 23,15; 27,11", "℘ Kap. 5,10; 6,26; Lk 15,13"] },
      { number: 4, text: "Ein König gibt durch das Recht dem Land Bestand*; aber wer <nur> Abgaben erhebt*, zerstört es.", footnotes: ["℘ Kap. 14,34; 16,10.12", "w. aber ein Mann der Abgaben"] },
      { number: 5, text: "Ein Mann, der seinem Nächsten schmeichelt, breitet ein Fangnetz vor seinen Schritten aus.*", footnotes: ["℘ Kap. 26,28; 1Sam 18,23"] },
      { number: 6, text: "Im Verbrechen des bösen Menschen <liegt> eine Falle <für ihn>*; aber der Gerechte jauchzt* und ist fröhlich*.", footnotes: ["℘ Hi 18,7-10", "mit einer hebr. Handschr.: läuft", "℘ Kap. 10,28"] },
      { number: 7, text: "Der Gerechte ist bedacht auf den Rechtsanspruch der Geringen*; der Gottlose versteht sich nicht auf Erkenntnis*.", footnotes: ["℘ Hi 29,16; Ps 72,12-14", "℘ 1Sam 25,25"] },
      { number: 8, text: "Spötter versetzen eine Stadt in Aufruhr*, Weise aber wenden den Zorn ab.*", footnotes: ["w. fachen eine Stadt an", "℘ Kap. 15,1"] },
      { number: 9, text: "Tritt ein weiser Mann mit einem närrischen Mann vor Gericht, tobt der und lacht, aber es gibt keine Ruhe." },
      { number: 10, text: "Blutmenschen hassen den Unschuldigen*, aber die Aufrichtigen suchen <das Beste für> sein Leben*.", footnotes: ["o. den Untadeligen; o. den Rechtschaffenen\n℘ 1Kö 22,8; 1Jo 3,12", "o. seine Seele. — Andere üs.: und den Aufrichtigen trachten sie nach dem Leben\n℘ Jer 38,7-13"] },
      { number: 11, text: "Seinen ganzen Unmut lässt der Tor herausfahren, aber der Weise beschwichtigt ihn zuletzt*.*", footnotes: ["mit einer hebr. Handschr.: aber der Weise vergisst ihn zuletzt; d. i. den Unmut", "℘ Kap. 12,16.23"] },
      { number: 12, text: "Ein Herrscher, der auf Lügenrede achtet, dessen Diener sind alle gottlos." },
      { number: 13, text: "Der Arme und der Unterdrücker* begegnen sich*; der ihrer beider Augen hell macht*, ist der HERR.", footnotes: ["w. der Mann der Bedrängungen o. Gewalttätigkeiten", "℘ Kap. 22,2", "s. Anm. zu Ps 13,4"] },
      { number: 14, text: "Ein König, der die Geringen in Wahrhaftigkeit richtet*, dessen Thron wird fest stehen für immer.*", footnotes: ["o. den Geringen in Treue Recht schafft", "℘ Kap. 20,28; Ps 72,2-4.17"] },
      { number: 15, text: "Rute und Ermahnung* geben Weisheit*; aber ein sich selbst überlassener Junge macht seiner Mutter Schande*.", footnotes: ["o. Rüge", "℘ Kap. 22,15", "℘ 1Kö 1,6"] },
      { number: 16, text: "Wenn die Gottlosen zahlreich werden, werden zahlreich die Verbrechen*; aber die Gerechten werden ihrem Sturz zusehen*.", footnotes: ["w. wird zahlreich das Verbrechen\n℘ Ps 12,9", "o. sich an ihrem Sturz weiden\n℘ Ps 37,34"] },
      { number: 17, text: "Züchtige deinen Sohn, so wird er dich erquicken und dir Freude machen*.*", footnotes: ["w. so wird er dich <in Ruhe> lagern lassen und deiner Seele Leckerbissen bereiten", "℘ Kap. 19,18"] },
      { number: 18, text: "Wenn keine Offenbarung* da ist, verwildert ein Volk; aber wohl ihm, wenn es das Gesetz beachtet!*", footnotes: ["w. keine Vision", "℘ Ps 119,1.2; Lk 11,28; Jak 1,25"] },
      { number: 19, text: "Durch Worte lässt sich ein Sklave nicht belehren; denn er versteht <zwar>, aber er kehrt sich nicht daran*.", footnotes: ["w. er antwortet nicht"] },
      { number: 20, text: "Siehst du einen Mann, der sich in seinen Worten überhastet — für einen Toren gibt es mehr Hoffnung als für ihn.*", footnotes: ["℘ Kap. 21,5; 26,12"] },
      { number: 21, text: "Wenn einer seinen Sklaven von Jugend auf verhätschelt, so wird der zuletzt rebellisch." },
      { number: 22, text: "Ein zorniger Mann erregt Streit*, und ein Hitziger ist reich an Vergehen*.", footnotes: ["o. zettelt <schnell> einen Prozess an\n℘ Kap. 15,18; 26,21; 27,17", "℘ 1Mo 49,7; Jak 1,20"] },
      { number: 23, text: "Der Hochmut eines Menschen erniedrigt ihn*; der Demütige* aber erlangt Ehre*.", footnotes: ["℘ Kap. 16,18; Ob 3; Apg 12,23", "w. der mit niedrigem Geist", "℘ Kap. 18,12; Mt 23,12"] },
      { number: 24, text: "Wer mit einem Dieb teilt, hasst sein Leben*; er hört den Fluch, aber zeigt es nicht an*.", footnotes: ["o. seine Seele\n℘ Kap. 1,11-19", "℘ 3Mo 5,1"] },
      { number: 25, text: "Menschenfurcht stellt eine Falle*; wer aber auf den HERRN vertraut, ist in Sicherheit*.", footnotes: ["℘ 1Mo 12,11-13; 5Mo 1,17; 1Sam 15,24; 21,13", "℘ Kap. 30,5; 1Chr 5,20"] },
      { number: 26, text: "Viele suchen das Angesicht eines Herrschers*, doch von dem HERRN <kommt> das Recht eines Mannes*.", footnotes: ["℘ Kap. 16,15", "o. <kommt> Rechtsspruch für jeden\n℘ 1Kor 4,3.4"] },
      { number: 27, text: "Ein Gräuel für die Gerechten ist der Übeltäter*, aber ein Gräuel für den Gottlosen ist, wer redlich <seinen> Weg <geht>*. —", footnotes: ["℘ Ps 101,4", "℘ Kap. 13,19; Joh 7,7"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Worte Agurs, des Sohnes des Jake, aus Massa.* *Ausspruch des Mannes: Bemüht habe ich mich um Gott*, bemüht habe ich mich um Gott* und bin vergangen*.", footnotes: ["o. des Sohnes des Jake: Spruch:", "T.; schwieriger, wohl fehlerhaft überlieferter Text; Mas. T. viell.: Ausspruch des Mannes zu Itiël, zu Itiël und Ukal", "o. o Gott", "o. o Gott", "o. o Gott"] },
      { number: 2, text: "Denn ich bin zu dumm für einen Mann*, und Menschenverstand habe ich nicht.*", footnotes: ["o. Ja, ich bin dümmer als irgendjemand", "℘ 1Kor 3,18"] },
      { number: 3, text: "Und Weisheit habe ich nicht gelernt, dass ich Erkenntnis des Heiligen kennen könnte*.*", footnotes: ["LXX: Gott <aber> lehrte mich Weisheit, so kenne ich die Erkenntnis der Heiligen o. des Heiligen", "℘ Kap. 9,10"] },
      { number: 4, text: "Wer ist hinaufgestiegen zum Himmel und herabgefahren?* Wer hat den Wind in seine Fäuste gesammelt? Wer hat das Wasser in ein Tuch eingebunden?* Wer hat aufgerichtet alle Enden der Erde?* Was ist sein Name* und was der Name seines Sohnes, wenn du es weißt?", footnotes: ["℘ Joh 3,13", "℘ Hi 26,8", "℘ Jes 40,12", "℘ Hi 11,7.8"] },
      { number: 5, text: "Alle Rede Gottes ist geläutert.* Ein Schild ist er denen, die bei ihm <ihre> Zuflucht suchen.*", footnotes: ["℘ Ps 119,140", "℘ Kap. 29,25; Ps 18,31"] },
      { number: 6, text: "Füge zu seinen Worten nichts hinzu*, damit er dich nicht überführt und du als Lügner dastehst!", footnotes: ["℘ 5Mo 4,2; 13,1; Offb 22,18"] },
      { number: 7, text: "Zweierlei erbitte ich von dir; verweigere es mir nicht, bevor ich sterbe:" },
      { number: 8, text: "Gehaltloses* und Lügenwort halte von mir fern!* Armut und Reichtum gib mir nicht, lass mich das Brot, das ich brauche*, genießen*,", footnotes: ["o. Falschheit", "℘ Kap. 13,5; Ps 119,29", "w. das Brot der mir zukommenden Gebühr", "℘ Mt 6,11; 1Tim 6,8"] },
      { number: 9, text: "damit ich nicht, satt geworden, leugne* und sage: Wer ist <denn> der HERR*? — und damit ich nicht, arm geworden, stehle und mich vergreife an dem Namen meines Gottes!", footnotes: ["℘ 5Mo 6,12; Hes 23,35; Hos 13,6", "℘ 2Mo 5,2"] },
      { number: 10, text: "Verleumde einen Sklaven nicht bei seinem Herrn, damit er dir nicht flucht und du es büßen musst!" },
      { number: 11, text: "Eine Generation, die dem* Vater flucht und die* Mutter nicht segnet*;", footnotes: ["w. ihrem", "w. ihre", "o. der Mutter nicht dankt\n℘ V. 17; Kap. 20,20; 23,22; 3Mo 20,9"] },
      { number: 12, text: "eine Generation, die in ihren Augen rein ist und doch nicht gewaschen von ihrem Unflat*;", footnotes: ["℘ Hos 12,9; Joh 9,41"] },
      { number: 13, text: "eine Generation — wie hochmütig ihre Augen und überheblich ihre Wimpern* —;", footnotes: ["℘ Kap. 21,4"] },
      { number: 14, text: "eine Generation, deren Zähne Schwerter sind und Messer ihr Gebiss*, um wegzufressen die Elenden von der Erde und die Armen weg aus der Mitte der Menschheit*!", footnotes: ["℘ Hi 29,17; Ps 14,4; 57,5", "℘ Jes 3,15; 10,2; Hes 22,6; 34,3; Mi 3,3"] },
      { number: 15, text: "Der Blutegel hat zwei Töchter*: Gib her, gib her! Drei sind es, die nicht satt werden, vier, die nicht sagen: Genug!", footnotes: ["o. Von Aluka: Zwei Töchter <sagen>"] },
      { number: 16, text: "Der Scheol* und der verschlossene Mutterleib*, die Erde, die an Wasser nie satt wird, und das Feuer, das nie sagt: Genug!", footnotes: ["℘ Kap. 27,20; Jes 5,14", "℘ 1Mo 30,1"] },
      { number: 17, text: "Ein Auge, das den Vater verspottet und den Gehorsam gegen die* Mutter verachtet, aushacken werden es die Raben am Bach und auffressen die jungen Adler*.*", footnotes: ["LXX: und das Altern der", "o. die jungen Geier", "℘ V. 11; 5Mo 21,21"] },
      { number: 18, text: "Drei sind es, die mir zu wunderbar sind, und vier, die ich nicht erkenne*:", footnotes: ["℘ Ps 139,6"] },
      { number: 19, text: "Der Weg des Adlers am Himmel, der Weg einer Schlange auf dem Felsen, der Weg eines Schiffes im Herzen des Meeres und der Weg eines Mannes mit einem Mädchen. —" },
      { number: 20, text: "So ist der Weg einer ehebrecherischen Frau: Sie isst und wischt ihren Mund und sagt: Ich habe nichts Unrechtes getan!*", footnotes: ["℘ 2Sam 11,4; Jer 2,23; Hebr 13,4"] },
      { number: 21, text: "Unter dreien erbebt die Erde, und unter vieren kann sie es nicht aushalten:" },
      { number: 22, text: "Unter einem Sklaven, wenn er König wird*, und einem törichten* Menschen, wenn er sich an Brot satt essen kann*,", footnotes: ["℘ Kap. 19,10", "o. einem gottlosen", "℘ 1Sam 25,2.3"] },
      { number: 23, text: "unter einer Verschmähten, wenn sie geheiratet wird*, und einer Magd, wenn sie ihre Herrin <aus dem Besitz> verdrängt*.", footnotes: ["℘ Kap. 12,4; 21,19", "o. beerbt"] },
      { number: 24, text: "Vier sind die Kleinen der Erde, und doch sind sie wohlerfahrene Weise*:", footnotes: ["LXX, die syr. Üs. und Vulg.: sind sie weiser als die Weisen\n℘ Hi 12,7"] },
      { number: 25, text: "Die Ameisen, ein nicht starkes Volk, und doch bereiten sie im Sommer ihre Speise*,", footnotes: ["℘ Kap. 6,8; 10,5"] },
      { number: 26, text: "die Klippdachse*, ein nicht kräftiges Volk, und doch legen sie im Felsen ihre Wohnungen an*;", footnotes: ["℘ 3Mo 11,5", "℘ Ps 104,18"] },
      { number: 27, text: "die Heuschrecken haben keinen König, und doch ziehen sie allesamt aus in geordneten Scharen*;", footnotes: ["℘ 2Mo 10,13-15; Joe 2,8"] },
      { number: 28, text: "die Eidechse* kannst du mit Händen fangen, und doch ist sie in Königspalästen.", footnotes: ["℘ 3Mo 11,29"] },
      { number: 29, text: "Drei sind es, die stattlich schreiten, und vier, die stattlich einhergehen:" },
      { number: 30, text: "Der Löwe, der Held unter den Tieren, der vor niemandem kehrtmacht*,", footnotes: ["℘ 2Sam 1,23; Hes 32,2"] },
      { number: 31, text: "der Hahn, der stolziert, und* der Ziegenbock und ein König, bei dem der Heerbann ist.", footnotes: ["T.; Mas. T.: der Hahn der Lenden oder"] },
      { number: 32, text: "Ob du töricht gehandelt hast, wenn du dich <selbst> erhobst, oder ob du überlegt gehandelt hast — die Hand auf den Mund!*", footnotes: ["℘ Hi 21,5"] },
      { number: 33, text: "Denn das Pressen der Milch bringt Butter hervor, und das Pressen der Nase bringt Blut hervor, und das Pressen des Zornes bringt Streit hervor.* —", footnotes: ["℘ Kap. 26,21"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Worte Lemuëls, des Königs von Massa, mit denen* seine Mutter ihn unterwies*:", footnotes: ["so mit anderer Zeichensetzung; Mas. T.: Worte des Königs Lemuël, Ausspruch, womit; andere üs.: Worte an Lemuël, den König von Massa", "℘ Kap. 1,8"] },
      { number: 2, text: "Was, mein Sohn *was, Lemuël, mein Erstgeborener, soll ich dir sagen* und was, du Sohn meines Leibes, und was, du Sohn meiner Gelübde*?", footnotes: ["so mit LXX; im Mas. T. fehlt dieses Satzstück", "so mit LXX; im Mas. T. fehlt dieses Satzstück", "℘ 1Sam 1,11.27.28"] },
      { number: 3, text: "Gib nicht den Frauen deine Kraft, noch deine Wege denen, die Könige auslöschen*.", footnotes: ["T.; Mas. T.: deine Wege <dazu>, Könige auszulöschen\n℘ 5Mo 17,17; Neh 13,26"] },
      { number: 4, text: "Nicht für Könige <ziemt es sich>, Lemuël, nicht für Könige, Wein zu trinken, noch für Fürsten <zu fragen>: Wo ist Rauschtrank*?", footnotes: ["℘ Kap. 23,34; 1Kö 16,9; 20,12; Est 1,10; 3,15; Pred 10,17"] },
      { number: 5, text: "Sonst trinkt einer und vergisst, was vorgeschrieben ist, und verändert den Rechtsanspruch aller Elenden*.* —", footnotes: ["w. aller Söhne des Elends", "℘ Jes 5,22.23"] },
      { number: 6, text: "Gebt Rauschtrank dem Mutlosen und Wein den Verbitterten*!*", footnotes: ["w. denen mit bitterer Seele", "℘ Mk 15,23"] },
      { number: 7, text: "Ein solcher mag trinken und seine Armut vergessen und an seine Mühsal nicht mehr denken.*", footnotes: ["℘ Ps 104,15"] },
      { number: 8, text: "Öffne deinen Mund für den Stummen, für den Rechtsanspruch aller Schwachen*!*", footnotes: ["o. aller Dahinschwindenden; w. aller Söhne des Vergehens", "℘ 1Sam 19,6; Hi 29,12"] },
      { number: 9, text: "Öffne deinen Mund, richte gerecht und schaffe Recht dem Elenden und Armen!*", footnotes: ["℘ Ps 82,3; Jer 21,12"] },
      { number: 10, text: "*Eine tüchtige Frau — wer findet sie?* Weit über Korallen geht ihr Wert*.*", footnotes: ["Die V. 10—31 sind ein Akrostichon, d. h., im Hebr. folgen die Anfangsbuchstaben der einzelnen Verse der alphabetischen Ordnung.", "℘ Kap. 18,22", "w. ihr Kaufpreis", "℘ Kap. 12,4"] },
      { number: 11, text: "Ihr vertraut das Herz ihres Mannes*, und an Ausbeute* wird es ihm nicht fehlen.", footnotes: ["w. ihres <Ehe>herrn", "nach anderen: an Nachkommen"] },
      { number: 12, text: "Sie erweist ihm Gutes und nichts Böses alle Tage ihres Lebens.*", footnotes: ["℘ Tit 1,4"] },
      { number: 13, text: "Sie kümmert sich um Wolle und Flachs und arbeitet dann mit Lust ihrer Hände*.", footnotes: ["o. was ihren Händen gefällt"] },
      { number: 14, text: "Sie gleicht Handelsschiffen, von weit her holt sie ihr Brot herbei.*", footnotes: ["℘ V. 27"] },
      { number: 15, text: "Und sie steht auf, wenn es noch Nacht ist, und gibt Speise ihrem Haus* und das Angemessene ihren Mägden.", footnotes: ["℘ Lk 12,42"] },
      { number: 16, text: "Sie hält Ausschau nach einem Feld und erwirbt es*; von der Frucht ihrer Hände pflanzt sie einen Weinberg.", footnotes: ["℘ Kap. 14,1"] },
      { number: 17, text: "Sie gürtet ihre Lenden* mit Kraft und macht ihre Arme stark.", footnotes: ["℘ Lk 12,35; 1Petr 1,13"] },
      { number: 18, text: "Sie merkt, dass ihr Erwerb gut ist; <auch> nachts erlischt ihre Lampe nicht." },
      { number: 19, text: "Sie streckt ihre Hände aus nach der Spinnrolle, und ihre Finger ergreifen die Spindel.*", footnotes: ["℘ 2Mo 35,25.26; Tit 2,5"] },
      { number: 20, text: "Ihre Hand öffnet sie dem Elenden und streckt ihre Hände dem Armen entgegen.*", footnotes: ["℘ Ps 41,2; Eph 4,28"] },
      { number: 21, text: "Nicht fürchtet sie für ihr Haus den Schnee, denn ihr ganzes Haus ist in Karmesin<stoff>e gekleidet*.*", footnotes: ["LXX und Vulg.: ist doppelt eingekleidet", "℘ Nah 2,4"] },
      { number: 22, text: "Decken macht sie sich; Byssus und roter Purpur sind ihr Gewand." },
      { number: 23, text: "Ihr Mann ist bekannt in den Toren*, wenn er Sitzung hält mit den Ältesten des Landes.", footnotes: ["℘ Kap. 24,7; Hi 29,7"] },
      { number: 24, text: "<Kostbare> Hemden macht sie* und verkauft sie, und Gürtel liefert sie dem Kaufmann*.", footnotes: ["℘ Apg 9,39", "o. dem Kanaanäer"] },
      { number: 25, text: "Kraft und Hoheit sind ihr Gewand, und <unbekümmert> lacht sie dem nächsten Tag zu." },
      { number: 26, text: "Ihren Mund öffnet sie mit Weisheit, und freundliche* Weisung ist auf ihrer Zunge.*", footnotes: ["o. gütige", "℘ Kap. 19,14; Eph 4,29; Tit 2,3"] },
      { number: 27, text: "Sie überwacht die Vorgänge in ihrem Haus*, und das Brot der Faulheit isst sie nicht*.", footnotes: ["℘ Tit 1,5", "℘ V. 14; 2Thes 3,10"] },
      { number: 28, text: "Es treten ihre Söhne auf und preisen sie glücklich, ihr Mann* <tritt auf> und rühmt sie:", footnotes: ["w. ihr <Ehe>herr"] },
      { number: 29, text: "Viele Töchter haben sich als tüchtig erwiesen*, du aber übertriffst sie alle!*", footnotes: ["℘ Rt 3,11", "℘ Kap. 12,4"] },
      { number: 30, text: "Trügerisch* ist Anmut und nichtig* die Schönheit*; eine Frau <aber>, die den HERRN fürchtet, die soll man rühmen*.", footnotes: ["w. Lüge", "w. ein Windhauch", "℘ Kap. 11,22", "℘ 1Petr 3,4.5"] },
      { number: 31, text: "Gebt ihr von der Frucht ihrer Hände, und in den Toren sollen ihre Werke sie rühmen!" },
    ]},
  ]
};
